window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[913]={"91300":{"example:91300:exzh":"I watch a movie once a month.","example:91300:exzh2":"It's been a month since I came to Japan.","grammar:91300:ex:trans":"I watch a movie once a month.","grammar:91300:ex:structure":"〔period〕に＋〔number of times〕＋〔action〕","grammar:91300:ex:explain":"「ひと月」 is the native Japanese way of saying one month; in kanji it is written 「一月」, but to keep it distinct from 「一月（いちがつ, January）」 it is often written 「ひと月」. The pattern for frequency is 〔period〕＋に＋〔number of times〕, here 「ひと月に一回」.","grammar:91300:ex:words:0:zh":"one month","grammar:91300:ex:words:0:note":"ひとつき","grammar:91300:ex:words:0:pos":"noun","grammar:91300:ex:words:1:zh":"(within ～, expressing frequency)","grammar:91300:ex:words:1:pos":"particle","grammar:91300:ex:words:2:zh":"once","grammar:91300:ex:words:2:note":"いっかい","grammar:91300:ex:words:2:pos":"numeral with counter","grammar:91300:ex:words:3:zh":"movie","grammar:91300:ex:words:3:note":"えいが","grammar:91300:ex:words:3:pos":"noun","grammar:91300:ex:words:4:zh":"(object marker)","grammar:91300:ex:words:4:pos":"particle","grammar:91300:ex:words:5:zh":"look","grammar:91300:ex:words:5:note":"みます; the masu-form of 見る","grammar:91300:ex:words:5:pos":"verb","grammar:91300:ex:points:0":"ひと月＝one month; same meaning as 「一か月（いっかげつ）」 but more casual and softer","grammar:91300:ex:points:1":"〔period〕に〔number of times〕＝frequency: ひと月に一回＝once a month","grammar:91300:ex2:trans":"It has been a month since I came to Japan.","grammar:91300:ex2:structure":"〔verb te-form〕＋〔period〕になります","grammar:91300:ex2:words:0:zh":"Japan","grammar:91300:ex2:words:0:note":"にほん","grammar:91300:ex2:words:0:pos":"noun","grammar:91300:ex2:words:1:zh":"(destination)","grammar:91300:ex2:words:1:pos":"particle","grammar:91300:ex2:words:2:zh":"come","grammar:91300:ex2:words:2:note":"きて; the te-form of 来る","grammar:91300:ex2:words:2:pos":"verb","grammar:91300:ex2:words:3:zh":"one month","grammar:91300:ex2:words:3:note":"ひとつき","grammar:91300:ex2:words:3:pos":"noun","grammar:91300:ex2:words:4:zh":"(to become ～)","grammar:91300:ex2:words:4:pos":"particle","grammar:91300:ex2:words:5:zh":"became, reached","grammar:91300:ex2:words:5:note":"; the masu-form of なる","grammar:91300:ex2:words:5:pos":"verb","grammar:91300:ex2:points:0":"〜てひと月になります＝it has been a full month since doing ～","grammar:91300:ex2:points:1":"verb te-form + time + になる: shows how much time has passed since then","exam:91300:zh":"From June 1st to June 30th — the whole of June, from the beginning of the month to the end — I stayed in this town.","exam:91300:why":"「ひと月」 means one month, which fits the period from the start of June to the end. 「一週間」 is only one week, which is too short."},"91301":{"example:91301:exzh":"This pen is a hundred yen.","example:91301:exzh2":"A hundred students came.","grammar:91301:ex:trans":"This pen is one hundred yen.","grammar:91301:ex:structure":"〔thing〕は＋〔amount〕です","grammar:91301:ex:words:0:zh":"this","grammar:91301:ex:words:0:pos":"pre-noun adjectival","grammar:91301:ex:words:1:zh":"pen","grammar:91301:ex:words:1:pos":"noun","grammar:91301:ex:words:2:zh":"(topic)","grammar:91301:ex:words:2:pos":"particle","grammar:91301:ex:words:3:zh":"One hundred","grammar:91301:ex:words:3:note":"ひゃく","grammar:91301:ex:words:3:pos":"numeral","grammar:91301:ex:words:4:zh":"yen","grammar:91301:ex:words:4:note":"えん","grammar:91301:ex:words:4:pos":"suffix","grammar:91301:ex:words:5:zh":"is (polite form)","grammar:91301:ex:words:5:pos":"copula","grammar:91301:ex:points:0":"百＝one hundred; in Japanese you just say 「百」, not 「一百」","grammar:91301:ex2:trans":"One hundred students came.","grammar:91301:ex2:structure":"〔number〕の＋〔noun〕が来ました","grammar:91301:ex2:words:0:zh":"One hundred","grammar:91301:ex2:words:0:note":"ひゃく","grammar:91301:ex2:words:0:pos":"numeral","grammar:91301:ex2:words:1:zh":"(number of people) ～ people","grammar:91301:ex2:words:1:note":"にん","grammar:91301:ex2:words:1:pos":"suffix","grammar:91301:ex2:words:2:zh":"'s","grammar:91301:ex2:words:2:pos":"particle","grammar:91301:ex2:words:3:zh":"student","grammar:91301:ex2:words:3:note":"がくせい","grammar:91301:ex2:words:3:pos":"noun","grammar:91301:ex2:words:4:zh":"(nominative)","grammar:91301:ex2:words:4:pos":"particle","grammar:91301:ex2:words:5:zh":"came","grammar:91301:ex2:words:5:note":"きました; the past form of 来る","grammar:91301:ex2:words:5:pos":"verb","grammar:91301:ex2:points:0":"百人＝one hundred people; people are counted with 「〜人（にん）」, but one person and two people are ひとり and ふたり","grammar:91301:ex2:points:1":"A quantity can also take 「の」 and come before a noun: 百人の学生","exam:91301:zh":"If you buy two 50-yen stamps, the total is 100 yen.","exam:91301:why":"「百」 means one hundred, and 50 yen times two is 100 yen. 「二百」 is two hundred, which is more than the total in the question."},"91302":{"example:91302:exzh":"Please write your name in hiragana.","example:91302:exzh2":"The child can already read hiragana.","grammar:91302:ex:trans":"Please write your name in hiragana.","grammar:91302:ex:structure":"〔script〕で＋〔thing〕を書いてください","grammar:91302:ex:explain":"「ひらがな」 is the most basic Japanese script, and it is what children learn first. On forms you are often asked to write the reading of your name in hiragana above it. The pattern 「〜で書いてください」 means please write in ～.","grammar:91302:ex:words:0:zh":"hiragana","grammar:91302:ex:words:0:pos":"noun","grammar:91302:ex:words:1:zh":"(means, method)","grammar:91302:ex:words:1:pos":"particle","grammar:91302:ex:words:2:zh":"name","grammar:91302:ex:words:2:note":"なまえ","grammar:91302:ex:words:2:pos":"noun","grammar:91302:ex:words:3:zh":"(object marker)","grammar:91302:ex:words:3:pos":"particle","grammar:91302:ex:words:4:zh":"write","grammar:91302:ex:words:4:note":"かいて；the te-form of 書く","grammar:91302:ex:words:4:pos":"verb","grammar:91302:ex:words:5:zh":"please (do ～)","grammar:91302:ex:words:5:pos":"auxiliary verb","grammar:91302:ex:points:0":"ひらがな＝hiragana, the most basic Japanese script; katakana is 「カタカナ」","grammar:91302:ex:points:1":"Add 「で」 to the script you write with: ひらがなで書く","grammar:91302:ex2:trans":"My child can already read hiragana.","grammar:91302:ex2:structure":"〔person〕は＋もう＋〔thing〕が〔potential form〕","grammar:91302:ex2:words:0:zh":"child","grammar:91302:ex2:words:0:note":"こども","grammar:91302:ex2:words:0:pos":"noun","grammar:91302:ex2:words:1:zh":"(topic)","grammar:91302:ex2:words:1:pos":"particle","grammar:91302:ex2:words:2:zh":"already","grammar:91302:ex2:words:2:pos":"adverb","grammar:91302:ex2:words:3:zh":"hiragana","grammar:91302:ex2:words:3:pos":"noun","grammar:91302:ex2:words:4:zh":"(nominative)","grammar:91302:ex2:words:4:pos":"particle","grammar:91302:ex2:words:5:zh":"can read; is able to read","grammar:91302:ex2:words:5:note":"よめます; the potential form of 読む","grammar:91302:ex2:words:5:pos":"verb","grammar:91302:ex2:points:0":"もう＝already; 「もう読めます」＝can already read","grammar:91302:ex2:points:1":"読める＝can read (the potential form of 読む); what one is able to do often takes 「が」","exam:91302:zh":"「あ・い・う・え・お」 are hiragana, not kanji and not katakana.","exam:91302:why":"「あ・い・う・え・お」 are 「ひらがな」. The corresponding 「カタカナ」 are written 「ア・イ・ウ・エ・オ」."},"91303":{"example:91303:exzh":"Would you like to have lunch together?","example:91303:exzh2":"Today's lunch was ramen.","grammar:91303:ex:trans":"Shall we have lunch together?","grammar:91303:ex:structure":"〔noun〕を一緒に＋〜ませんか","grammar:91303:ex:explain":"「昼ご飯」 means lunch, and colleagues often say 「お昼、行きませんか」. This sentence invites someone with 「〜ませんか」; even though the form is negative, it means shall we ～ together, and it is more polite than saying 「食べましょう」 outright because it leaves the other person room to say no.","grammar:91303:ex:words:0:zh":"lunch","grammar:91303:ex:words:0:note":"ひるごはん","grammar:91303:ex:words:0:pos":"noun","grammar:91303:ex:words:1:zh":"(object marker)","grammar:91303:ex:words:1:pos":"particle","grammar:91303:ex:words:2:zh":"together","grammar:91303:ex:words:2:note":"いっしょ","grammar:91303:ex:words:2:pos":"noun","grammar:91303:ex:words:3:zh":"(made adverbial)","grammar:91303:ex:words:3:pos":"particle","grammar:91303:ex:words:4:zh":"(does not) eat","grammar:91303:ex:words:4:note":"たべません; the negative of 食べる","grammar:91303:ex:words:4:pos":"verb","grammar:91303:ex:words:5:zh":"(question)","grammar:91303:ex:words:5:pos":"particle","grammar:91303:ex:points:0":"昼ご飯＝lunch; you can also simply say 「お昼」","grammar:91303:ex:points:1":"〜ませんか＝shall we ～? A negative question used as a polite invitation","grammar:91303:ex2:trans":"Today's lunch was ramen.","grammar:91303:ex2:structure":"〔noun〕は＋〔noun〕でした","grammar:91303:ex2:words:0:zh":"today","grammar:91303:ex2:words:0:note":"きょう","grammar:91303:ex2:words:0:pos":"noun","grammar:91303:ex2:words:1:zh":"'s","grammar:91303:ex2:words:1:pos":"particle","grammar:91303:ex2:words:2:zh":"lunch","grammar:91303:ex2:words:2:note":"ひるごはん","grammar:91303:ex2:words:2:pos":"noun","grammar:91303:ex2:words:3:zh":"(topic)","grammar:91303:ex2:words:3:pos":"particle","grammar:91303:ex2:words:4:zh":"ramen","grammar:91303:ex2:words:4:pos":"noun","grammar:91303:ex2:words:5:zh":"was (past, polite)","grammar:91303:ex2:words:5:pos":"copula","grammar:91303:ex2:points:0":"今日の昼ご飯＝today's lunch","grammar:91303:ex2:points:1":"It has already been eaten, so the past form 「でした」 is used"},"91304":{"example:91304:exzh":"I put the letter in the envelope.","example:91304:exzh2":"Please give me a brown envelope.","grammar:91304:ex:trans":"I put the letter in the envelope.","grammar:91304:ex:structure":"〔thing〕を＋〔container〕に入れます","grammar:91304:ex:explain":"「封筒」 means envelope, read 「ふうとう」. The pattern 「〜を〜に入れる」 means to put something in; this sentence puts the thing first (手紙を) and then the place (封筒に), and the two particles can also be swapped.","grammar:91304:ex:words:0:zh":"letter","grammar:91304:ex:words:0:note":"てがみ","grammar:91304:ex:words:0:pos":"noun","grammar:91304:ex:words:1:zh":"(object marker)","grammar:91304:ex:words:1:pos":"particle","grammar:91304:ex:words:2:zh":"envelope","grammar:91304:ex:words:2:note":"ふうとう","grammar:91304:ex:words:2:pos":"noun","grammar:91304:ex:words:3:zh":"(the place it goes into)","grammar:91304:ex:words:3:pos":"particle","grammar:91304:ex:words:4:zh":"put in","grammar:91304:ex:words:4:note":"いれます; the masu-form of 入れる","grammar:91304:ex:words:4:pos":"verb","grammar:91304:ex:points:0":"封筒＝envelope; 「封筒に入れる」＝put in an envelope","grammar:91304:ex:points:1":"The place you put something into takes 「に」, and the thing you put takes 「を」","grammar:91304:ex2:trans":"A brown envelope, please.","grammar:91304:ex2:structure":"〔adjective〕＋〔noun〕を＋ください","grammar:91304:ex2:words:0:zh":"brown","grammar:91304:ex2:words:0:note":"ちゃいろい","grammar:91304:ex2:words:0:pos":"adjective","grammar:91304:ex2:words:1:zh":"envelope","grammar:91304:ex2:words:1:note":"ふうとう","grammar:91304:ex2:words:1:pos":"noun","grammar:91304:ex2:words:2:zh":"(object marker)","grammar:91304:ex2:words:2:pos":"particle","grammar:91304:ex2:words:3:zh":"please (do ～)","grammar:91304:ex2:words:3:pos":"auxiliary verb","grammar:91304:ex2:points:0":"茶色い封筒＝a brown envelope (the kraft envelopes commonly used in Japanese offices look like this)","grammar:91304:ex2:points:1":"茶色い is the adjective form of 「茶色」 (brown) and goes directly before a noun","exam:91304:zh":"I put the letter I had written into the envelope, sealed the opening, and then wrote the address.","exam:91304:why":"A 「封筒」 holds a letter and can be sealed. A 「はがき」 is a card you write on and send directly, and you can't put a letter inside it."},"91305":{"example:91305:exzh":"Please give me two apples.","example:91305:exzh2":"There are two bags.","grammar:91305:ex:trans":"Two apples, please.","grammar:91305:ex:structure":"〔thing〕を＋二つ＋ください","grammar:91305:ex:explain":"「二つ」 is read 「ふたつ」 and is the second of the native Japanese counting words. When shopping, the simplest form is 「〔thing〕を〔quantity〕ください」. Note that two people is 「二人（ふたり）」, not 「二つ」.","grammar:91305:ex:words:0:zh":"apple","grammar:91305:ex:words:0:pos":"noun","grammar:91305:ex:words:1:zh":"(object marker)","grammar:91305:ex:words:1:pos":"particle","grammar:91305:ex:words:2:zh":"two","grammar:91305:ex:words:2:note":"ふたつ","grammar:91305:ex:words:2:pos":"numeral with counter","grammar:91305:ex:words:3:zh":"please (do ～)","grammar:91305:ex:words:3:pos":"auxiliary verb","grammar:91305:ex:points:0":"二つ＝two; read ふたつ","grammar:91305:ex:points:1":"The counter goes directly before 「ください」","grammar:91305:ex2:trans":"There are two bags.","grammar:91305:ex2:structure":"〔thing〕が＋二つあります","grammar:91305:ex2:words:0:zh":"bag","grammar:91305:ex2:words:0:pos":"noun","grammar:91305:ex2:words:1:zh":"(nominative)","grammar:91305:ex2:words:1:pos":"particle","grammar:91305:ex2:words:2:zh":"two","grammar:91305:ex2:words:2:note":"ふたつ","grammar:91305:ex2:words:2:pos":"numeral with counter","grammar:91305:ex2:words:3:zh":"there is / are","grammar:91305:ex2:words:3:note":"; the masu-form of ある","grammar:91305:ex2:words:3:pos":"verb","grammar:91305:ex2:points:0":"二つ＋あります: the quantity goes before the verb","grammar:91305:ex2:points:1":"Bags are things, so 「あります」 is used","exam:91305:zh":"There were five oranges in the box, and after eating three, there are two left now.","exam:91305:why":"「二つ」 means two, and five minus three is two. 「三つ」 is how many you ate, not how many are left now."},"91306":{"example:91306:exzh":"I bought pork at the supermarket.","example:91306:exzh2":"I grill the pork and vegetables together.","grammar:91306:ex:trans":"I bought pork at the supermarket.","grammar:91306:ex:structure":"〔place〕で＋〔thing〕を買いました","grammar:91306:ex:words:0:zh":"supermarket","grammar:91306:ex:words:0:pos":"noun","grammar:91306:ex:words:1:zh":"(place of the action)","grammar:91306:ex:words:1:pos":"particle","grammar:91306:ex:words:2:zh":"pork","grammar:91306:ex:words:2:note":"ぶたにく","grammar:91306:ex:words:2:pos":"noun","grammar:91306:ex:words:3:zh":"(object marker)","grammar:91306:ex:words:3:pos":"particle","grammar:91306:ex:words:4:zh":"bought","grammar:91306:ex:words:4:note":"かいました; the past tense of 買う","grammar:91306:ex:words:4:pos":"verb","grammar:91306:ex:points:1":"The place where you buy something takes 「で」","grammar:91306:ex2:trans":"I grill the pork and the vegetables together.","grammar:91306:ex2:structure":"AとBを＋一緒に＋〔action〕","grammar:91306:ex2:words:0:zh":"pork","grammar:91306:ex2:words:0:note":"ぶたにく","grammar:91306:ex2:words:0:pos":"noun","grammar:91306:ex2:words:1:zh":"with","grammar:91306:ex2:words:1:pos":"particle","grammar:91306:ex2:words:2:zh":"vegetables","grammar:91306:ex2:words:2:note":"やさい","grammar:91306:ex2:words:2:pos":"noun","grammar:91306:ex2:words:3:zh":"(object marker)","grammar:91306:ex2:words:3:pos":"particle","grammar:91306:ex2:words:4:zh":"together","grammar:91306:ex2:words:4:note":"いっしょ","grammar:91306:ex2:words:4:pos":"noun","grammar:91306:ex2:words:5:zh":"(made adverbial)","grammar:91306:ex2:words:5:pos":"particle","grammar:91306:ex2:words:6:zh":"pan-fry, grill","grammar:91306:ex2:words:6:note":"やきます; the masu-form of 焼く","grammar:91306:ex2:words:6:pos":"verb","grammar:91306:ex2:points:0":"豚肉と野菜＝pork and vegetables; 「と」 joins two nouns","grammar:91306:ex2:points:1":"焼く＝grill, bake, or burn; frying in a frying pan is also 「焼く」","exam:91306:zh":"We're using pork, not beef, so please go to the shop and buy some pork.","exam:91306:why":"Pork is called 「豚肉」. 「牛肉」 is beef, which the sentence clearly rules out."},"91307":{"example:91307:exzh":"March 2nd is my birthday.","example:91307:exzh2":"I traveled around Kyoto for two days.","grammar:91307:ex:trans":"March 2nd is my birthday.","grammar:91307:ex:structure":"〔date〕は＋私の誕生日です","grammar:91307:ex:explain":"「二日」 is read 「ふつか」; here it means the 2nd of the month. The 1st through the 10th of the month all have special readings, and 「二日」 is one of them. 「三月」 is read 「さんがつ」; months generally follow the regular numbers.","grammar:91307:ex:words:0:zh":"March","grammar:91307:ex:words:0:note":"さんがつ","grammar:91307:ex:words:0:pos":"noun","grammar:91307:ex:words:1:zh":"the 2nd","grammar:91307:ex:words:1:note":"ふつか","grammar:91307:ex:words:1:pos":"noun","grammar:91307:ex:words:2:zh":"(topic)","grammar:91307:ex:words:2:pos":"particle","grammar:91307:ex:words:3:zh":"I","grammar:91307:ex:words:3:note":"わたし","grammar:91307:ex:words:3:pos":"pronoun","grammar:91307:ex:words:4:zh":"'s","grammar:91307:ex:words:4:pos":"particle","grammar:91307:ex:words:5:zh":"birthday","grammar:91307:ex:words:5:note":"たんじょうび","grammar:91307:ex:words:5:pos":"noun","grammar:91307:ex:words:6:zh":"is (polite form)","grammar:91307:ex:words:6:pos":"copula","grammar:91307:ex:points:0":"二日 is read ふつか and means both the 2nd of the month and two days","grammar:91307:ex:points:1":"Readings for dates: ついたち、ふつか、みっか、よっか、いつか……","grammar:91307:ex2:trans":"I traveled around Kyoto for two days.","grammar:91307:ex2:structure":"〔number of days〕間、〔place〕を旅行しました","grammar:91307:ex2:words:0:zh":"two days","grammar:91307:ex2:words:0:note":"ふつか","grammar:91307:ex2:words:0:pos":"noun","grammar:91307:ex2:words:1:zh":"period, duration","grammar:91307:ex2:words:1:note":"かん","grammar:91307:ex2:words:1:pos":"suffix","grammar:91307:ex2:words:2:zh":"Kyoto","grammar:91307:ex2:words:2:note":"きょうと","grammar:91307:ex2:words:2:pos":"noun","grammar:91307:ex2:words:3:zh":"(the area passed through or moved around)","grammar:91307:ex2:words:3:pos":"particle","grammar:91307:ex2:words:4:zh":"traveled","grammar:91307:ex2:words:4:note":"りょこうしました；旅行する的過去式","grammar:91307:ex2:words:4:pos":"verb","grammar:91307:ex2:points:0":"二日間＝two days (a period of time)","grammar:91307:ex2:points:1":"Use 「を」 for traveling around a place: 京都を旅行する","exam:91307:zh":"Today is May 1st, so tomorrow is May 2nd.","exam:91307:why":"「二日」 means the second of the month and is the day after May 1st. 「三日」 is the 3rd, which isn't until the day after tomorrow."},"91308":{"example:91308:exzh":"I study Japanese every night.","example:91308:exzh2":"Let's study at the library.","grammar:91308:ex:trans":"I study Japanese every evening.","grammar:91308:ex:structure":"〔thing〕を＋勉強します","grammar:91308:ex:explain":"「勉強」 is a noun, and adding 「する」 makes it the verb 「勉強する」 (to study). This is one of the words Chinese speakers most often misunderstand: Japanese 「勉強」 means studying or hitting the books, while the Chinese meaning of 'to force oneself' is 「無理（むり）」 in Japanese.","grammar:91308:ex:words:0:zh":"every night","grammar:91308:ex:words:0:note":"まいばん","grammar:91308:ex:words:0:pos":"noun","grammar:91308:ex:words:1:zh":"Japanese","grammar:91308:ex:words:1:note":"にほんご","grammar:91308:ex:words:1:pos":"noun","grammar:91308:ex:words:2:zh":"(object marker)","grammar:91308:ex:words:2:pos":"particle","grammar:91308:ex:words:3:zh":"study","grammar:91308:ex:words:3:note":"べんきょう","grammar:91308:ex:words:3:pos":"noun","grammar:91308:ex:words:4:zh":"do","grammar:91308:ex:words:4:note":"; the masu-form of する","grammar:91308:ex:words:4:pos":"verb","grammar:91308:ex:points:0":"勉強＝studying, hitting the books; 「勉強する」 is a verb, and what you study takes 「を」","grammar:91308:ex:points:1":"Japanese 「勉強」 does not mean 'reluctant' the way the same characters do in Chinese, so don't read it literally","grammar:91308:ex2:trans":"Let's study at the library.","grammar:91308:ex2:structure":"〔place〕で＋勉強しましょう","grammar:91308:ex2:words:0:zh":"library","grammar:91308:ex2:words:0:note":"としょかん","grammar:91308:ex2:words:0:pos":"noun","grammar:91308:ex2:words:1:zh":"(place of the action)","grammar:91308:ex2:words:1:pos":"particle","grammar:91308:ex2:words:2:zh":"to study","grammar:91308:ex2:words:2:note":"べんきょう","grammar:91308:ex2:words:2:pos":"noun","grammar:91308:ex2:words:3:zh":"let's do ～","grammar:91308:ex2:words:3:note":"; the volitional form of する","grammar:91308:ex2:words:3:pos":"verb","grammar:91308:ex2:points:0":"勉強しましょう＝let's study together; 〜ましょう is an invitation","grammar:91308:ex2:points:1":"The place where you study takes 「で」","exam:91308:zh":"I want to get a good score on tomorrow's Japanese test, so tonight I'll open my textbook and study.","exam:91308:why":"「勉強をする」 means to study, which fits preparing for a test. 「買い物」 means shopping, which doesn't fit opening a textbook to prepare for a test."},"91309":{"example:91309:exzh":"Please write your name with a ballpoint pen.","example:91309:exzh2":"This ballpoint pen is 100 yen.","grammar:91309:ex:trans":"Please write your name with a ballpoint pen.","grammar:91309:ex:structure":"〔tool〕で＋〔thing〕を書いてください","grammar:91309:ex:explain":"「ボールペン」 is a ballpoint pen, a loanword from English 'ball pen'. Official documents often require 「ボールペンで書いてください」 because pencil can be erased. The tool takes 「で」.","grammar:91309:ex:words:0:zh":"ballpoint pen","grammar:91309:ex:words:0:pos":"noun","grammar:91309:ex:words:1:zh":"(means, tool)","grammar:91309:ex:words:1:pos":"particle","grammar:91309:ex:words:2:zh":"name","grammar:91309:ex:words:2:note":"なまえ","grammar:91309:ex:words:2:pos":"noun","grammar:91309:ex:words:3:zh":"(object marker)","grammar:91309:ex:words:3:pos":"particle","grammar:91309:ex:words:4:zh":"write","grammar:91309:ex:words:4:note":"かいて；the te-form of 書く","grammar:91309:ex:words:4:pos":"verb","grammar:91309:ex:words:5:zh":"please (do ～)","grammar:91309:ex:words:5:pos":"auxiliary verb","grammar:91309:ex:points:0":"ボールペン＝ballpoint pen; pencil is 「鉛筆（えんぴつ）」","grammar:91309:ex:points:1":"Add 「で」 to what you write with: ボールペンで書く","grammar:91309:ex2:trans":"This ballpoint pen is one hundred yen.","grammar:91309:ex2:structure":"〔thing〕は＋〔amount〕です","grammar:91309:ex2:words:0:zh":"this","grammar:91309:ex2:words:0:pos":"pre-noun adjectival","grammar:91309:ex2:words:1:zh":"ballpoint pen","grammar:91309:ex2:words:1:pos":"noun","grammar:91309:ex2:words:2:zh":"(topic)","grammar:91309:ex2:words:2:pos":"particle","grammar:91309:ex2:words:3:zh":"One hundred","grammar:91309:ex2:words:3:note":"ひゃく","grammar:91309:ex2:words:3:pos":"numeral","grammar:91309:ex2:words:4:zh":"yen","grammar:91309:ex2:words:4:note":"えん","grammar:91309:ex2:words:4:pos":"suffix","grammar:91309:ex2:words:5:zh":"is (polite form)","grammar:91309:ex2:words:5:pos":"copula","grammar:91309:ex2:points:1":"Talking about price: 〜は〜円です","exam:91309:zh":"I wrote my name in my notebook with a ballpoint pen, which writes in ink unlike a pencil.","exam:91309:why":"「ボールペン」 writes with ink and matches the description in the sentence. 「鉛筆」 can write too, but it uses graphite, not ink."},"91310":{"example:91310:exzh":"Please press this red button.","example:91310:exzh2":"The button on the shirt came off.","grammar:91310:ex:trans":"Please press this red button.","grammar:91310:ex:structure":"〔thing〕を＋押してください","grammar:91310:ex:explain":"「ボタン」 has two meanings: a button on a machine and a button on clothing. Pressing a button is 「押す」. In 「この赤いボタン」 a demonstrative and an adjective both modify the noun, in the same order as in Chinese.","grammar:91310:ex:words:0:zh":"this","grammar:91310:ex:words:0:pos":"pre-noun adjectival","grammar:91310:ex:words:1:zh":"red","grammar:91310:ex:words:1:note":"あかい","grammar:91310:ex:words:1:pos":"adjective","grammar:91310:ex:words:2:zh":"button","grammar:91310:ex:words:2:pos":"noun","grammar:91310:ex:words:3:zh":"(object marker)","grammar:91310:ex:words:3:pos":"particle","grammar:91310:ex:words:4:zh":"press","grammar:91310:ex:words:4:note":"おして; the te-form of 押す","grammar:91310:ex:words:4:pos":"verb","grammar:91310:ex:words:5:zh":"please (do ～)","grammar:91310:ex:words:5:pos":"auxiliary verb","grammar:91310:ex:points:0":"ボタンを押す＝press a button; a fixed collocation","grammar:91310:ex:points:1":"この＋adjective＋noun: この赤いボタン","grammar:91310:ex2:trans":"A shirt button came off.","grammar:91310:ex2:structure":"〔thing〕が＋取れました","grammar:91310:ex2:words:0:zh":"shirt","grammar:91310:ex2:words:0:pos":"noun","grammar:91310:ex2:words:1:zh":"'s","grammar:91310:ex2:words:1:pos":"particle","grammar:91310:ex2:words:2:zh":"button","grammar:91310:ex2:words:2:pos":"noun","grammar:91310:ex2:words:3:zh":"(nominative)","grammar:91310:ex2:words:3:pos":"particle","grammar:91310:ex2:words:4:zh":"came off","grammar:91310:ex2:words:4:note":"とれました; the past form of 取れる","grammar:91310:ex2:words:4:pos":"verb","grammar:91310:ex2:points:0":"Here ボタン means a button on clothing","grammar:91310:ex2:points:1":"取れる＝come off (something attached); it came off by itself, so 「が」 is used","exam:91310:zh":"To take the elevator to the third floor, I pressed the button marked 「3」.","exam:91310:why":"「ボタンを押す」 is the natural way to say pressing a button. A 「電池」 supplies power; it isn't the part you operate to choose a floor."},"91311":{"example:91311:exzh":"There is a dictionary on the bookshelf.","example:91311:exzh2":"I bought a new bookshelf.","grammar:91311:ex:trans":"There is a dictionary on the bookshelf.","grammar:91311:ex:structure":"〔place〕に＋〔thing〕があります","grammar:91311:ex:explain":"「本棚」 is a shelf for books, and 「棚（たな）」 becomes 「だな」 when it follows another word. The pattern 「〔place〕に〔thing〕があります」 says where something is. 「本棚に」 can also be said more specifically as 「本棚の上に」.","grammar:91311:ex:words:0:zh":"bookshelf","grammar:91311:ex:words:0:note":"ほんだな","grammar:91311:ex:words:0:pos":"noun","grammar:91311:ex:words:1:zh":"（place of existence）","grammar:91311:ex:words:1:pos":"particle","grammar:91311:ex:words:2:zh":"dictionary","grammar:91311:ex:words:2:note":"じしょ","grammar:91311:ex:words:2:pos":"noun","grammar:91311:ex:words:3:zh":"(nominative)","grammar:91311:ex:words:3:pos":"particle","grammar:91311:ex:words:4:zh":"there is / are","grammar:91311:ex:words:4:note":"; the masu-form of ある","grammar:91311:ex:words:4:pos":"verb","grammar:91311:ex:points:0":"本棚＝bookshelf, bookcase (本＋棚); 棚 alone is read たな, but becomes だな when it follows another word","grammar:91311:ex:points:1":"Something exists somewhere: 〜に〜があります","grammar:91311:ex2:trans":"I bought a new bookshelf.","grammar:91311:ex2:structure":"新しい＋〔noun〕を買いました","grammar:91311:ex2:words:0:zh":"new","grammar:91311:ex2:words:0:note":"あたらしい","grammar:91311:ex2:words:0:pos":"adjective","grammar:91311:ex2:words:1:zh":"bookshelf","grammar:91311:ex2:words:1:note":"ほんだな","grammar:91311:ex2:words:1:pos":"noun","grammar:91311:ex2:words:2:zh":"(object marker)","grammar:91311:ex2:words:2:pos":"particle","grammar:91311:ex2:words:3:zh":"bought","grammar:91311:ex2:words:3:note":"かいました; the past tense of 買う","grammar:91311:ex2:words:3:pos":"verb","grammar:91311:ex2:points:0":"本棚 can mean either a shelf or a bookcase","grammar:91311:ex2:points:1":"新しい + noun: an i-adjective modifies the noun directly","exam:91311:zh":"Since my books had increased, I bought a bookshelf with three tiers where I can stand books up in rows.","exam:91311:why":"「本棚」 is a shelf or cabinet for arranging and storing books. 「机」 is a desk, which doesn't fit the description of a three-tier bookshelf."},"91312":{"example:91312:exzh":"I get up at seven every day.","example:91312:exzh2":"My older brother takes the train to the office every day.","grammar:91312:ex:trans":"I get up at seven every day.","grammar:91312:ex:structure":"毎日、〔time〕に＋〔action〕","grammar:91312:ex:explain":"「毎日」 means every day and describes a habit or routine. Words like 「毎日、毎朝、毎週」 (every ～) do not take 「に」, but a specific time like 「七時」 does. 「起きます」＝get up.","grammar:91312:ex:words:0:zh":"every day","grammar:91312:ex:words:0:note":"まいにち","grammar:91312:ex:words:0:pos":"noun","grammar:91312:ex:words:1:zh":"seven o'clock","grammar:91312:ex:words:1:note":"しちじ","grammar:91312:ex:words:1:pos":"noun","grammar:91312:ex:words:2:zh":"(point in time)","grammar:91312:ex:words:2:pos":"particle","grammar:91312:ex:words:3:zh":"to get up","grammar:91312:ex:words:3:note":"おきます; the masu-form of 起きる","grammar:91312:ex:words:3:pos":"verb","grammar:91312:ex:points:0":"毎日＝every day; no 「に」 is needed after it","grammar:91312:ex:points:1":"A specific time such as 「七時」 takes 「に」","grammar:91312:ex2:trans":"My older brother goes to work by train every day.","grammar:91312:ex2:structure":"〔person〕は＋毎日＋〔means of transport〕で＋〔place〕に行きます","grammar:91312:ex2:words:0:zh":"(my) older brother","grammar:91312:ex2:words:0:note":"あに","grammar:91312:ex2:words:0:pos":"noun","grammar:91312:ex2:words:1:zh":"(topic)","grammar:91312:ex2:words:1:pos":"particle","grammar:91312:ex2:words:2:zh":"every day","grammar:91312:ex2:words:2:note":"まいにち","grammar:91312:ex2:words:2:pos":"noun","grammar:91312:ex2:words:3:zh":"train","grammar:91312:ex2:words:3:note":"でんしゃ","grammar:91312:ex2:words:3:pos":"noun","grammar:91312:ex2:words:4:zh":"(means of transport)","grammar:91312:ex2:words:4:pos":"particle","grammar:91312:ex2:words:5:zh":"company","grammar:91312:ex2:words:5:note":"かいしゃ","grammar:91312:ex2:words:5:pos":"noun","grammar:91312:ex2:words:6:zh":"(destination)","grammar:91312:ex2:words:6:pos":"particle","grammar:91312:ex2:words:7:zh":"go","grammar:91312:ex2:words:7:note":"いきます; masu-form of 行く","grammar:91312:ex2:words:7:pos":"verb","grammar:91312:ex2:points:0":"毎日 can go anywhere before the verb","grammar:91312:ex2:points:1":"The means of transport takes 「で」, and the destination takes 「に」 or 「へ」","exam:91312:zh":"From Monday to Sunday, without a single day off, I study Japanese every day.","exam:91312:why":"「毎日」 means every day, which fits doing it all week without a single break. 「毎週」 only means doing it every week, and can't express doing it every day."},"91313":{"example:91313:exzh":"I go to the beach every summer.","example:91313:exzh2":"This festival is held every April.","grammar:91313:ex:trans":"I go to the sea every summer.","grammar:91313:ex:structure":"毎年、〔season〕に＋〔action〕","grammar:91313:ex:explain":"「毎年」 has two readings: 「まいとし」 is more casual and 「まいねん」 is more formal; both are correct. This sentence describes a fixed yearly habit. The 「に」 in 「夏に」 is also often dropped.","grammar:91313:ex:words:0:zh":"every year","grammar:91313:ex:words:0:note":"まいとし","grammar:91313:ex:words:0:pos":"noun","grammar:91313:ex:words:1:zh":"summer","grammar:91313:ex:words:1:note":"なつ","grammar:91313:ex:words:1:pos":"noun","grammar:91313:ex:words:2:zh":"(point in time)","grammar:91313:ex:words:2:pos":"particle","grammar:91313:ex:words:3:zh":"seaside","grammar:91313:ex:words:3:note":"うみ","grammar:91313:ex:words:3:pos":"noun","grammar:91313:ex:words:4:zh":"(direction)","grammar:91313:ex:words:4:pos":"particle","grammar:91313:ex:words:5:zh":"go","grammar:91313:ex:words:5:note":"いきます; masu-form of 行く","grammar:91313:ex:words:5:pos":"verb","grammar:91313:ex:points:0":"毎年＝every year; read either まいとし or まいねん, same meaning","grammar:91313:ex:points:1":"No 「に」 is needed after 毎年","grammar:91313:ex2:trans":"This festival is held every April.","grammar:91313:ex2:structure":"〔event〕は＋毎年〔time〕にあります","grammar:91313:ex2:words:0:zh":"this","grammar:91313:ex2:words:0:pos":"pre-noun adjectival","grammar:91313:ex2:words:1:zh":"festival","grammar:91313:ex2:words:1:note":"まつり","grammar:91313:ex2:words:1:pos":"noun","grammar:91313:ex2:words:2:zh":"(topic)","grammar:91313:ex2:words:2:pos":"particle","grammar:91313:ex2:words:3:zh":"every year","grammar:91313:ex2:words:3:note":"まいとし","grammar:91313:ex2:words:3:pos":"noun","grammar:91313:ex2:words:4:zh":"April","grammar:91313:ex2:words:4:note":"しがつ","grammar:91313:ex2:words:4:pos":"noun","grammar:91313:ex2:words:5:zh":"(point in time)","grammar:91313:ex2:words:5:pos":"particle","grammar:91313:ex2:words:6:zh":"is held; there is","grammar:91313:ex2:words:6:note":"; the masu-form of ある","grammar:91313:ex2:words:6:pos":"verb","grammar:91313:ex2:points:0":"For festivals and events, 'is held' can be expressed with 「あります」","grammar:91313:ex2:points:1":"四月 is read しがつ","exam:91313:zh":"A birthday comes only once a year, so at my house we have a birthday party every year.","exam:91313:why":"「毎年」 means every year and matches a frequency of once a year. 「毎月」 means every month, which doesn't fit the condition given."},"91314":{"example:91314:exzh":"Please turn right at the next corner.","example:91314:exzh2":"This road curves to the left.","grammar:91314:ex:trans":"Please turn right at the next corner.","grammar:91314:ex:structure":"〔place〕を＋〔direction〕に曲がってください","grammar:91314:ex:explain":"「曲がる」 means to turn and is the most common word when giving directions. In 「角を曲がる」, 「を」 is not an object marker but marks the place you pass through; 「右に」 is the direction you turn. 「角」 here is read 「かど」 and means a street corner.","grammar:91314:ex:words:0:zh":"next","grammar:91314:ex:words:0:note":"つぎ","grammar:91314:ex:words:0:pos":"noun","grammar:91314:ex:words:1:zh":"'s","grammar:91314:ex:words:1:pos":"particle","grammar:91314:ex:words:2:zh":"corner","grammar:91314:ex:words:2:note":"かど","grammar:91314:ex:words:2:pos":"noun","grammar:91314:ex:words:3:zh":"(the place you pass through)","grammar:91314:ex:words:3:pos":"particle","grammar:91314:ex:words:4:zh":"the right side","grammar:91314:ex:words:4:note":"みぎ","grammar:91314:ex:words:4:pos":"noun","grammar:91314:ex:words:5:zh":"(direction)","grammar:91314:ex:words:5:pos":"particle","grammar:91314:ex:words:6:zh":"turn","grammar:91314:ex:words:6:note":"まがって; the te-form of 曲がる","grammar:91314:ex:words:6:pos":"verb","grammar:91314:ex:words:7:zh":"please (do ～)","grammar:91314:ex:words:7:pos":"auxiliary verb","grammar:91314:ex:points:0":"曲がる＝turn; the corner you pass takes 「を」, the direction takes 「に」","grammar:91314:ex:points:1":"角＝corner (read かど); the three phrases for giving directions: まっすぐ, 右に曲がる, 左に曲がる","grammar:91314:ex2:trans":"This road curves to the left.","grammar:91314:ex2:structure":"〔thing〕は＋〔direction〕に曲がっています","grammar:91314:ex2:words:0:zh":"this","grammar:91314:ex2:words:0:pos":"pre-noun adjectival","grammar:91314:ex2:words:1:zh":"road","grammar:91314:ex2:words:1:note":"みち","grammar:91314:ex2:words:1:pos":"noun","grammar:91314:ex2:words:2:zh":"(topic)","grammar:91314:ex2:words:2:pos":"particle","grammar:91314:ex2:words:3:zh":"left","grammar:91314:ex2:words:3:note":"ひだり","grammar:91314:ex2:words:3:pos":"noun","grammar:91314:ex2:words:4:zh":"(direction)","grammar:91314:ex2:words:4:pos":"particle","grammar:91314:ex2:words:5:zh":"is curved","grammar:91314:ex2:words:5:note":"まがっています; 曲がる＋ています","grammar:91314:ex2:words:5:pos":"verb","grammar:91314:ex2:points:0":"曲がる can also describe a thing that is itself curved: 道が曲がっている (the road is curved)","grammar:91314:ex2:points:1":"〜ています describes a state: the road stays curved","exam:91314:zh":"Go straight along this street and turn right at the next corner, and the station is on your left.","exam:91314:why":"「角を右に曲がる」 means to turn right at the corner. 「渡る」 means to cross a road or a river and can't express changing your direction of travel."},"91315":{"example:91315:exzh":"I lit the candle with a match.","example:91315:exzh2":"Do you have a match?","grammar:91315:ex:trans":"I lit the candle with a match.","grammar:91315:ex:structure":"〔tool〕で＋〔thing〕に火をつけました","grammar:91315:ex:explain":"「マッチ」 means match, from English 'match'. To light something you say 「〜に火をつける」: what gets lit takes 「に」, 「火」 takes 「を」, and the tool 「マッチ」 takes 「で」 — three particles you can learn in one sentence.","grammar:91315:ex:words:0:zh":"match","grammar:91315:ex:words:0:pos":"noun","grammar:91315:ex:words:1:zh":"(means, tool)","grammar:91315:ex:words:1:pos":"particle","grammar:91315:ex:words:2:zh":"candle","grammar:91315:ex:words:2:pos":"noun","grammar:91315:ex:words:3:zh":"(object)","grammar:91315:ex:words:3:pos":"particle","grammar:91315:ex:words:4:zh":"fire","grammar:91315:ex:words:4:note":"ひ","grammar:91315:ex:words:4:pos":"noun","grammar:91315:ex:words:5:zh":"(object marker)","grammar:91315:ex:words:5:pos":"particle","grammar:91315:ex:words:6:zh":"lit (a fire)","grammar:91315:ex:words:6:note":"; the past form of つける","grammar:91315:ex:words:6:pos":"verb","grammar:91315:ex:points:0":"マッチ＝match; 「マッチを擦る（する）」＝strike a match","grammar:91315:ex:points:1":"〔thing〕に火をつける＝light ～; 「に」 marks what is being lit","grammar:91315:ex2:trans":"Do you have a match?","grammar:91315:ex2:structure":"〔thing〕を＋持っていますか","grammar:91315:ex2:words:0:zh":"match","grammar:91315:ex2:words:0:pos":"noun","grammar:91315:ex2:words:1:zh":"(object marker)","grammar:91315:ex2:words:1:pos":"particle","grammar:91315:ex2:words:2:zh":"have; carry","grammar:91315:ex2:words:2:note":"もっています; 持つ＋ています","grammar:91315:ex2:words:2:pos":"verb","grammar:91315:ex2:words:3:zh":"(question)","grammar:91315:ex2:words:3:pos":"particle","grammar:91315:ex2:points:0":"マッチを持っていますか＝do you have a match on you?","grammar:91315:ex2:points:1":"持っています＝have, carry; used to ask whether someone has something with them","exam:91315:zh":"To light a fire, I took a match out of the box.","exam:91315:why":"「マッチ」 is a match used to light a fire and is counted with 「一本」. 「ペン」 is also counted with 「一本」, but it can't be used to light a fire."},"91316":{"example:91316:exzh":"I received a fountain pen from my father.","example:91316:exzh2":"I write letters with a fountain pen.","grammar:91316:ex:trans":"I got a fountain pen from my father.","grammar:91316:ex:structure":"〔person〕に＋〔thing〕を＋もらう","grammar:91316:ex:explain":"「万年筆」 literally means a pen for long use and refers to a fountain pen you refill with ink; it is often given as a gift for entering school or starting a job. This is the basic pattern 「〔person〕に〔thing〕をもらう」, with the subject I left out; 「もらいました」 is the polite past form and shows the receiving is complete.","grammar:91316:ex:words:0:zh":"dad","grammar:91316:ex:words:0:note":"ちち; used when talking about your own father to other people","grammar:91316:ex:words:0:pos":"noun","grammar:91316:ex:words:1:zh":"from (the source of the giving)","grammar:91316:ex:words:1:pos":"particle","grammar:91316:ex:words:2:zh":"fountain pen","grammar:91316:ex:words:2:note":"まんねんひつ","grammar:91316:ex:words:2:pos":"noun","grammar:91316:ex:words:3:zh":"(object marker)","grammar:91316:ex:words:3:pos":"particle","grammar:91316:ex:words:4:zh":"received","grammar:91316:ex:words:4:note":"もらいました; the polite past form of もらう","grammar:91316:ex:words:4:pos":"verb","grammar:91316:ex:points:0":"万年筆＝fountain pen (a pen filled with ink); a ballpoint pen is 「ボールペン」 — don't mix them up","grammar:91316:ex:points:1":"〜にもらう: receive from someone; here 「に」 marks who the thing came from, and 「父から」 is also possible","grammar:91316:ex:points:2":"「父」 is how you refer to your own father when speaking to others; someone else's father is 「お父さん」","grammar:91316:ex2:trans":"I write letters with a fountain pen.","grammar:91316:ex2:structure":"〔tool〕で＋〔thing〕を書く","grammar:91316:ex2:words:0:zh":"fountain pen","grammar:91316:ex2:words:0:note":"まんねんひつ","grammar:91316:ex2:words:0:pos":"noun","grammar:91316:ex2:words:1:zh":"with (a tool)","grammar:91316:ex2:words:1:pos":"particle","grammar:91316:ex2:words:2:zh":"letter","grammar:91316:ex2:words:2:note":"てがみ; Japanese 「手紙」 means letter, not toilet paper","grammar:91316:ex2:words:2:pos":"noun","grammar:91316:ex2:words:3:zh":"(object marker)","grammar:91316:ex2:words:3:pos":"particle","grammar:91316:ex2:words:4:zh":"write","grammar:91316:ex2:words:4:note":"かきます；書く的ます形","grammar:91316:ex2:words:4:pos":"verb","grammar:91316:ex2:points:0":"万年筆で書く: write with a fountain pen; tools and means take 「で」","grammar:91316:ex2:points:1":"手紙＝letter (the same characters mean toilet paper in Chinese)","exam:91316:zh":"The fountain pen I got from my father is a pen you fill with ink to use.","exam:91316:why":"「万年筆」 is a fountain pen that uses ink. 「鉛筆」 uses lead and can't be filled with ink."},"91317":{"example:91317:exzh":"May 3rd is a day off.","example:91317:exzh2":"I came to Japan three days ago.","grammar:91317:ex:trans":"May 3rd is a day off.","grammar:91317:ex:structure":"〔date〕は＋休みです","grammar:91317:ex:explain":"In Japanese, the 1st through the 10th of the month do not use the regular number readings; 「三日」 is read 「みっか」, not 「さんにち」. Here 「五月三日」 is Constitution Memorial Day in Japan, part of the Golden Week holidays. 「〜は休みです」 is the basic way to say ～ is a day off.","grammar:91317:ex:words:0:zh":"May","grammar:91317:ex:words:0:note":"ごがつ","grammar:91317:ex:words:0:pos":"noun","grammar:91317:ex:words:1:zh":"the 3rd","grammar:91317:ex:words:1:note":"みっか","grammar:91317:ex:words:1:pos":"noun","grammar:91317:ex:words:2:zh":"(topic)","grammar:91317:ex:words:2:pos":"particle","grammar:91317:ex:words:3:zh":"day off","grammar:91317:ex:words:3:note":"やすみ; the noun form of 休む","grammar:91317:ex:words:3:pos":"noun","grammar:91317:ex:words:4:zh":"is (polite form)","grammar:91317:ex:words:4:pos":"copula","grammar:91317:ex:points:0":"三日（みっか） has two meanings: the 3rd of the month and three days; here it is the date","grammar:91317:ex:points:1":"The readings for the 1st to the 10th are special: ついたち、ふつか、みっか、よっか、いつか…… learn them as a set","grammar:91317:ex2:trans":"I came to Japan three days ago.","grammar:91317:ex2:structure":"〔period〕前に＋〔place〕に来る","grammar:91317:ex2:words:0:zh":"three days","grammar:91317:ex2:words:0:note":"みっか","grammar:91317:ex2:words:0:pos":"noun","grammar:91317:ex2:words:1:zh":"～ ago","grammar:91317:ex2:words:1:note":"まえ","grammar:91317:ex2:words:1:pos":"suffix","grammar:91317:ex2:words:2:zh":"(point in time)","grammar:91317:ex2:words:2:pos":"particle","grammar:91317:ex2:words:3:zh":"Japan","grammar:91317:ex2:words:3:note":"にほん","grammar:91317:ex2:words:3:pos":"noun","grammar:91317:ex2:words:4:zh":"to (the destination)","grammar:91317:ex2:words:4:pos":"particle","grammar:91317:ex2:words:5:zh":"came","grammar:91317:ex2:words:5:note":"きました; the polite past form of 来る","grammar:91317:ex2:words:5:pos":"verb","grammar:91317:ex2:points:0":"三日前＝three days ago; here 「三日」 counts days, not a date","grammar:91317:ex2:points:1":"〔period〕前に: ～ ago; the first 「に」 marks the point in time, the second marks the place you arrived at","exam:91317:zh":"I was absent from school on Monday, Tuesday, and Wednesday—all three of those days.","exam:91317:why":"Monday through Wednesday is three days, so 「三日」 is correct. 「二日」 is only two days, one day short."},"91318":{"example:91318:exzh":"I bought three eggs.","example:91318:exzh2":"I have three questions.","grammar:91318:ex:trans":"I bought three eggs.","grammar:91318:ex:structure":"〔thing〕を＋〔quantity〕＋買う","grammar:91318:ex:explain":"「三つ」 is a native Japanese number, handy because it can count eggs, apples, questions, and many other things. Note the word order: Japanese says 「卵を三つ買いました」, with the quantity after 「を」 and before the verb — the opposite of the Chinese order.","grammar:91318:ex:words:0:zh":"egg","grammar:91318:ex:words:0:note":"たまご","grammar:91318:ex:words:0:pos":"noun","grammar:91318:ex:words:1:zh":"(object marker)","grammar:91318:ex:words:1:pos":"particle","grammar:91318:ex:words:2:zh":"three","grammar:91318:ex:words:2:note":"みっつ","grammar:91318:ex:words:2:pos":"numeral","grammar:91318:ex:words:3:zh":"bought","grammar:91318:ex:words:3:note":"かいました; past masu-form of 買う","grammar:91318:ex:words:3:pos":"verb","grammar:91318:ex:points:0":"三つ＝three; 「ひとつ、ふたつ、みっつ……」 counts almost anything regardless of type","grammar:91318:ex:points:1":"The quantity goes directly before the verb: 「卵を三つ買う」, with no 「の」 or generic counter added","grammar:91318:ex2:trans":"I have three questions.","grammar:91318:ex2:structure":"〔thing〕が＋〔quantity〕＋あります","grammar:91318:ex2:words:0:zh":"question","grammar:91318:ex2:words:0:note":"しつもん","grammar:91318:ex2:words:0:pos":"noun","grammar:91318:ex2:words:1:zh":"(nominative)","grammar:91318:ex2:words:1:pos":"particle","grammar:91318:ex2:words:2:zh":"three","grammar:91318:ex2:words:2:note":"みっつ","grammar:91318:ex2:words:2:pos":"numeral","grammar:91318:ex2:words:3:zh":"there is / are","grammar:91318:ex2:words:3:note":"あります; the masu-form (polite form) of ある","grammar:91318:ex2:words:3:pos":"verb","grammar:91318:ex2:points:0":"三つ can also count abstract things, such as 「質問が三つ」 or 「お願いが三つ」","grammar:91318:ex2:points:1":"〜があります: there is ～ (things, matters); people and animals take 「います」","exam:91318:zh":"There were five apples and I ate two, so now there are three.","exam:91318:why":"Five minus two leaves 「三つ」. 「二つ」 is how many I ate, not how many are left."},"91319":{"example:91319:exzh":"He is wearing a green shirt.","example:91319:exzh2":"There is a lot of greenery in the park.","grammar:91319:ex:trans":"He is wearing a green shirt.","grammar:91319:ex:structure":"〔color〕の＋〔clothing〕を着ています","grammar:91319:ex:explain":"「緑」 is a noun, so you say 「緑のシャツ」 with 「の」; 「赤い・白い・青い」 are adjectives and can go directly before a noun. 「着ています」 is not the action of putting something on but the state of having it on, and it is very common when describing what someone is wearing.","grammar:91319:ex:words:0:zh":"green","grammar:91319:ex:words:0:note":"みどり","grammar:91319:ex:words:0:pos":"noun","grammar:91319:ex:words:1:zh":"'s","grammar:91319:ex:words:1:pos":"particle","grammar:91319:ex:words:2:zh":"shirt","grammar:91319:ex:words:2:pos":"noun","grammar:91319:ex:words:3:zh":"(object marker)","grammar:91319:ex:words:3:pos":"particle","grammar:91319:ex:words:4:zh":"wear","grammar:91319:ex:words:4:note":"きて; the te-form of 着る","grammar:91319:ex:words:4:pos":"verb","grammar:91319:ex:words:5:zh":"(is in the state of ～)","grammar:91319:ex:words:5:note":"the masu-form of いる","grammar:91319:ex:words:5:pos":"auxiliary verb","grammar:91319:ex:points:0":"緑 is a noun, so it needs 「の」 to modify clothing: 緑のシャツ (unlike 「赤い」 or 「青い」, which attach directly)","grammar:91319:ex:points:1":"〜を着ています: is wearing ～ (a current state); clothing for the upper body takes 「着る」, while trousers and shoes take 「はく」","grammar:91319:ex2:trans":"There is a lot of greenery in the park.","grammar:91319:ex2:structure":"〔place〕には＋〔thing〕がたくさんあります","grammar:91319:ex2:words:0:zh":"park","grammar:91319:ex2:words:0:note":"こうえん","grammar:91319:ex2:words:0:pos":"noun","grammar:91319:ex2:words:1:zh":"in (the place where something exists)","grammar:91319:ex2:words:1:pos":"particle","grammar:91319:ex2:words:2:zh":"(topic)","grammar:91319:ex2:words:2:pos":"particle","grammar:91319:ex2:words:3:zh":"greenery; green trees","grammar:91319:ex2:words:3:note":"みどり","grammar:91319:ex2:words:3:pos":"noun","grammar:91319:ex2:words:4:zh":"(nominative)","grammar:91319:ex2:words:4:pos":"particle","grammar:91319:ex2:words:5:zh":"a lot","grammar:91319:ex2:words:5:pos":"adverb","grammar:91319:ex2:words:6:zh":"there is / are","grammar:91319:ex2:words:6:note":"あります; the masu-form (polite form) of ある","grammar:91319:ex2:words:6:pos":"verb","grammar:91319:ex2:points:0":"Besides the color green, 緑 can also mean trees and plants: 「緑が多い町」＝a town with lots of greenery","grammar:91319:ex2:points:1":"〔place〕に〔thing〕があります: something exists somewhere; adding 「は」 gives 「には」, which emphasizes this place","exam:91319:zh":"If you mix blue and yellow, you get green.","exam:91319:why":"「緑」 is green, the color you get by mixing blue and yellow. 「黒」 is black and isn't the result of mixing those two colors."},"91320":{"example:91320:exzh":"Good morning, everyone.","example:91320:exzh2":"Where are you all from?","grammar:91320:ex:trans":"Good morning, everyone.","grammar:91320:ex:structure":"皆さん、＋おはようございます","grammar:91320:ex:explain":"「皆さん」 is the polite way to say everyone, often used by teachers at the start of class or by hosts opening an event, followed by a greeting. More casual is 「みんな」, and more formal is 「皆様（みなさま）」.","grammar:91320:ex:words:0:zh":"everyone","grammar:91320:ex:words:0:note":"みなさん","grammar:91320:ex:words:0:pos":"pronoun","grammar:91320:ex:words:1:zh":"good morning","grammar:91320:ex:words:1:pos":"set phrase","grammar:91320:ex:points:0":"皆さん＝everyone; said up front when greeting a group, and polite","grammar:91320:ex:points:1":"おはようございます: good morning (polite); with friends you can just say 「おはよう」","grammar:91320:ex2:trans":"Where are you all from?","grammar:91320:ex2:structure":"〔person〕は＋どこから来ましたか","grammar:91320:ex2:words:0:zh":"everyone","grammar:91320:ex2:words:0:note":"みなさん","grammar:91320:ex2:words:0:pos":"pronoun","grammar:91320:ex2:words:1:zh":"(topic)","grammar:91320:ex2:words:1:pos":"particle","grammar:91320:ex2:words:2:zh":"where","grammar:91320:ex2:words:2:pos":"question word","grammar:91320:ex2:words:3:zh":"from","grammar:91320:ex2:words:3:pos":"particle","grammar:91320:ex2:words:4:zh":"came","grammar:91320:ex2:words:4:note":"きました; the polite past form of 来る","grammar:91320:ex2:words:4:pos":"verb","grammar:91320:ex2:words:5:zh":"(question)","grammar:91320:ex2:words:5:pos":"particle","grammar:91320:ex2:points:0":"皆さんは〜: everyone, all of you; used when asking a group of people a question","grammar:91320:ex2:points:1":"どこから来ましたか: Where are you from? Asks about the other person's home country or region","exam:91320:zh":"The teacher said to the whole class, “Everyone, good morning.”","exam:91320:why":"「皆さん」 is a polite way to address everyone who is present. 「あなた」 usually refers to a single person, so it doesn't fit greeting a whole class here."},"91321":{"example:91321:exzh":"There is a big park south of the station.","example:91321:exzh2":"In winter I want to go to a southern country.","grammar:91321:ex:trans":"There's a big park south of the station.","grammar:91321:ex:structure":"〔place〕の南に＋〔thing〕があります","grammar:91321:ex:explain":"「南」 on its own is read みなみ, and it stays みなみ in compounds like 「南口（みなみぐち）」 too. 「駅の南に」 means \"south of the station\" — the same pattern as 「駅の前に」 (in front of the station), so you can just swap in another direction word.","grammar:91321:ex:words:0:zh":"station","grammar:91321:ex:words:0:note":"えき","grammar:91321:ex:words:0:pos":"noun","grammar:91321:ex:words:1:zh":"'s","grammar:91321:ex:words:1:pos":"particle","grammar:91321:ex:words:2:zh":"the south / the south side","grammar:91321:ex:words:2:note":"みなみ","grammar:91321:ex:words:2:pos":"noun","grammar:91321:ex:words:3:zh":"in (the place where something exists)","grammar:91321:ex:words:3:pos":"particle","grammar:91321:ex:words:4:zh":"big","grammar:91321:ex:words:4:note":"おおきい","grammar:91321:ex:words:4:pos":"adjective","grammar:91321:ex:words:5:zh":"park","grammar:91321:ex:words:5:note":"こうえん","grammar:91321:ex:words:5:pos":"noun","grammar:91321:ex:words:6:zh":"(nominative)","grammar:91321:ex:words:6:pos":"particle","grammar:91321:ex:words:7:zh":"there is / are","grammar:91321:ex:words:7:note":"あります; the masu-form (polite form) of ある","grammar:91321:ex:words:7:pos":"verb","grammar:91321:ex:points:1":"〔place〕の南に: south of ~; 「の」 links the place and the direction","grammar:91321:ex2:trans":"In winter I want to go to a country in the south.","grammar:91321:ex2:structure":"〔place〕へ＋行きたいです","grammar:91321:ex2:words:0:zh":"winter","grammar:91321:ex2:words:0:note":"ふゆ","grammar:91321:ex2:words:0:pos":"noun","grammar:91321:ex2:words:1:zh":"(topic)","grammar:91321:ex2:words:1:pos":"particle","grammar:91321:ex2:words:2:zh":"south","grammar:91321:ex2:words:2:note":"みなみ","grammar:91321:ex2:words:2:pos":"noun","grammar:91321:ex2:words:3:zh":"'s","grammar:91321:ex2:words:3:pos":"particle","grammar:91321:ex2:words:4:zh":"country","grammar:91321:ex2:words:4:note":"くに","grammar:91321:ex2:words:4:pos":"noun","grammar:91321:ex2:words:5:zh":"to","grammar:91321:ex2:words:5:pos":"particle","grammar:91321:ex2:words:6:zh":"want to go","grammar:91321:ex2:words:6:note":"いきたい; 行く + たい (want to)","grammar:91321:ex2:words:6:pos":"verb","grammar:91321:ex2:words:7:zh":"is (polite form)","grammar:91321:ex2:words:7:pos":"copula","grammar:91321:ex2:points:0":"南の国 = a country in the south (a warm place)","grammar:91321:ex2:points:1":"〜たいです: want to ~; drop 「ます」 from the masu-form and add 「たい」: 行きます→行きたい","exam:91321:zh":"On this map the top is north, so the bottom is south.","exam:91321:why":"「南」 and 「北」 are opposite directions. 「東」 is east, which should be on the right side of this map."},"91322":{"example:91322:exzh":"Let's meet on the 6th of next month.","example:91322:exzh2":"I took six days off work.","grammar:91322:ex:trans":"Let's meet on the sixth of next month.","grammar:91322:ex:structure":"〔date〕に＋会いましょう","grammar:91322:ex:explain":"「六日」 is read むいか, one of the special readings for dates 1～10, close in sound to 「六つ（むっつ）」. This sentence uses 「〜ましょう」 to suggest meeting, and 「来月の六日に」 marks the time — add 「に」 whenever you give a specific date.","grammar:91322:ex:words:0:zh":"next month","grammar:91322:ex:words:0:note":"らいげつ","grammar:91322:ex:words:0:pos":"noun","grammar:91322:ex:words:1:zh":"'s","grammar:91322:ex:words:1:pos":"particle","grammar:91322:ex:words:2:zh":"the sixth (of the month)","grammar:91322:ex:words:2:note":"むいか","grammar:91322:ex:words:2:pos":"noun","grammar:91322:ex:words:3:zh":"(point in time)","grammar:91322:ex:words:3:pos":"particle","grammar:91322:ex:words:4:zh":"let's meet","grammar:91322:ex:words:4:note":"あいましょう; the masu-form of 会う + ましょう","grammar:91322:ex:words:4:pos":"verb","grammar:91322:ex:points:0":"六日（むいか） = the sixth / six days; it's not ろくにち, so memorize it separately","grammar:91322:ex:points:1":"〜ましょう: let's ~ (inviting the other person to do something together); a specific date takes 「に」 after it","grammar:91322:ex2:trans":"I took six days off work.","grammar:91322:ex2:structure":"〔number of days〕間、＋仕事を休む","grammar:91322:ex2:words:0:zh":"six days","grammar:91322:ex2:words:0:note":"むいか","grammar:91322:ex2:words:0:pos":"noun","grammar:91322:ex2:words:1:zh":"for ~ / a period of ~","grammar:91322:ex2:words:1:note":"かん","grammar:91322:ex2:words:1:pos":"suffix","grammar:91322:ex2:words:2:zh":"work","grammar:91322:ex2:words:2:note":"しごと","grammar:91322:ex2:words:2:pos":"noun","grammar:91322:ex2:words:3:zh":"(object marker)","grammar:91322:ex2:words:3:pos":"particle","grammar:91322:ex2:words:4:zh":"took the day off","grammar:91322:ex2:words:4:note":"やすみました; the past masu-form of 休む","grammar:91322:ex2:words:4:pos":"verb","grammar:91322:ex2:points:0":"六日間 = a period of six days; 「〜間（かん）」 comes after a number of days to stress how long it lasted","grammar:91322:ex2:points:1":"仕事を休む: take time off work; the thing you're absent from takes 「を」 before 「休む」","exam:91322:zh":"Today is May 5th, so tomorrow is May 6th.","exam:91322:why":"The day after the 5th is 「六日」. 「七日」 is two days after the 5th, so it doesn't match 「明日」."},"91323":{"example:91323:exzh":"There are six mandarin oranges in the box.","example:91323:exzh2":"This child is six years old.","grammar:91323:ex:trans":"There are six mandarin oranges in the box.","grammar:91323:ex:structure":"〔place〕に＋〔thing〕が＋〔quantity〕あります","grammar:91323:ex:explain":"「六つ」 is read むっつ, starting with む just like 「六日（むいか）」. This is the existence pattern 「〔place〕に〔thing〕があります」, with the quantity 「六つ」 slipped in before the verb. Mandarins are things, so 「あります」 is used.","grammar:91323:ex:words:0:zh":"box","grammar:91323:ex:words:0:note":"はこ","grammar:91323:ex:words:0:pos":"noun","grammar:91323:ex:words:1:zh":"'s","grammar:91323:ex:words:1:pos":"particle","grammar:91323:ex:words:2:zh":"inside","grammar:91323:ex:words:2:note":"なか","grammar:91323:ex:words:2:pos":"noun","grammar:91323:ex:words:3:zh":"in (the place where something exists)","grammar:91323:ex:words:3:pos":"particle","grammar:91323:ex:words:4:zh":"mandarin orange","grammar:91323:ex:words:4:pos":"noun","grammar:91323:ex:words:5:zh":"(nominative)","grammar:91323:ex:words:5:pos":"particle","grammar:91323:ex:words:6:zh":"six (items)","grammar:91323:ex:words:6:note":"むっつ","grammar:91323:ex:words:6:pos":"numeral","grammar:91323:ex:words:7:zh":"there is / are","grammar:91323:ex:words:7:note":"あります; the masu-form (polite form) of ある","grammar:91323:ex:words:7:pos":"verb","grammar:91323:ex:points:0":"六つ = six (the ひとつ～とお counting style)","grammar:91323:ex:points:1":"〜の中に: inside ~; the quantity goes after 「が」 and before the verb","grammar:91323:ex2:trans":"This child is six.","grammar:91323:ex2:structure":"〔person〕は＋〔number〕つです","grammar:91323:ex2:words:0:zh":"this","grammar:91323:ex2:words:0:pos":"pre-noun adjectival","grammar:91323:ex2:words:1:zh":"child","grammar:91323:ex2:words:1:note":"こ","grammar:91323:ex2:words:1:pos":"noun","grammar:91323:ex2:words:2:zh":"(topic)","grammar:91323:ex2:words:2:pos":"particle","grammar:91323:ex2:words:3:zh":"six years old","grammar:91323:ex2:words:3:note":"むっつ","grammar:91323:ex2:words:3:pos":"numeral","grammar:91323:ex2:words:4:zh":"is (polite form)","grammar:91323:ex2:words:4:pos":"copula","grammar:91323:ex2:points:0":"「ひとつ～ここのつ」 can also give a small child's age: 六つ = six years old","grammar:91323:ex2:points:1":"Ages are usually given with 「六歳（ろくさい）」; 「六つ」 is more casual and mostly used for small children","exam:91323:zh":"I bought three apples and later bought three more, so there are six in all.","exam:91323:why":"Three plus three is six, so 「六つ」 is correct. 「七つ」 is seven, one more than the total in the sentence."},"91324":{"example:91324:exzh":"There is a test on Thursday.","example:91324:exzh2":"I go to the pool every Thursday.","grammar:91324:ex:trans":"There's a test on Thursday.","grammar:91324:ex:structure":"〔day of the week〕に＋〔event〕があります","grammar:91324:ex:explain":"The Japanese week runs 「日・月・火・水・木・金・土」 plus 「曜日」, so 「木曜日」 is Thursday — don't count in the Chinese order. Events like tests, meetings and parties also take 「があります」 to mean \"there is\".","grammar:91324:ex:words:0:zh":"Thursday","grammar:91324:ex:words:0:note":"もくようび","grammar:91324:ex:words:0:pos":"noun","grammar:91324:ex:words:1:zh":"(point in time)","grammar:91324:ex:words:1:pos":"particle","grammar:91324:ex:words:2:zh":"test","grammar:91324:ex:words:2:pos":"noun","grammar:91324:ex:words:3:zh":"(nominative)","grammar:91324:ex:words:3:pos":"particle","grammar:91324:ex:words:4:zh":"there is / are","grammar:91324:ex:words:4:note":"あります; the masu-form (polite form) of ある","grammar:91324:ex:words:4:pos":"verb","grammar:91324:ex:points:0":"木曜日 = Thursday; Japanese days of the week are written with 「日月火水木金土」","grammar:91324:ex:points:1":"Days of the week take 「に」: 木曜日に; events also use 「があります」","grammar:91324:ex2:trans":"I go to the pool every Thursday.","grammar:91324:ex2:structure":"毎週〔day of the week〕、＋〔place〕に行きます","grammar:91324:ex2:words:0:zh":"every week","grammar:91324:ex2:words:0:note":"まいしゅう","grammar:91324:ex2:words:0:pos":"noun","grammar:91324:ex2:words:1:zh":"Thursday","grammar:91324:ex2:words:1:note":"もくようび","grammar:91324:ex2:words:1:pos":"noun","grammar:91324:ex2:words:2:zh":"swimming pool","grammar:91324:ex2:words:2:pos":"noun","grammar:91324:ex2:words:3:zh":"to (the destination)","grammar:91324:ex2:words:3:pos":"particle","grammar:91324:ex2:words:4:zh":"go","grammar:91324:ex2:words:4:note":"いきます; masu-form of 行く","grammar:91324:ex2:words:4:pos":"verb","grammar:91324:ex2:points:0":"毎週木曜日 = every Thursday; when 「毎週」 comes first, 「に」 is usually dropped","grammar:91324:ex2:points:1":"〔place〕に行きます: go to ~; both 「に」 and 「へ」 can mark the destination","exam:91324:zh":"Today is Wednesday, so tomorrow is Thursday.","exam:91324:why":"The day after 「水曜日」 is 「木曜日」. 「火曜日」 is Tuesday, the day before Wednesday."},"91325":{"example:91325:exzh":"Hello, this is Tanaka.","example:91325:exzh2":"Hello, can you hear me?","grammar:91325:ex:trans":"Hello, this is Tanaka.","grammar:91325:ex:structure":"もしもし、＋〔name〕です","grammar:91325:ex:explain":"「もしもし」 is the first thing you say when you pick up or make a call — the phone version of \"hello\". You can't use it to stop a stranger in the street; say 「すみません」 instead. This line follows with 「田中です」 to give your surname, the most basic way to open a phone call.","grammar:91325:ex:words:0:zh":"hello (on the phone)","grammar:91325:ex:words:0:pos":"set phrase","grammar:91325:ex:words:1:zh":"Tanaka (surname)","grammar:91325:ex:words:1:note":"たなか","grammar:91325:ex:words:1:pos":"noun","grammar:91325:ex:words:2:zh":"is (polite form)","grammar:91325:ex:words:2:pos":"copula","grammar:91325:ex:points:0":"もしもし: the \"hello\" used on the phone, only on the phone — never when speaking to someone face to face","grammar:91325:ex:points:1":"Giving your name on the phone: 「〔name〕です」, or the more polite 「〔name〕と申します」","grammar:91325:ex2:trans":"Hello, can you hear me?","grammar:91325:ex2:structure":"もしもし、＋聞こえますか","grammar:91325:ex2:words:0:zh":"hello (on the phone)","grammar:91325:ex2:words:0:pos":"set phrase","grammar:91325:ex2:words:1:zh":"can be heard","grammar:91325:ex2:words:1:note":"きこえます; the masu-form of 聞こえる","grammar:91325:ex2:words:1:pos":"verb","grammar:91325:ex2:words:2:zh":"(question)","grammar:91325:ex2:words:2:pos":"particle","grammar:91325:ex2:points:0":"もしもし is also used when the line is bad or to check that the other person is still there","grammar:91325:ex2:points:1":"聞こえる: to be audible (the sound reaches you naturally); different from 「聞く」 (to listen on purpose)","exam:91325:zh":"I picked up the phone and first said, \"Hello, this is Tanaka.\"","exam:91325:why":"「もしもし」 is the greeting commonly used when answering the phone. 「おかえりなさい」 is said to someone who has come home and means \"welcome back,\" so it doesn't fit answering the phone."},"91326":{"example:91326:exzh":"I bought vegetables at the greengrocer's.","example:91326:exzh2":"There is a greengrocer's in front of the station.","grammar:91326:ex:trans":"I bought vegetables at the greengrocer's.","grammar:91326:ex:structure":"〔shop〕で＋〔thing〕を買う","grammar:91326:ex:explain":"「八百屋」 is read やおや, an irregular reading you have to memorize as a whole word. 「〜屋」 means \"~ shop\", as in 「本屋（bookstore）」 or 「パン屋（bakery）」. Here 「で」 marks where the buying happens.","grammar:91326:ex:words:0:zh":"greengrocer's","grammar:91326:ex:words:0:note":"やおや","grammar:91326:ex:words:0:pos":"noun","grammar:91326:ex:words:1:zh":"at / in (where the action happens)","grammar:91326:ex:words:1:pos":"particle","grammar:91326:ex:words:2:zh":"vegetables","grammar:91326:ex:words:2:note":"やさい","grammar:91326:ex:words:2:pos":"noun","grammar:91326:ex:words:3:zh":"(object marker)","grammar:91326:ex:words:3:pos":"particle","grammar:91326:ex:words:4:zh":"bought","grammar:91326:ex:words:4:note":"かいました; past masu-form of 買う","grammar:91326:ex:words:4:pos":"verb","grammar:91326:ex:points:0":"八百屋（やおや） = a small shop selling vegetables and fruit; the reading is unusual and doesn't follow the kanji","grammar:91326:ex:points:1":"〔place〕で: where an action takes place; 「に」 marks existence, 「で」 marks action","grammar:91326:ex2:trans":"There's a greengrocer's in front of the station.","grammar:91326:ex2:structure":"〔place〕に＋〔thing〕があります","grammar:91326:ex2:words:0:zh":"station","grammar:91326:ex2:words:0:note":"えき","grammar:91326:ex2:words:0:pos":"noun","grammar:91326:ex2:words:1:zh":"'s","grammar:91326:ex2:words:1:pos":"particle","grammar:91326:ex2:words:2:zh":"front","grammar:91326:ex2:words:2:note":"まえ","grammar:91326:ex2:words:2:pos":"noun","grammar:91326:ex2:words:3:zh":"in (the place where something exists)","grammar:91326:ex2:words:3:pos":"particle","grammar:91326:ex2:words:4:zh":"greengrocer's","grammar:91326:ex2:words:4:note":"やおや","grammar:91326:ex2:words:4:pos":"noun","grammar:91326:ex2:words:5:zh":"(nominative)","grammar:91326:ex2:words:5:pos":"particle","grammar:91326:ex2:words:6:zh":"there is / are","grammar:91326:ex2:words:6:note":"あります; the masu-form (polite form) of ある","grammar:91326:ex2:words:6:pos":"verb","grammar:91326:ex2:points:0":"八百屋が〜: 「〜屋」 can mean the shop or the person running it (八百屋さん = the greengrocer)","grammar:91326:ex2:points:1":"駅の前に: in front of the station; shops and buildings take 「あります」","exam:91326:zh":"The produce shop in front of the station is a small store that sells only vegetables and fruit.","exam:91326:why":"「八百屋」 is a shop that sells vegetables and fruit. 「魚屋」 is also a food shop, but it mainly sells fish, so it doesn't match the goods mentioned in the sentence."},"91327":{"example:91327:exzh":"I'm tired, so let's take a short break.","example:91327:exzh2":"I missed school because of a cold.","grammar:91327:ex:trans":"I'm tired, so let's rest for a bit.","grammar:91327:ex:structure":"〔reason〕から、＋少し休みましょう","grammar:91327:ex:explain":"「休む」 basically means to stop and rest, and 「休みましょう」 here invites everyone to take a break. 「疲れた」 uses the past form to describe the state of being tired now — Japanese usually says \"I'm tired\" with the ta-form. 「少し」 softens the tone.","grammar:91327:ex:words:0:zh":"tired","grammar:91327:ex:words:0:note":"つかれた; the ta-form of 疲れる","grammar:91327:ex:words:0:pos":"verb","grammar:91327:ex:words:1:zh":"because","grammar:91327:ex:words:1:pos":"particle","grammar:91327:ex:words:2:zh":"a little / for a bit","grammar:91327:ex:words:2:note":"すこし","grammar:91327:ex:words:2:pos":"adverb","grammar:91327:ex:words:3:zh":"let's rest","grammar:91327:ex:words:3:note":"やすみましょう; the masu-form of 休む + ましょう","grammar:91327:ex:words:3:pos":"verb","grammar:91327:ex:points:0":"休む = to rest; it also means to take time off or be absent","grammar:91327:ex:points:1":"〜から: because ~; it follows the reason. 「〜ましょう」 = let's ~ (inviting the other person to join)","grammar:91327:ex2:trans":"I stayed away from school because of a cold.","grammar:91327:ex2:structure":"〔reason〕で＋〔school・work〕を休む","grammar:91327:ex2:words:0:zh":"a cold","grammar:91327:ex2:words:0:note":"かぜ","grammar:91327:ex2:words:0:pos":"noun","grammar:91327:ex2:words:1:zh":"because of (cause)","grammar:91327:ex2:words:1:pos":"particle","grammar:91327:ex2:words:2:zh":"school","grammar:91327:ex2:words:2:note":"がっこう","grammar:91327:ex2:words:2:pos":"noun","grammar:91327:ex2:words:3:zh":"(object marker)","grammar:91327:ex2:words:3:pos":"particle","grammar:91327:ex2:words:4:zh":"take time off / stay away","grammar:91327:ex2:words:4:note":"やすみました; the past masu-form of 休む","grammar:91327:ex2:words:4:pos":"verb","grammar:91327:ex2:points:0":"学校を休む = take time off school, miss school; the place you're absent from takes 「を」","grammar:91327:ex2:points:1":"風邪で: because of a cold; illnesses and weather can take 「で」 to show the reason","exam:91327:zh":"I can't go to school because I have a cold, so I'll skip today's class.","exam:91327:why":"「授業を休む」 means to miss class, which fits not being able to go to school because of a cold. 「受ける」 means to take a class, which contradicts not being able to come to school."},"91328":{"example:91328:exzh":"I bought eight loaves of bread.","example:91328:exzh2":"There are eight desks in this classroom.","grammar:91328:ex:trans":"I bought eight pieces of bread.","grammar:91328:ex:structure":"〔thing〕を＋〔quantity〕＋買う","grammar:91328:ex:explain":"「八つ」 is read やっつ, which is different from 「八日（ようか）」 — keep the two apart. The ひとつ～とお counting style works for most things — bread, apples, eggs — and it's the easiest one for beginners.","grammar:91328:ex:words:0:zh":"bread","grammar:91328:ex:words:0:pos":"noun","grammar:91328:ex:words:1:zh":"(object marker)","grammar:91328:ex:words:1:pos":"particle","grammar:91328:ex:words:2:zh":"eight (of them)","grammar:91328:ex:words:2:note":"やっつ","grammar:91328:ex:words:2:pos":"numeral","grammar:91328:ex:words:3:zh":"bought","grammar:91328:ex:words:3:note":"かいました; past masu-form of 買う","grammar:91328:ex:words:3:pos":"verb","grammar:91328:ex:points:0":"八つ = eight; read やっつ, with the small っ in the middle","grammar:91328:ex:points:1":"The quantity goes before the verb: パンを八つ買う","grammar:91328:ex2:trans":"There are eight desks in this classroom.","grammar:91328:ex2:structure":"〔place〕には＋〔thing〕が＋〔quantity〕あります","grammar:91328:ex2:words:0:zh":"this","grammar:91328:ex2:words:0:pos":"pre-noun adjectival","grammar:91328:ex2:words:1:zh":"class; classroom","grammar:91328:ex2:words:1:pos":"noun","grammar:91328:ex2:words:2:zh":"in (the place where something exists)","grammar:91328:ex2:words:2:pos":"particle","grammar:91328:ex2:words:3:zh":"(topic)","grammar:91328:ex2:words:3:pos":"particle","grammar:91328:ex2:words:4:zh":"desk","grammar:91328:ex2:words:4:note":"つくえ","grammar:91328:ex2:words:4:pos":"noun","grammar:91328:ex2:words:5:zh":"(nominative)","grammar:91328:ex2:words:5:pos":"particle","grammar:91328:ex2:words:6:zh":"eight (desks)","grammar:91328:ex2:words:6:note":"やっつ","grammar:91328:ex2:words:6:pos":"numeral","grammar:91328:ex2:words:7:zh":"there is / are","grammar:91328:ex2:words:7:note":"あります; the masu-form (polite form) of ある","grammar:91328:ex2:words:7:pos":"verb","grammar:91328:ex2:points:0":"八つ can count desks, chairs and so on; there's no need to change counters — Japanese simply uses 「つ」","grammar:91328:ex2:points:1":"〜には〜があります: there is ~ in / at a place","exam:91328:zh":"There were ten boxes, and two were used, so eight are left.","exam:91328:why":"Ten minus two leaves 「八つ」. 「九つ」 is the amount left only when just one has been used."},"91329":{"example:91329:exzh":"I buy stamps at the post office.","example:91329:exzh2":"The post office opens at nine.","grammar:91329:ex:trans":"I buy stamps at the post office.","grammar:91329:ex:structure":"〔place〕で＋〔thing〕を買います","grammar:91329:ex:explain":"「郵便局」 is read ゆうびんきょく, with 「便」 pronounced びん here. Japanese post offices handle savings and bill payments as well as mail. 「で」 marks where the buying happens, and 「買います」 is non-past, so it can be a habit or something you're about to do.","grammar:91329:ex:words:0:zh":"post office","grammar:91329:ex:words:0:note":"ゆうびんきょく","grammar:91329:ex:words:0:pos":"noun","grammar:91329:ex:words:1:zh":"at / in (where the action happens)","grammar:91329:ex:words:1:pos":"particle","grammar:91329:ex:words:2:zh":"stamp","grammar:91329:ex:words:2:note":"きって","grammar:91329:ex:words:2:pos":"noun","grammar:91329:ex:words:3:zh":"(object marker)","grammar:91329:ex:words:3:pos":"particle","grammar:91329:ex:words:4:zh":"buy","grammar:91329:ex:words:4:note":"かいます; the masu-form of 買う","grammar:91329:ex:words:4:pos":"verb","grammar:91329:ex:points:0":"郵便局 = post office; 「郵便」 means mail and 「局」 means bureau","grammar:91329:ex:points:1":"〔place〕で: where an action happens; 「切手」 means postage stamp, not \"cut hand\"","grammar:91329:ex2:trans":"The post office opens at nine.","grammar:91329:ex2:structure":"〔place〕は＋〔time〕に開きます","grammar:91329:ex2:words:0:zh":"post office","grammar:91329:ex2:words:0:note":"ゆうびんきょく","grammar:91329:ex2:words:0:pos":"noun","grammar:91329:ex2:words:1:zh":"(topic)","grammar:91329:ex2:words:1:pos":"particle","grammar:91329:ex2:words:2:zh":"nine o'clock","grammar:91329:ex2:words:2:note":"くじ; in times, 「九」 is read く","grammar:91329:ex2:words:2:pos":"noun","grammar:91329:ex2:words:3:zh":"(point in time)","grammar:91329:ex2:words:3:pos":"particle","grammar:91329:ex2:words:4:zh":"opens (for business)","grammar:91329:ex2:words:4:note":"あきます; the masu-form of 開く（あく）","grammar:91329:ex2:words:4:pos":"verb","grammar:91329:ex2:points:0":"郵便局は〜時に開きます: what time the post office opens","grammar:91329:ex2:points:1":"九時 is read くじ, not きゅうじ; 開く here is あく (an intransitive verb — the doors open by themselves)","exam:91329:zh":"I went to the post office to buy stamps to put on a letter.","exam:91329:why":"「郵便局」 is the post office, where you can buy stamps. 「銀行」 is also a place where you take care of business, but it mainly handles financial matters such as deposits."},"91330":{"example:91330:exzh":"Please speak a little more slowly.","example:91330:exzh2":"On weekends I take it easy at home.","grammar:91330:ex:trans":"Please speak a little more slowly.","grammar:91330:ex:structure":"もう少し＋ゆっくり＋〔verb te-form〕ください","grammar:91330:ex:explain":"「ゆっくり」 describes doing something slowly and unhurriedly, and sits before the verb as an adverb. 「もう少し」 means \"a little more\", so the whole sentence politely asks the other person to slow down. It's extremely useful when talking to Japanese people while you're learning.","grammar:91330:ex:words:0:zh":"a little more","grammar:91330:ex:words:0:note":"もうすこし","grammar:91330:ex:words:0:pos":"adverb","grammar:91330:ex:words:1:zh":"slowly","grammar:91330:ex:words:1:pos":"adverb","grammar:91330:ex:words:2:zh":"tell","grammar:91330:ex:words:2:note":"はなして; te-form of 話す","grammar:91330:ex:words:2:pos":"verb","grammar:91330:ex:words:3:zh":"please ~","grammar:91330:ex:words:3:note":"ください; the imperative form of くださる","grammar:91330:ex:words:3:pos":"auxiliary verb","grammar:91330:ex:points:0":"ゆっくり = slowly; the handiest line when you can't follow Japanese: 「ゆっくり話してください」","grammar:91330:ex:points:1":"〜てください: please ~; put the verb in the te-form and add 「ください」","grammar:91330:ex2:trans":"On weekends I rest and take it easy at home.","grammar:91330:ex2:structure":"〔time〕は＋〔place〕で＋ゆっくり休みます","grammar:91330:ex2:words:0:zh":"weekend","grammar:91330:ex2:words:0:note":"しゅうまつ","grammar:91330:ex2:words:0:pos":"noun","grammar:91330:ex2:words:1:zh":"(topic)","grammar:91330:ex2:words:1:pos":"particle","grammar:91330:ex2:words:2:zh":"house","grammar:91330:ex2:words:2:note":"いえ","grammar:91330:ex2:words:2:pos":"noun","grammar:91330:ex2:words:3:zh":"at / in (where the action happens)","grammar:91330:ex2:words:3:pos":"particle","grammar:91330:ex2:words:4:zh":"leisurely / taking it easy","grammar:91330:ex2:words:4:pos":"adverb","grammar:91330:ex2:words:5:zh":"rest","grammar:91330:ex2:words:5:note":"やすみます: the masu-form of 休む.","grammar:91330:ex2:words:5:pos":"verb","grammar:91330:ex2:points:0":"ゆっくり also means unhurried, with no rush: ゆっくり休む = rest properly","grammar:91330:ex2:points:1":"家で: at home; the place of an action takes 「で」","exam:91330:zh":"You speak too fast and I don't really understand, so please speak a little more slowly.","exam:91330:why":"「ゆっくり」 can mean slowing down the speed of speaking. 「たくさん」 means speaking a lot, which doesn't solve the problem of speaking too fast."},"91331":{"example:91331:exzh":"School starts on April 8th.","example:91331:exzh2":"I was in America for eight days.","grammar:91331:ex:trans":"School starts on April 8th.","grammar:91331:ex:structure":"〔date〕から＋〔thing〕が始まります","grammar:91331:ex:explain":"「八日」 is read ようか and sounds very close to 「四日（よっか）」 — a favourite trap on exams, so be careful. The Japanese school year starts in April, so this sentence comes up a lot. 「学校が始まる」 literally says \"school begins\", meaning classes start again.","grammar:91331:ex:words:0:zh":"April","grammar:91331:ex:words:0:note":"しがつ; in month names, 「四」 is read し","grammar:91331:ex:words:0:pos":"noun","grammar:91331:ex:words:1:zh":"the eighth (of the month)","grammar:91331:ex:words:1:note":"ようか","grammar:91331:ex:words:1:pos":"noun","grammar:91331:ex:words:2:zh":"from","grammar:91331:ex:words:2:pos":"particle","grammar:91331:ex:words:3:zh":"school","grammar:91331:ex:words:3:note":"がっこう","grammar:91331:ex:words:3:pos":"noun","grammar:91331:ex:words:4:zh":"(nominative)","grammar:91331:ex:words:4:pos":"particle","grammar:91331:ex:words:5:zh":"begins","grammar:91331:ex:words:5:note":"はじまります; the masu-form of 始まる","grammar:91331:ex:words:5:pos":"verb","grammar:91331:ex:points:0":"八日（ようか） = the eighth / eight days; don't read it はちにち","grammar:91331:ex:points:1":"〜から始まります: start from ~; 「始まる」 is something starting on its own, so it takes 「が」","grammar:91331:ex2:trans":"I was in the US for eight days.","grammar:91331:ex2:structure":"〔number of days〕間、＋〔place〕にいました","grammar:91331:ex2:words:0:zh":"eight days","grammar:91331:ex2:words:0:note":"ようか","grammar:91331:ex2:words:0:pos":"noun","grammar:91331:ex2:words:1:zh":"for ~ / a period of ~","grammar:91331:ex2:words:1:note":"かん","grammar:91331:ex2:words:1:pos":"suffix","grammar:91331:ex2:words:2:zh":"America","grammar:91331:ex2:words:2:pos":"noun","grammar:91331:ex2:words:3:zh":"in (the place where something exists)","grammar:91331:ex2:words:3:pos":"particle","grammar:91331:ex2:words:4:zh":"was (there) / stayed","grammar:91331:ex2:words:4:note":"いました; the past masu-form of いる","grammar:91331:ex2:words:4:pos":"verb","grammar:91331:ex2:points:0":"八日間 = eight days; a number of days plus 「間」 marks a span of time","grammar:91331:ex2:points:1":"〔place〕にいる: someone is somewhere; people and animals take 「いる」","exam:91331:zh":"The day after July 7th is July 8th.","exam:91331:why":"「八日」 here means the eighth of the month and is the day after the 7th. 「九日」 is the 9th, two days later."},"91332":{"example:91332:exzh":"I go back to my country on July 4th.","example:91332:exzh2":"It rained for four days.","grammar:91332:ex:trans":"I'm going back to my country on July 4th.","grammar:91332:ex:structure":"〔date〕に＋国へ帰ります","grammar:91332:ex:explain":"「四日」 is read よっか, one of the special readings for dates 1～10 and the easiest to confuse with 「八日（ようか）」. 「国へ帰ります」 is how exchange students and other foreigners say they're going home. A date takes 「に」 to mark the point in time.","grammar:91332:ex:words:0:zh":"July","grammar:91332:ex:words:0:note":"しちがつ","grammar:91332:ex:words:0:pos":"noun","grammar:91332:ex:words:1:zh":"the fourth (of the month)","grammar:91332:ex:words:1:note":"よっか","grammar:91332:ex:words:1:pos":"noun","grammar:91332:ex:words:2:zh":"(point in time)","grammar:91332:ex:words:2:pos":"particle","grammar:91332:ex:words:3:zh":"(one's own) country","grammar:91332:ex:words:3:note":"くに","grammar:91332:ex:words:3:pos":"noun","grammar:91332:ex:words:4:zh":"to","grammar:91332:ex:words:4:pos":"particle","grammar:91332:ex:words:5:zh":"go home / return","grammar:91332:ex:words:5:note":"かえります; the masu-form of 帰る","grammar:91332:ex:words:5:pos":"verb","grammar:91332:ex:points:0":"四日（よっか） = the fourth / four days; don't mix it up with 「八日（ようか）」","grammar:91332:ex:points:1":"国へ帰る: go back to your own country; 「国」 here means your home country","grammar:91332:ex2:trans":"It rained for four days.","grammar:91332:ex2:structure":"〔number of days〕間、＋雨が降りました","grammar:91332:ex2:words:0:zh":"four days","grammar:91332:ex2:words:0:note":"よっか","grammar:91332:ex2:words:0:pos":"noun","grammar:91332:ex2:words:1:zh":"for ~ / a period of ~","grammar:91332:ex2:words:1:note":"かん","grammar:91332:ex2:words:1:pos":"suffix","grammar:91332:ex2:words:2:zh":"rain","grammar:91332:ex2:words:2:note":"あめ","grammar:91332:ex2:words:2:pos":"noun","grammar:91332:ex2:words:3:zh":"(nominative)","grammar:91332:ex2:words:3:pos":"particle","grammar:91332:ex2:words:4:zh":"rained","grammar:91332:ex2:words:4:note":"ふりました; the past masu-form of 降る","grammar:91332:ex2:words:4:pos":"verb","grammar:91332:ex2:points:0":"四日間 = a period of four days","grammar:91332:ex2:points:1":"雨が降る: to rain; rain and snow take 「降る」","exam:91332:zh":"Today is June 3rd, so tomorrow is June 4th.","exam:91332:why":"The day after the 3rd is 「四日」. 「二日」 is the day before the 3rd, so it doesn't match 「明日」."},"91333":{"example:91333:exzh":"I bought four apples.","example:91333:exzh2":"There are four windows in this room.","grammar:91333:ex:trans":"I bought four apples.","grammar:91333:ex:structure":"〔thing〕を＋〔quantity〕＋買う","grammar:91333:ex:explain":"「四つ」 is read よっつ, starting with よっ just like 「四日（よっか）」. For things like apples, counting with 「つ」 is the simplest. Note that Japanese puts the quantity after 「を」 and before the verb.","grammar:91333:ex:words:0:zh":"apple","grammar:91333:ex:words:0:pos":"noun","grammar:91333:ex:words:1:zh":"(object marker)","grammar:91333:ex:words:1:pos":"particle","grammar:91333:ex:words:2:zh":"four","grammar:91333:ex:words:2:note":"よっつ","grammar:91333:ex:words:2:pos":"numeral","grammar:91333:ex:words:3:zh":"bought","grammar:91333:ex:words:3:note":"かいました; past masu-form of 買う","grammar:91333:ex:words:3:pos":"verb","grammar:91333:ex:points:0":"四つ = four; read よっつ, not しつ or よんつ","grammar:91333:ex:points:1":"The quantity goes before the verb: りんごを四つ買う","grammar:91333:ex2:trans":"There are four windows in this room.","grammar:91333:ex2:structure":"〔place〕には＋〔thing〕が＋〔quantity〕あります","grammar:91333:ex2:words:0:zh":"this","grammar:91333:ex2:words:0:pos":"pre-noun adjectival","grammar:91333:ex2:words:1:zh":"room","grammar:91333:ex2:words:1:note":"へや","grammar:91333:ex2:words:1:pos":"noun","grammar:91333:ex2:words:2:zh":"in (the place where something exists)","grammar:91333:ex2:words:2:pos":"particle","grammar:91333:ex2:words:3:zh":"(topic)","grammar:91333:ex2:words:3:pos":"particle","grammar:91333:ex2:words:4:zh":"window","grammar:91333:ex2:words:4:note":"まど","grammar:91333:ex2:words:4:pos":"noun","grammar:91333:ex2:words:5:zh":"(nominative)","grammar:91333:ex2:words:5:pos":"particle","grammar:91333:ex2:words:6:zh":"four (windows)","grammar:91333:ex2:words:6:note":"よっつ","grammar:91333:ex2:words:6:pos":"numeral","grammar:91333:ex2:words:7:zh":"there is / are","grammar:91333:ex2:words:7:note":"あります; the masu-form (polite form) of ある","grammar:91333:ex2:words:7:pos":"verb","grammar:91333:ex2:points:0":"四つ also counts windows, doors and the like — no special counter is needed in Japanese, 「つ」 does the job","grammar:91333:ex2:points:1":"部屋（へや） = room; the reading is irregular","exam:91333:zh":"There were six cakes, and after eating two, there are four now.","exam:91333:why":"Six minus two leaves four, so 「四つ」 is correct. 「二つ」 is how many you ate, not how many are left."},"91334":{"example:91334:exzh":"I listen to the radio every morning.","example:91334:exzh2":"I turned on the radio in the car.","grammar:91334:ex:trans":"I listen to the radio every morning.","grammar:91334:ex:structure":"毎朝、＋ラジオを聞きます","grammar:91334:ex:explain":"「ラジオ」 comes from English \"radio\" and can mean the set or the programmes. 「ラジオを聞く」 is to listen to the radio, while watching TV is 「テレビを見る」. The non-past 「聞きます」 shows a daily habit.","grammar:91334:ex:words:0:zh":"every morning","grammar:91334:ex:words:0:note":"まいあさ","grammar:91334:ex:words:0:pos":"noun","grammar:91334:ex:words:1:zh":"radio","grammar:91334:ex:words:1:pos":"noun","grammar:91334:ex:words:2:zh":"(object marker)","grammar:91334:ex:words:2:pos":"particle","grammar:91334:ex:words:3:zh":"listen","grammar:91334:ex:words:3:note":"ききます; the masu-form of 聞く","grammar:91334:ex:words:3:pos":"verb","grammar:91334:ex:points:0":"ラジオ = radio set, and also radio programmes; 「ラジオを聞く」 = listen to the radio","grammar:91334:ex:points:1":"毎朝: every morning; 「毎〜」 marks a repeated habit and doesn't take 「に」","grammar:91334:ex2:trans":"I turned on the radio in the car.","grammar:91334:ex2:structure":"〔place〕で＋ラジオをつける","grammar:91334:ex2:words:0:zh":"car","grammar:91334:ex2:words:0:note":"くるま","grammar:91334:ex2:words:0:pos":"noun","grammar:91334:ex2:words:1:zh":"'s","grammar:91334:ex2:words:1:pos":"particle","grammar:91334:ex2:words:2:zh":"inside","grammar:91334:ex2:words:2:note":"なか","grammar:91334:ex2:words:2:pos":"noun","grammar:91334:ex2:words:3:zh":"at / in (where the action happens)","grammar:91334:ex2:words:3:pos":"particle","grammar:91334:ex2:words:4:zh":"radio","grammar:91334:ex2:words:4:pos":"noun","grammar:91334:ex2:words:5:zh":"(object marker)","grammar:91334:ex2:words:5:pos":"particle","grammar:91334:ex2:words:6:zh":"opened","grammar:91334:ex2:words:6:note":"つけました; the past masu-form of つける","grammar:91334:ex2:words:6:pos":"verb","grammar:91334:ex2:points:0":"ラジオをつける: turn on the radio; to turn it off, 「ラジオを消す（けす）」","grammar:91334:ex2:points:1":"Appliances switch on and off with 「つける／消す」 — TV, lights, air conditioning, all the same","exam:91334:zh":"This radio is for listening to news and music, and unlike a TV you can't watch images on it.","exam:91334:why":"「ラジオ」 delivers news, music, and other content through sound. 「テレビ」 can also play news and music, but it shows images, so it doesn't fit the second half of the sentence."},"91335":{"example:91335:exzh":"There are many international students at this university.","example:91335:exzh2":"I'm an international student from Taiwan.","grammar:91335:ex:trans":"This university has a lot of international students.","grammar:91335:ex:structure":"〔place〕には＋〔person〕がたくさんいます","grammar:91335:ex:explain":"「留学生」 is read りゅうがくせい — note the contracted りゅう for 「留」. This is the existence pattern 「〔place〕に〔person〕がいます」; the subject is a person, so it takes 「います」, not 「あります」.","grammar:91335:ex:words:0:zh":"this","grammar:91335:ex:words:0:pos":"pre-noun adjectival","grammar:91335:ex:words:1:zh":"university","grammar:91335:ex:words:1:note":"だいがく","grammar:91335:ex:words:1:pos":"noun","grammar:91335:ex:words:2:zh":"in (the place where something exists)","grammar:91335:ex:words:2:pos":"particle","grammar:91335:ex:words:3:zh":"(topic)","grammar:91335:ex:words:3:pos":"particle","grammar:91335:ex:words:4:zh":"international student","grammar:91335:ex:words:4:note":"りゅうがくせい","grammar:91335:ex:words:4:pos":"noun","grammar:91335:ex:words:5:zh":"(nominative)","grammar:91335:ex:words:5:pos":"particle","grammar:91335:ex:words:6:zh":"a lot","grammar:91335:ex:words:6:pos":"adverb","grammar:91335:ex:words:7:zh":"there is / to exist","grammar:91335:ex:words:7:note":"います; the masu-form of いる","grammar:91335:ex:words:7:pos":"verb","grammar:91335:ex:points:0":"留学生 = a student studying abroad; 「留学する」 means to study abroad","grammar:91335:ex:points:1":"People take 「います」: 留学生がいます; only things take 「あります」","grammar:91335:ex2:trans":"I'm an international student from Taiwan.","grammar:91335:ex2:structure":"私は＋〔place〕から来た＋留学生です","grammar:91335:ex2:words:0:zh":"I","grammar:91335:ex2:words:0:note":"わたし","grammar:91335:ex2:words:0:pos":"pronoun","grammar:91335:ex2:words:1:zh":"(topic)","grammar:91335:ex2:words:1:pos":"particle","grammar:91335:ex2:words:2:zh":"Taiwan","grammar:91335:ex2:words:2:note":"たいわん","grammar:91335:ex2:words:2:pos":"noun","grammar:91335:ex2:words:3:zh":"from","grammar:91335:ex2:words:3:pos":"particle","grammar:91335:ex2:words:4:zh":"who came","grammar:91335:ex2:words:4:note":"きた; the ta-form of 来る, modifying the noun that follows","grammar:91335:ex2:words:4:pos":"verb","grammar:91335:ex2:words:5:zh":"international student","grammar:91335:ex2:words:5:note":"りゅうがくせい","grammar:91335:ex2:words:5:pos":"noun","grammar:91335:ex2:words:6:zh":"is (polite form)","grammar:91335:ex2:words:6:pos":"copula","grammar:91335:ex2:points:0":"A common self-introduction: 〔country〕から来た留学生です = I'm an international student from ~","grammar:91335:ex2:points:1":"The ta-form of a verb can sit directly before a noun to modify it: 来た留学生 = an international student who came from there","exam:91335:zh":"I'm an international student who came from abroad to study at a Japanese university.","exam:91335:why":"「留学生」 is a student who goes to another country to study. 「先生」 is a teacher, which is different from the role of coming to a university to study."},"91336":{"example:91336:exzh":"Please put the milk in the refrigerator.","example:91336:exzh2":"There is nothing in the refrigerator.","grammar:91336:ex:trans":"Please put the milk in the fridge.","grammar:91336:ex:structure":"〔thing〕は＋冷蔵庫に入れてください","grammar:91336:ex:explain":"「冷蔵庫」 literally means \"cold storage warehouse\" — the fridge. Here 「牛乳」 is picked out with 「は」 as the topic before saying \"put it in the fridge\", which adds an \"as for the milk\" flavour compared with 「牛乳を冷蔵庫に入れて」. 「〔place〕に入れる」 is the basic pattern for putting something somewhere.","grammar:91336:ex:words:0:zh":"milk","grammar:91336:ex:words:0:note":"ぎゅうにゅう","grammar:91336:ex:words:0:pos":"noun","grammar:91336:ex:words:1:zh":"(topic)","grammar:91336:ex:words:1:pos":"particle","grammar:91336:ex:words:2:zh":"refrigerator","grammar:91336:ex:words:2:note":"れいぞうこ","grammar:91336:ex:words:2:pos":"noun","grammar:91336:ex:words:3:zh":"into (the place it goes)","grammar:91336:ex:words:3:pos":"particle","grammar:91336:ex:words:4:zh":"put in","grammar:91336:ex:words:4:note":"いれて; te-form of 入れる","grammar:91336:ex:words:4:pos":"verb","grammar:91336:ex:words:5:zh":"please ~","grammar:91336:ex:words:5:note":"ください; the imperative form of くださる","grammar:91336:ex:words:5:pos":"auxiliary verb","grammar:91336:ex:points:1":"〔place〕に入れる: put into ~; 「に」 marks where the thing ends up. 「〜てください」 = please ~","grammar:91336:ex2:trans":"There's nothing in the fridge.","grammar:91336:ex2:structure":"〔place〕に＋何もありません","grammar:91336:ex2:words:0:zh":"refrigerator","grammar:91336:ex2:words:0:note":"れいぞうこ","grammar:91336:ex2:words:0:pos":"noun","grammar:91336:ex2:words:1:zh":"in (the place where something exists)","grammar:91336:ex2:words:1:pos":"particle","grammar:91336:ex2:words:2:zh":"what","grammar:91336:ex2:words:2:note":"なに","grammar:91336:ex2:words:2:pos":"question word","grammar:91336:ex2:words:3:zh":"(with a negative) nothing at all","grammar:91336:ex2:words:3:pos":"particle","grammar:91336:ex2:words:4:zh":"don't have","grammar:91336:ex2:words:4:note":"ありません; the negative masu-form of ある","grammar:91336:ex2:words:4:pos":"verb","grammar:91336:ex2:points:0":"冷蔵庫に〜: in the fridge (where something exists takes 「に」)","grammar:91336:ex2:points:1":"何も + negative: nothing at all; 「何もありません」 is a set phrase","exam:91336:zh":"So the milk doesn't get warm, put it back in the fridge right after drinking.","exam:91336:why":"「冷蔵庫」 keeps milk cold. 「電子レンジ」 is a microwave, used to heat food, so it can't keep things cold."},"91337":{"example:91337:exzh":"I wear a white dress shirt to the office.","example:91337:exzh2":"I ironed the dress shirt.","grammar:91337:ex:trans":"I go to work in a white shirt.","grammar:91337:ex:structure":"〔clothes〕を着て＋〔place〕に行きます","grammar:91337:ex:explain":"「ワイシャツ」 comes from English \"white shirt\" and means a dress shirt worn with a suit — not necessarily white. The te-form links the two actions, dressing and going to work, so you put it on first and then leave. 「白い」 is an adjective and can sit straight in front of the noun.","grammar:91337:ex:words:0:zh":"white","grammar:91337:ex:words:0:note":"しろい","grammar:91337:ex:words:0:pos":"adjective","grammar:91337:ex:words:1:zh":"(men's) dress shirt","grammar:91337:ex:words:1:pos":"noun","grammar:91337:ex:words:2:zh":"(object marker)","grammar:91337:ex:words:2:pos":"particle","grammar:91337:ex:words:3:zh":"Wearing","grammar:91337:ex:words:3:note":"きて; the te-form of 着る","grammar:91337:ex:words:3:pos":"verb","grammar:91337:ex:words:4:zh":"company","grammar:91337:ex:words:4:note":"かいしゃ","grammar:91337:ex:words:4:pos":"noun","grammar:91337:ex:words:5:zh":"to (the destination)","grammar:91337:ex:words:5:pos":"particle","grammar:91337:ex:words:6:zh":"go","grammar:91337:ex:words:6:note":"いきます; masu-form of 行く","grammar:91337:ex:words:6:pos":"verb","grammar:91337:ex:points:0":"ワイシャツ = a collared button-up shirt for work (from \"white shirt\"); a plain shirt or T-shirt is just 「シャツ」","grammar:91337:ex:points:1":"The te-form joins two actions: 「着て、行きます」 = put it on, then go","grammar:91337:ex2:trans":"I ironed my shirt.","grammar:91337:ex2:structure":"〔clothes〕に＋アイロンをかける","grammar:91337:ex2:words:0:zh":"(men's) dress shirt","grammar:91337:ex2:words:0:pos":"noun","grammar:91337:ex2:words:1:zh":"(the target of the action)","grammar:91337:ex2:words:1:pos":"particle","grammar:91337:ex2:words:2:zh":"the appliance used to press clothes","grammar:91337:ex2:words:2:pos":"noun","grammar:91337:ex2:words:3:zh":"(object marker)","grammar:91337:ex2:words:3:pos":"particle","grammar:91337:ex2:words:4:zh":"ironed (clothes)","grammar:91337:ex2:words:4:note":"かけました; the past masu-form of かける","grammar:91337:ex2:words:4:pos":"verb","grammar:91337:ex2:points:0":"ワイシャツにアイロンをかける: iron a shirt; the shirt being ironed takes 「に」","grammar:91337:ex2:points:1":"アイロンをかける = to iron; it's a fixed pairing, so memorize it as one chunk","exam:91337:zh":"My father passed his tie under the collar of his shirt.","exam:91337:why":"「ワイシャツ」 is a shirt and has a collar you can put a tie through. 「ズボン」 are trousers and have no collar."},"91338":{"example:91338:exzh":"He stood up quickly.","example:91338:exzh2":"Someone listened to what I had to say, and I felt relieved.","grammar:91338:ex:trans":"He stood up at once.","grammar:91338:ex:structure":"〔person〕は＋すっと＋立ち上がる","grammar:91338:ex:explain":"「すっと」 describes a movement that is light, smooth and over in an instant; here it shows him getting to his feet without hesitation. It can also describe a feeling of relief (see the next sentence). It's close to 「さっと」, but 「すっと」 carries a stronger sense of quiet smoothness.","grammar:91338:ex:words:0:zh":"he","grammar:91338:ex:words:0:note":"かれ","grammar:91338:ex:words:0:pos":"pronoun","grammar:91338:ex:words:1:zh":"(topic)","grammar:91338:ex:words:1:pos":"particle","grammar:91338:ex:words:2:zh":"smoothly and briskly","grammar:91338:ex:words:2:pos":"adverb","grammar:91338:ex:words:3:zh":"stood up","grammar:91338:ex:words:3:note":"たちあがりました; the past masu-form of 立ち上がる","grammar:91338:ex:words:3:pos":"verb","grammar:91338:ex:points:0":"すっと = quick and smooth, without extra noise: すっと立つ, すっと手を出す","grammar:91338:ex:points:1":"立ち上がる: to get up from a sitting position","grammar:91338:ex2:trans":"After someone heard me out, I felt a weight lift.","grammar:91338:ex2:structure":"〜てもらって、＋気持ちがすっとする","grammar:91338:ex2:words:0:zh":"talk; story","grammar:91338:ex2:words:0:note":"はなし","grammar:91338:ex2:words:0:pos":"noun","grammar:91338:ex2:words:1:zh":"(object marker)","grammar:91338:ex2:words:1:pos":"particle","grammar:91338:ex2:words:2:zh":"listen","grammar:91338:ex2:words:2:note":"きいて; the te-form of 聞く","grammar:91338:ex2:words:2:pos":"verb","grammar:91338:ex2:words:3:zh":"(someone does something for me)","grammar:91338:ex2:words:3:note":"もらって; the te-form of もらう","grammar:91338:ex2:words:3:pos":"auxiliary verb","grammar:91338:ex2:words:4:zh":"feeling","grammar:91338:ex2:words:4:note":"きもち","grammar:91338:ex2:words:4:pos":"noun","grammar:91338:ex2:words:5:zh":"(nominative)","grammar:91338:ex2:words:5:pos":"particle","grammar:91338:ex2:words:6:zh":"(feeling) lighter","grammar:91338:ex2:words:6:pos":"adverb","grammar:91338:ex2:words:7:zh":"became (lighter)","grammar:91338:ex2:words:7:note":"しました; the past masu-form of する","grammar:91338:ex2:words:7:pos":"verb","grammar:91338:ex2:points:0":"気持ちがすっとする: the heaviness inside clears all at once and you feel light and refreshed","grammar:91338:ex2:points:1":"〜てもらう: have someone do ~ for me (and I'm grateful for it); 「聞いてもらう」 = have someone listen to me"},"91339":{"example:91339:exzh":"Summer vacation has finally arrived.","example:91339:exzh2":"I waited and waited, but in the end he never came.","grammar:91339:ex:trans":"Summer vacation has finally arrived.","grammar:91339:ex:structure":"とうとう＋〔thing〕が来ました","grammar:91339:ex:explain":"「とうとう」 means that after a stretch of time something finally happens, and here it carries a sense of long-awaited expectation. It can also be used for bad outcomes (see the next sentence), which is where it differs from 「やっと」, used only for good ones.","grammar:91339:ex:words:0:zh":"finally","grammar:91339:ex:words:0:pos":"adverb","grammar:91339:ex:words:1:zh":"summer vacation","grammar:91339:ex:words:1:note":"なつやすみ","grammar:91339:ex:words:1:pos":"noun","grammar:91339:ex:words:2:zh":"(nominative)","grammar:91339:ex:words:2:pos":"particle","grammar:91339:ex:words:3:zh":"came","grammar:91339:ex:words:3:note":"きました; the polite past form of 来る","grammar:91339:ex:words:3:pos":"verb","grammar:91339:ex:points:0":"とうとう = after a long wait, something finally happens; it usually goes with the past tense","grammar:91339:ex:points:1":"夏休み = summer vacation; 冬休み（ふゆやすみ） = winter vacation","grammar:91339:ex2:trans":"I waited and waited, but in the end he never came.","grammar:91339:ex2:structure":"〜ていたのに、＋とうとう〜ませんでした","grammar:91339:ex2:words:0:zh":"wait","grammar:91339:ex2:words:0:note":"まって; the te-form of 待つ","grammar:91339:ex2:words:0:pos":"verb","grammar:91339:ex2:words:1:zh":"was ~ing (the whole time)","grammar:91339:ex2:words:1:note":"いた; ta-form of いる","grammar:91339:ex2:words:1:pos":"auxiliary verb","grammar:91339:ex2:words:2:zh":"even though ~","grammar:91339:ex2:words:2:pos":"particle","grammar:91339:ex2:words:3:zh":"he","grammar:91339:ex2:words:3:note":"かれ","grammar:91339:ex2:words:3:pos":"pronoun","grammar:91339:ex2:words:4:zh":"(topic)","grammar:91339:ex2:words:4:pos":"particle","grammar:91339:ex2:words:5:zh":"in the end (still)","grammar:91339:ex2:words:5:pos":"adverb","grammar:91339:ex2:words:6:zh":"didn't come","grammar:91339:ex2:words:6:note":"きませんでした; the past negative masu-form of 来る","grammar:91339:ex2:words:6:pos":"verb","grammar:91339:ex2:points:0":"とうとう + negative: in the end still didn't ~; the result is disappointing","grammar:91339:ex2:points:1":"〜のに: even though ~; the result goes against expectation and carries a note of complaint"},"91340":{"example:91340:exzh":"This medicine is very bitter.","example:91340:exzh2":"Coffee is bitter if you don't add sugar.","grammar:91340:ex:trans":"This medicine is very bitter.","grammar:91340:ex:structure":"〔thing〕は＋とても苦いです","grammar:91340:ex:explain":"「苦い」 is an i-adjective for a bitter taste, used for medicine, coffee, bitter melon. It can also describe an unpleasant experience, as in 「苦い思い出（bitter memories）」. Watch out for 「苦しい（くるしい）」, which means painful or hard going — same kanji, different meaning and reading.","grammar:91340:ex:words:0:zh":"this","grammar:91340:ex:words:0:pos":"pre-noun adjectival","grammar:91340:ex:words:1:zh":"medicine","grammar:91340:ex:words:1:note":"くすり","grammar:91340:ex:words:1:pos":"noun","grammar:91340:ex:words:2:zh":"(topic)","grammar:91340:ex:words:2:pos":"particle","grammar:91340:ex:words:3:zh":"extremely","grammar:91340:ex:words:3:pos":"adverb","grammar:91340:ex:words:4:zh":"bitter","grammar:91340:ex:words:4:note":"にがい","grammar:91340:ex:words:4:pos":"adjective","grammar:91340:ex:words:5:zh":"is (polite form)","grammar:91340:ex:words:5:pos":"copula","grammar:91340:ex:points:0":"苦い = bitter; other tastes: 甘い (sweet), 辛い (spicy), 酸っぱい (sour)","grammar:91340:ex:points:1":"i-adjective + です is the polite form: 苦いです","grammar:91340:ex2:trans":"Without sugar, coffee is bitter.","grammar:91340:ex2:structure":"〜ないと、＋〔thing〕は苦いです","grammar:91340:ex2:words:0:zh":"sugar","grammar:91340:ex2:words:0:note":"さとう","grammar:91340:ex2:words:0:pos":"noun","grammar:91340:ex2:words:1:zh":"(object marker)","grammar:91340:ex2:words:1:pos":"particle","grammar:91340:ex2:words:2:zh":"don't add","grammar:91340:ex2:words:2:note":"いれない; the nai-form of 入れる","grammar:91340:ex2:words:2:pos":"verb","grammar:91340:ex2:words:3:zh":"if ~","grammar:91340:ex2:words:3:pos":"particle","grammar:91340:ex2:words:4:zh":"coffee","grammar:91340:ex2:words:4:pos":"noun","grammar:91340:ex2:words:5:zh":"(topic)","grammar:91340:ex2:words:5:pos":"particle","grammar:91340:ex2:words:6:zh":"bitter","grammar:91340:ex2:words:6:note":"にがい","grammar:91340:ex2:words:6:pos":"adjective","grammar:91340:ex2:words:7:zh":"is (polite form)","grammar:91340:ex2:words:7:pos":"copula","grammar:91340:ex2:points:0":"苦い often describes coffee, medicine and beer","grammar:91340:ex2:points:1":"〜と: whenever ~, then ~; a conditional meaning that as long as ~ holds, ~ necessarily follows"},"91341":{"example:91341:exzh":"I put a new stereo in the room.","example:91341:exzh2":"I listen to music on the stereo.","grammar:91341:ex:trans":"I put a new stereo in my room.","grammar:91341:ex:structure":"〔place〕に＋〔thing〕を置く","grammar:91341:ex:explain":"「ステレオ」 originally meant stereo sound, and in Japanese it also refers to the audio system you listen to at home. This sentence uses 「〔place〕に〔thing〕を置く」 to show where something is placed, and 「新しい」 is an adjective sitting straight in front of the noun it modifies.","grammar:91341:ex:words:0:zh":"room","grammar:91341:ex:words:0:note":"へや","grammar:91341:ex:words:0:pos":"noun","grammar:91341:ex:words:1:zh":"at (the place where something is placed)","grammar:91341:ex:words:1:pos":"particle","grammar:91341:ex:words:2:zh":"new","grammar:91341:ex:words:2:note":"あたらしい","grammar:91341:ex:words:2:pos":"adjective","grammar:91341:ex:words:3:zh":"acoustics","grammar:91341:ex:words:3:pos":"noun","grammar:91341:ex:words:4:zh":"(object marker)","grammar:91341:ex:words:4:pos":"particle","grammar:91341:ex:words:5:zh":"put","grammar:91341:ex:words:5:note":"okimashita; masu-form past of 置く","grammar:91341:ex:words:5:pos":"verb","grammar:91341:ex:points:0":"ステレオ = stereo system (from the English word stereo); these days 「オーディオ」 is also common","grammar:91341:ex:points:1":"〔place〕に置く: to put something in a place","grammar:91341:ex2:trans":"I listen to music on the stereo.","grammar:91341:ex2:structure":"〔tool〕で＋音楽を聞きます","grammar:91341:ex2:words:0:zh":"acoustics","grammar:91341:ex2:words:0:pos":"noun","grammar:91341:ex2:words:1:zh":"with (a tool)","grammar:91341:ex2:words:1:pos":"particle","grammar:91341:ex2:words:2:zh":"music","grammar:91341:ex2:words:2:note":"おんがく","grammar:91341:ex2:words:2:pos":"noun","grammar:91341:ex2:words:3:zh":"(object marker)","grammar:91341:ex2:words:3:pos":"particle","grammar:91341:ex2:words:4:zh":"listen","grammar:91341:ex2:words:4:note":"ききます; the masu-form of 聞く","grammar:91341:ex2:words:4:pos":"verb","grammar:91341:ex2:points:0":"ステレオで聞く: to listen with the stereo","grammar:91341:ex2:points:1":"Tools and methods take 「で」"},"91342":{"example:91342:exzh":"Please open the textbook to page 20.","example:91342:exzh2":"I read the textbook in advance before class.","grammar:91342:ex:trans":"Please open your textbook to page 20.","grammar:91342:ex:structure":"テキストの〔number〕ページを＋開いてください","grammar:91342:ex:explain":"In Japanese classes, 「テキスト」 usually means the textbook or handout used in class, and teachers say this sentence all the time. For opening a book or notebook, use 「開く（ひらく）」; for opening doors and windows, 「開ける（あける）」 is more common.","grammar:91342:ex:words:0:zh":"textbook","grammar:91342:ex:words:0:pos":"noun","grammar:91342:ex:words:1:zh":"'s","grammar:91342:ex:words:1:pos":"particle","grammar:91342:ex:words:2:zh":"twenty","grammar:91342:ex:words:2:note":"にじゅう","grammar:91342:ex:words:2:pos":"numeral","grammar:91342:ex:words:3:zh":"page","grammar:91342:ex:words:3:pos":"suffix","grammar:91342:ex:words:4:zh":"(object marker)","grammar:91342:ex:words:4:pos":"particle","grammar:91342:ex:words:5:zh":"open","grammar:91342:ex:words:5:note":"hiraite; te-form of 開く（ひらく）","grammar:91342:ex:words:5:pos":"verb","grammar:91342:ex:words:6:zh":"please ~","grammar:91342:ex:words:6:note":"ください; the imperative form of くださる","grammar:91342:ex:words:6:pos":"auxiliary verb","grammar:91342:ex:points:1":"For opening a book, use 「開く（ひらく）」; 〜てください = please do ~","grammar:91342:ex2:trans":"I'll read the textbook before class.","grammar:91342:ex2:structure":"〜の前に、＋〔verb te-form〕おきます","grammar:91342:ex2:words:0:zh":"class, lesson","grammar:91342:ex2:words:0:note":"じゅぎょう","grammar:91342:ex2:words:0:pos":"noun","grammar:91342:ex2:words:1:zh":"'s","grammar:91342:ex2:words:1:pos":"particle","grammar:91342:ex2:words:2:zh":"before","grammar:91342:ex2:words:2:note":"まえ","grammar:91342:ex2:words:2:pos":"noun","grammar:91342:ex2:words:3:zh":"(point in time)","grammar:91342:ex2:words:3:pos":"particle","grammar:91342:ex2:words:4:zh":"teaching material","grammar:91342:ex2:words:4:pos":"noun","grammar:91342:ex2:words:5:zh":"(object marker)","grammar:91342:ex2:words:5:pos":"particle","grammar:91342:ex2:words:6:zh":"read","grammar:91342:ex2:words:6:note":"yonde; te-form of 読む","grammar:91342:ex2:words:6:pos":"verb","grammar:91342:ex2:words:7:zh":"(do) in advance","grammar:91342:ex2:words:7:note":"okimasu; masu-form of おく","grammar:91342:ex2:words:7:pos":"auxiliary verb","grammar:91342:ex2:points:0":"授業の前にテキストを読む: to read the textbook before class","grammar:91342:ex2:points:1":"〜ておく: to do something in advance (so it's easier later)"},"91343":{"example:91343:exzh":"I broke a bone in my leg while skiing.","example:91343:exzh2":"Please fold the paper in half.","grammar:91343:ex:trans":"I broke a bone in my leg skiing.","grammar:91343:ex:structure":"〔cause〕で＋〔body part〕の骨を折る","grammar:91343:ex:explain":"「折る」 basically means to bend or snap something long and thin, so 「骨を折る」 means to break a bone. Even when it happens through your own carelessness, Japanese still uses the transitive verb 「折る」 with 「を」. 「骨を折る」 also has the figurative meaning of taking great pains over something.","grammar:91343:ex:words:0:zh":"skiing","grammar:91343:ex:words:0:pos":"noun","grammar:91343:ex:words:1:zh":"because of (cause)","grammar:91343:ex:words:1:pos":"particle","grammar:91343:ex:words:2:zh":"leg, foot","grammar:91343:ex:words:2:note":"あし","grammar:91343:ex:words:2:pos":"noun","grammar:91343:ex:words:3:zh":"'s","grammar:91343:ex:words:3:pos":"particle","grammar:91343:ex:words:4:zh":"bone","grammar:91343:ex:words:4:note":"ほね","grammar:91343:ex:words:4:pos":"noun","grammar:91343:ex:words:5:zh":"(object marker)","grammar:91343:ex:words:5:pos":"particle","grammar:91343:ex:words:6:zh":"broke","grammar:91343:ex:words:6:note":"orimashita; masu-form past of 折る","grammar:91343:ex:words:6:pos":"verb","grammar:91343:ex:points:0":"骨を折る = to break a bone; Japanese expresses fracturing a bone as breaking the bone","grammar:91343:ex:points:1":"スキーで: because of skiing; 「で」 can mark a cause","grammar:91343:ex2:trans":"Please fold the paper in half.","grammar:91343:ex2:structure":"〔thing〕を半分に＋折る","grammar:91343:ex2:words:0:zh":"paper","grammar:91343:ex2:words:0:note":"かみ","grammar:91343:ex2:words:0:pos":"noun","grammar:91343:ex2:words:1:zh":"(object marker)","grammar:91343:ex2:words:1:pos":"particle","grammar:91343:ex2:words:2:zh":"half","grammar:91343:ex2:words:2:note":"はんぶん","grammar:91343:ex2:words:2:pos":"noun","grammar:91343:ex2:words:3:zh":"(the resulting color)","grammar:91343:ex2:words:3:pos":"particle","grammar:91343:ex2:words:4:zh":"fold","grammar:91343:ex2:words:4:note":"otte; te-form of 折る","grammar:91343:ex2:words:4:pos":"verb","grammar:91343:ex2:words:5:zh":"please ~","grammar:91343:ex2:words:5:note":"ください; the imperative form of くださる","grammar:91343:ex2:words:5:pos":"auxiliary verb","grammar:91343:ex2:points:0":"紙を折る = to fold paper; 「折り紙（おりがみ）」 (origami) comes from this","grammar:91343:ex2:points:1":"半分に: into half; 「に」 shows the resulting state"},"91344":{"example:91344:exzh":"My little brother broke my toy.","example:91344:exzh2":"I ate too much and got an upset stomach.","grammar:91344:ex:trans":"My little brother broke my toy.","grammar:91344:ex:structure":"〔person〕が＋〔thing〕を壊す","grammar:91344:ex:explain":"「壊す」 means someone makes something break, so the subject is the person who did it (the little brother) and the thing takes 「を」. To simply say that something broke, use the intransitive 「壊れる」. The pair 「壊す／壊れる」 is a very important transitive/intransitive pair at N4.","grammar:91344:ex:words:0:zh":"younger brother","grammar:91344:ex:words:0:note":"おとうと","grammar:91344:ex:words:0:pos":"noun","grammar:91344:ex:words:1:zh":"(nominative)","grammar:91344:ex:words:1:pos":"particle","grammar:91344:ex:words:2:zh":"I","grammar:91344:ex:words:2:note":"わたし","grammar:91344:ex:words:2:pos":"pronoun","grammar:91344:ex:words:3:zh":"'s","grammar:91344:ex:words:3:pos":"particle","grammar:91344:ex:words:4:zh":"toy","grammar:91344:ex:words:4:pos":"noun","grammar:91344:ex:words:5:zh":"(object marker)","grammar:91344:ex:words:5:pos":"particle","grammar:91344:ex:words:6:zh":"broke","grammar:91344:ex:words:6:note":"kowashimashita; masu-form past of 壊す","grammar:91344:ex:words:6:pos":"verb","grammar:91344:ex:points:0":"壊す = (someone) breaks something; it's a transitive verb, so it takes 「を」","grammar:91344:ex:points:1":"When something breaks on its own, use 「壊れる」: おもちゃが壊れました","grammar:91344:ex2:trans":"I ate too much and got an upset stomach.","grammar:91344:ex2:structure":"〜すぎて、＋おなかを壊す","grammar:91344:ex2:words:0:zh":"eat","grammar:91344:ex2:words:0:note":"たべ; the masu-form stem of 食べる","grammar:91344:ex2:words:0:pos":"verb","grammar:91344:ex2:words:1:zh":"too much, over-","grammar:91344:ex2:words:1:note":"sugite; te-form of すぎる","grammar:91344:ex2:words:1:pos":"suffix","grammar:91344:ex2:words:2:zh":"stomach","grammar:91344:ex2:words:2:pos":"noun","grammar:91344:ex2:words:3:zh":"(object marker)","grammar:91344:ex2:words:3:pos":"particle","grammar:91344:ex2:words:4:zh":"ruined (my stomach)","grammar:91344:ex2:words:4:note":"kowashimashita; masu-form past of 壊す","grammar:91344:ex2:words:4:pos":"verb","grammar:91344:ex2:points:0":"おなかを壊す = to get an upset stomach or diarrhea; a set phrase","grammar:91344:ex2:points:1":"〜すぎる: too much, excessively; attaches to the stem of the masu-form: 食べすぎる"},"91345":{"example:91345:exzh":"I exercise in the park every morning.","example:91345:exzh2":"You should exercise for your health.","grammar:91345:ex:trans":"I exercise in the park every morning.","grammar:91345:ex:structure":"〔place〕で＋運動します","grammar:91345:ex:explain":"In Japanese, 「運動」 mainly means physical activity for your health, though it can also mean a social movement. 「運動する」 is a noun＋する verb, like 「勉強する」 and 「散歩する」. Note that sports and athletic events are usually called 「スポーツ」 in Japanese.","grammar:91345:ex:words:0:zh":"every morning","grammar:91345:ex:words:0:note":"まいあさ","grammar:91345:ex:words:0:pos":"noun","grammar:91345:ex:words:1:zh":"park","grammar:91345:ex:words:1:note":"こうえん","grammar:91345:ex:words:1:pos":"noun","grammar:91345:ex:words:2:zh":"at / in (where the action happens)","grammar:91345:ex:words:2:pos":"particle","grammar:91345:ex:words:3:zh":"exercise","grammar:91345:ex:words:3:note":"undō shimasu; masu-form of 運動する","grammar:91345:ex:words:3:pos":"verb","grammar:91345:ex:points:0":"運動する = to exercise, to work out; adding 「する」 to the noun 「運動」 turns it into a verb","grammar:91345:ex:points:1":"The place where an action happens takes 「で」: 公園で運動する","grammar:91345:ex2:trans":"It's best to exercise for your health.","grammar:91345:ex2:structure":"〜のために、＋〔verb ta-form〕ほうがいいです","grammar:91345:ex2:words:0:zh":"health","grammar:91345:ex2:words:0:note":"けんこう","grammar:91345:ex2:words:0:pos":"noun","grammar:91345:ex2:words:1:zh":"'s","grammar:91345:ex2:words:1:pos":"particle","grammar:91345:ex2:words:2:zh":"for the sake of","grammar:91345:ex2:words:2:pos":"formal noun","grammar:91345:ex2:words:3:zh":"exercise","grammar:91345:ex2:words:3:note":"undō shita; ta-form of 運動する","grammar:91345:ex2:words:3:pos":"verb","grammar:91345:ex2:words:4:zh":"(the ~ side / option)","grammar:91345:ex2:words:4:pos":"formal noun","grammar:91345:ex2:words:5:zh":"(nominative)","grammar:91345:ex2:words:5:pos":"particle","grammar:91345:ex2:words:6:zh":"good","grammar:91345:ex2:words:6:note":"いい","grammar:91345:ex2:words:6:pos":"adjective","grammar:91345:ex2:words:7:zh":"is (polite form)","grammar:91345:ex2:words:7:pos":"copula","grammar:91345:ex2:points:0":"〜たほうがいい: it's better to ~; used to give advice","grammar:91345:ex2:points:1":"〔noun〕のために: for the sake of ~"},"91346":{"example:91346:exzh":"Let's go out once the rain stops.","example:91346:exzh2":"The wind stopped when night fell.","grammar:91346:ex:trans":"Let's go out once the rain stops.","grammar:91346:ex:structure":"雨が止んだら、＋〜ましょう","grammar:91346:ex:explain":"「止む」 is read やむ and means that a natural phenomenon such as rain, snow, wind, or a sound stops; it can't be used for cars or machines (for a vehicle stopping, use 「止まる」). This sentence uses 「〜たら」 for after the rain stops, then 「〜ましょう」 to invite someone to go out together.","grammar:91346:ex:words:0:zh":"rain","grammar:91346:ex:words:0:note":"あめ","grammar:91346:ex:words:0:pos":"noun","grammar:91346:ex:words:1:zh":"(nominative)","grammar:91346:ex:words:1:pos":"particle","grammar:91346:ex:words:2:zh":"if/when it stops","grammar:91346:ex:words:2:note":"yandara; tara-form of 止む","grammar:91346:ex:words:2:pos":"verb","grammar:91346:ex:words:3:zh":"let's go out","grammar:91346:ex:words:3:note":"dekakemashō; masu-form of 出かける＋ましょう","grammar:91346:ex:words:3:pos":"verb","grammar:91346:ex:points:0":"止む = for rain, wind, sound, and so on to stop naturally; 「雨が止む」 is the most common combination","grammar:91346:ex:points:1":"〜たら: once ~; do the second thing after the first is done","grammar:91346:ex2:trans":"The wind stopped when night came.","grammar:91346:ex2:structure":"〔time〕になって、＋風が止みました","grammar:91346:ex2:words:0:zh":"evening","grammar:91346:ex2:words:0:note":"よる","grammar:91346:ex2:words:0:pos":"noun","grammar:91346:ex2:words:1:zh":"(the resulting color)","grammar:91346:ex2:words:1:pos":"particle","grammar:91346:ex2:words:2:zh":"becomes, turns into","grammar:91346:ex2:words:2:note":"なって; te-form of なる","grammar:91346:ex2:words:2:pos":"verb","grammar:91346:ex2:words:3:zh":"wind","grammar:91346:ex2:words:3:note":"かぜ","grammar:91346:ex2:words:3:pos":"noun","grammar:91346:ex2:words:4:zh":"(nominative)","grammar:91346:ex2:words:4:pos":"particle","grammar:91346:ex2:words:5:zh":"stopped","grammar:91346:ex2:words:5:note":"yamimashita; masu-form past of 止む","grammar:91346:ex2:words:5:pos":"verb","grammar:91346:ex2:points:0":"風が止む: the wind stops","grammar:91346:ex2:points:1":"〜になって: when it became ~ (a change in time)"},"91347":{"example:91347:exzh":"My older brother is a university student.","example:91347:exzh2":"When I was in college, I had a part-time job.","grammar:91347:ex:trans":"My older brother is a university student.","grammar:91347:ex:structure":"〔person〕は＋大学生です","grammar:91347:ex:explain":"「大学生」 is read だいがくせい. In Japanese, student status is expressed as 〔school〕＋生, as in 「高校生」 and 「中学生」. 「兄」 is used when talking about your own older brother to outsiders; for someone else's older brother, say 「お兄さん」.","grammar:91347:ex:words:0:zh":"older brother","grammar:91347:ex:words:0:note":"ani; used when mentioning your own older brother to outsiders","grammar:91347:ex:words:0:pos":"noun","grammar:91347:ex:words:1:zh":"(topic)","grammar:91347:ex:words:1:pos":"particle","grammar:91347:ex:words:2:zh":"university student","grammar:91347:ex:words:2:note":"だいがくせい","grammar:91347:ex:words:2:pos":"noun","grammar:91347:ex:words:3:zh":"is (polite form)","grammar:91347:ex:words:3:pos":"copula","grammar:91347:ex:points:1":"〜は〜です: A is B, the most basic pattern","grammar:91347:ex2:trans":"When I was in university, I had a part-time job.","grammar:91347:ex2:structure":"大学生のとき、＋〜ていました","grammar:91347:ex2:words:0:zh":"university student","grammar:91347:ex2:words:0:note":"だいがくせい","grammar:91347:ex2:words:0:pos":"noun","grammar:91347:ex2:words:1:zh":"'s","grammar:91347:ex2:words:1:pos":"particle","grammar:91347:ex2:words:2:zh":"when ～","grammar:91347:ex2:words:2:pos":"formal noun","grammar:91347:ex2:words:3:zh":"part-time job","grammar:91347:ex2:words:3:pos":"noun","grammar:91347:ex2:words:4:zh":"(object marker)","grammar:91347:ex2:words:4:pos":"particle","grammar:91347:ex2:words:5:zh":"do","grammar:91347:ex2:words:5:note":"して; the te-form of する","grammar:91347:ex2:words:5:pos":"verb","grammar:91347:ex2:words:6:zh":"(was doing ~ at the time)","grammar:91347:ex2:words:6:note":"いました; the past masu-form of いる","grammar:91347:ex2:words:6:pos":"auxiliary verb","grammar:91347:ex2:points:0":"大学生のとき = when I was a university student; noun＋「のとき」","grammar:91347:ex2:points:1":"〜ていました: something you did continuously over a period in the past"},"91348":{"example:91348:exzh":"I asked a taxi driver for directions.","example:91348:exzh2":"My father is a bus driver.","grammar:91348:ex:trans":"I asked a taxi driver for directions.","grammar:91348:ex:structure":"〔person〕に＋道を聞く","grammar:91348:ex:explain":"「運転手」 is made of 「運転」 (driving) plus 「手」 (the person who does it), so it means driver. Here 「聞く」 means to ask, and the person you ask takes 「に」. 「道を聞く」 (to ask for directions) is a very useful set phrase.","grammar:91348:ex:words:0:zh":"taxi","grammar:91348:ex:words:0:pos":"noun","grammar:91348:ex:words:1:zh":"'s","grammar:91348:ex:words:1:pos":"particle","grammar:91348:ex:words:2:zh":"driver","grammar:91348:ex:words:2:note":"うんてんしゅ","grammar:91348:ex:words:2:pos":"noun","grammar:91348:ex:words:3:zh":"to (the person asked)","grammar:91348:ex:words:3:pos":"particle","grammar:91348:ex:words:4:zh":"road","grammar:91348:ex:words:4:note":"みち","grammar:91348:ex:words:4:pos":"noun","grammar:91348:ex:words:5:zh":"(object marker)","grammar:91348:ex:words:5:pos":"particle","grammar:91348:ex:words:6:zh":"asked","grammar:91348:ex:words:6:note":"kikimashita; masu-form past of 聞く","grammar:91348:ex:words:6:pos":"verb","grammar:91348:ex:points:0":"運転手 = a driver; タクシーの運転手, バスの運転手","grammar:91348:ex:points:1":"Besides to listen, 聞く also means to ask: 道を聞く = to ask for directions","grammar:91348:ex2:trans":"My father is a bus driver.","grammar:91348:ex2:structure":"〔person〕は＋〔vehicle〕の運転手です","grammar:91348:ex2:words:0:zh":"dad","grammar:91348:ex2:words:0:note":"ちち","grammar:91348:ex2:words:0:pos":"noun","grammar:91348:ex2:words:1:zh":"(topic)","grammar:91348:ex2:words:1:pos":"particle","grammar:91348:ex2:words:2:zh":"bus","grammar:91348:ex2:words:2:pos":"noun","grammar:91348:ex2:words:3:zh":"'s","grammar:91348:ex2:words:3:pos":"particle","grammar:91348:ex2:words:4:zh":"driver","grammar:91348:ex2:words:4:note":"うんてんしゅ","grammar:91348:ex2:words:4:pos":"noun","grammar:91348:ex2:words:5:zh":"is (polite form)","grammar:91348:ex2:words:5:pos":"copula","grammar:91348:ex2:points:0":"バスの運転手: bus driver; 「の」 links the vehicle","grammar:91348:ex2:points:1":"Introducing a job: 〜は〜です"},"91349":{"example:91349:exzh":"I'll preview tomorrow's lesson.","example:91349:exzh2":"If you preview beforehand, you'll understand the class much better.","grammar:91349:ex:trans":"I'm going to preview tomorrow's class material.","grammar:91349:ex:structure":"〔class〕の予習をします","grammar:91349:ex:explain":"The 「予」 in 「予習」 means beforehand, so it means reading ahead before class. Its opposite is 「復習」. This sentence uses 「〔class〕の予習をする」, linking the material you preview with 「の」.","grammar:91349:ex:words:0:zh":"tomorrow","grammar:91349:ex:words:0:note":"あした","grammar:91349:ex:words:0:pos":"noun","grammar:91349:ex:words:1:zh":"'s","grammar:91349:ex:words:1:pos":"particle","grammar:91349:ex:words:2:zh":"class","grammar:91349:ex:words:2:note":"じゅぎょう","grammar:91349:ex:words:2:pos":"noun","grammar:91349:ex:words:3:zh":"'s","grammar:91349:ex:words:3:pos":"particle","grammar:91349:ex:words:4:zh":"previewing (before class)","grammar:91349:ex:words:4:note":"よしゅう","grammar:91349:ex:words:4:pos":"noun","grammar:91349:ex:words:5:zh":"(object marker)","grammar:91349:ex:words:5:pos":"particle","grammar:91349:ex:words:6:zh":"do","grammar:91349:ex:words:6:note":"shimasu; masu-form of する","grammar:91349:ex:words:6:pos":"verb","grammar:91349:ex:points:1":"Both 予習をする and 予習する are fine","grammar:91349:ex2:trans":"If you preview in advance, you'll understand the class much better.","grammar:91349:ex2:structure":"〜ておけば、＋〜がよくわかります","grammar:91349:ex2:words:0:zh":"previewing (before class)","grammar:91349:ex2:words:0:note":"yoshū shite; te-form of 予習する","grammar:91349:ex2:words:0:pos":"verb","grammar:91349:ex2:words:1:zh":"if you do it in advance","grammar:91349:ex2:words:1:note":"okeba; conditional form of おく","grammar:91349:ex2:words:1:pos":"auxiliary verb","grammar:91349:ex2:words:2:zh":"class","grammar:91349:ex2:words:2:note":"じゅぎょう","grammar:91349:ex2:words:2:pos":"noun","grammar:91349:ex2:words:3:zh":"(nominative)","grammar:91349:ex2:words:3:pos":"particle","grammar:91349:ex2:words:4:zh":"clearly","grammar:91349:ex2:words:4:pos":"adverb","grammar:91349:ex2:words:5:zh":"to understand","grammar:91349:ex2:words:5:note":"wakarimasu; masu-form of わかる","grammar:91349:ex2:words:5:pos":"verb","grammar:91349:ex2:points:0":"予習しておく: to preview in advance","grammar:91349:ex2:points:1":"〜ば: if ~; 「〜ておけば」 = if you do it in advance"},"91350":{"example:91350:exzh":"I'm in a good mood today, so I feel relaxed.","example:91350:exzh2":"Please watch out for cars.","grammar:91350:ex:trans":"I'm in a good mood today, so I feel relaxed.","grammar:91350:ex:structure":"〜ので、＋気が楽です","grammar:91350:ex:explain":"「気」 means mind or spirit and is rarely used alone; it usually appears in fixed combinations like 「気が楽」, 「気をつける」, and 「気になる」. 「気が楽」 means feeling unburdened and relaxed. 「気分」, on the other hand, is your mood at the moment; the two are easy to confuse.","grammar:91350:ex:words:0:zh":"today","grammar:91350:ex:words:0:note":"きょう","grammar:91350:ex:words:0:pos":"noun","grammar:91350:ex:words:1:zh":"(topic)","grammar:91350:ex:words:1:pos":"particle","grammar:91350:ex:words:2:zh":"feeling","grammar:91350:ex:words:2:note":"きぶん","grammar:91350:ex:words:2:pos":"noun","grammar:91350:ex:words:3:zh":"(nominative)","grammar:91350:ex:words:3:pos":"particle","grammar:91350:ex:words:4:zh":"good","grammar:91350:ex:words:4:note":"いい","grammar:91350:ex:words:4:pos":"adjective","grammar:91350:ex:words:5:zh":"because","grammar:91350:ex:words:5:pos":"particle","grammar:91350:ex:words:6:zh":"heart, mind","grammar:91350:ex:words:6:note":"き","grammar:91350:ex:words:6:pos":"noun","grammar:91350:ex:words:7:zh":"(nominative)","grammar:91350:ex:words:7:pos":"particle","grammar:91350:ex:words:8:zh":"easier","grammar:91350:ex:words:8:note":"らく","grammar:91350:ex:words:8:pos":"na-adjective","grammar:91350:ex:words:9:zh":"is (polite form)","grammar:91350:ex:words:9:pos":"copula","grammar:91350:ex:points:0":"気が楽 = feeling light and free of pressure; 「気」 often forms idiomatic expressions with other words","grammar:91350:ex:points:1":"〜ので: because ~; gives a reason with a softer tone than 「から」","grammar:91350:ex2:trans":"Please watch out for cars.","grammar:91350:ex2:structure":"〔thing〕に＋気をつけてください","grammar:91350:ex2:words:0:zh":"car","grammar:91350:ex2:words:0:note":"くるま","grammar:91350:ex2:words:0:pos":"noun","grammar:91350:ex2:words:1:zh":"(the thing you watch out for)","grammar:91350:ex2:words:1:pos":"particle","grammar:91350:ex2:words:2:zh":"be careful","grammar:91350:ex2:words:2:note":"き","grammar:91350:ex2:words:2:pos":"noun","grammar:91350:ex2:words:3:zh":"(object marker)","grammar:91350:ex2:words:3:pos":"particle","grammar:91350:ex2:words:4:zh":"attach, add","grammar:91350:ex2:words:4:note":"つけて; the te-form of つける","grammar:91350:ex2:words:4:pos":"verb","grammar:91350:ex2:words:5:zh":"please ~","grammar:91350:ex2:words:5:note":"ください; the imperative form of くださる","grammar:91350:ex2:words:5:pos":"auxiliary verb","grammar:91350:ex2:points:0":"気をつける = to be careful, to watch out; the thing you watch out for takes 「に」","grammar:91350:ex2:points:1":"When parting, people often say 「気をつけて」, meaning take care"},"91351":{"example:91351:exzh":"Compared with last year, this year is hotter.","example:91351:exzh2":"I compared the prices at the two shops.","grammar:91351:ex:trans":"Compared with last year, this year is hotter.","grammar:91351:ex:structure":"〔A〕と比べて、＋〔B〕は〜","grammar:91351:ex:explain":"「比べる」 means to put two or more things together and compare them; 「〜と比べて」 is a very common way to compare, followed by the result. 「暑い」 is specifically about hot weather; for something hot to the touch, use 「熱い」.","grammar:91351:ex:words:0:zh":"last year","grammar:91351:ex:words:0:note":"きょねん","grammar:91351:ex:words:0:pos":"noun","grammar:91351:ex:words:1:zh":"with","grammar:91351:ex:words:1:pos":"particle","grammar:91351:ex:words:2:zh":"comparison","grammar:91351:ex:words:2:note":"kurabete; te-form of 比べる","grammar:91351:ex:words:2:pos":"verb","grammar:91351:ex:words:3:zh":"this year","grammar:91351:ex:words:3:note":"ことし","grammar:91351:ex:words:3:pos":"noun","grammar:91351:ex:words:4:zh":"(topic)","grammar:91351:ex:words:4:pos":"particle","grammar:91351:ex:words:5:zh":"hot","grammar:91351:ex:words:5:note":"あつい","grammar:91351:ex:words:5:pos":"adjective","grammar:91351:ex:words:6:zh":"is (polite form)","grammar:91351:ex:words:6:pos":"copula","grammar:91351:ex:points:0":"比べる = to compare; 〜と比べて = compared with ~","grammar:91351:ex:points:1":"今年 is read ことし, an irregular reading","grammar:91351:ex2:trans":"I compared the prices at two shops.","grammar:91351:ex2:structure":"〔thing〕を＋比べる","grammar:91351:ex2:words:0:zh":"two","grammar:91351:ex2:words:0:note":"ふたつ","grammar:91351:ex2:words:0:pos":"numeral","grammar:91351:ex2:words:1:zh":"'s","grammar:91351:ex2:words:1:pos":"particle","grammar:91351:ex2:words:2:zh":"store","grammar:91351:ex2:words:2:note":"みせ","grammar:91351:ex2:words:2:pos":"noun","grammar:91351:ex2:words:3:zh":"'s","grammar:91351:ex2:words:3:pos":"particle","grammar:91351:ex2:words:4:zh":"price","grammar:91351:ex2:words:4:note":"ねだん","grammar:91351:ex2:words:4:pos":"noun","grammar:91351:ex2:words:5:zh":"(object marker)","grammar:91351:ex2:words:5:pos":"particle","grammar:91351:ex2:words:6:zh":"compared","grammar:91351:ex2:words:6:note":"kurabemashita; masu-form past of 比べる","grammar:91351:ex2:words:6:pos":"verb","grammar:91351:ex2:points:0":"〜を比べる: to compare ~","grammar:91351:ex2:points:1":"値段 = price"},"91352":{"example:91352:exzh":"The shoe department is on the third floor.","example:91352:exzh2":"Where is the grocery section?","grammar:91352:ex:trans":"The shoe department is on the third floor.","grammar:91352:ex:structure":"〔product〕売り場は＋〔floor〕です","grammar:91352:ex:explain":"「売り場」 is made of 「売る」 (to sell) and 「場」 (place) and means the area of a store where a certain kind of goods is sold. Put the product name in front to make 「靴売り場」, 「食料品売り場」, and so on. To ask about a floor, use the pattern 「〜は何階ですか」.","grammar:91352:ex:words:0:zh":"shoes","grammar:91352:ex:words:0:note":"くつ","grammar:91352:ex:words:0:pos":"noun","grammar:91352:ex:words:1:zh":"sales area","grammar:91352:ex:words:1:note":"うりば","grammar:91352:ex:words:1:pos":"noun","grammar:91352:ex:words:2:zh":"(topic)","grammar:91352:ex:words:2:pos":"particle","grammar:91352:ex:words:3:zh":"third floor","grammar:91352:ex:words:3:note":"sangai; 「階」 after 「三」 is read がい","grammar:91352:ex:words:3:pos":"noun","grammar:91352:ex:words:4:zh":"is (polite form)","grammar:91352:ex:words:4:pos":"copula","grammar:91352:ex:points:0":"売り場 = the area of a department store or supermarket selling a certain product; 「靴売り場」, 「おもちゃ売り場」","grammar:91352:ex:points:1":"〜階: floor ~; 三階 is read さんがい","grammar:91352:ex2:trans":"Where is the food department?","grammar:91352:ex2:structure":"〔product〕の売り場は＋どこですか","grammar:91352:ex2:words:0:zh":"food","grammar:91352:ex2:words:0:note":"しょくりょうひん","grammar:91352:ex2:words:0:pos":"noun","grammar:91352:ex2:words:1:zh":"'s","grammar:91352:ex2:words:1:pos":"particle","grammar:91352:ex2:words:2:zh":"sales area","grammar:91352:ex2:words:2:note":"うりば","grammar:91352:ex2:words:2:pos":"noun","grammar:91352:ex2:words:3:zh":"(topic)","grammar:91352:ex2:words:3:pos":"particle","grammar:91352:ex2:words:4:zh":"where","grammar:91352:ex2:words:4:pos":"question word","grammar:91352:ex2:words:5:zh":"is (polite form)","grammar:91352:ex2:words:5:pos":"copula","grammar:91352:ex2:words:6:zh":"(question)","grammar:91352:ex2:words:6:pos":"particle","grammar:91352:ex2:points:0":"売り場はどこですか: an essential phrase for finding things in a department store","grammar:91352:ex2:points:1":"You can say 「食料品売り場」, or add 「の」"},"91353":{"example:91353:exzh":"I spend New Year with my family.","example:91353:exzh2":"I went to a shrine at New Year's.","grammar:91353:ex:trans":"I spend New Year's with my family.","grammar:91353:ex:structure":"〔time〕は＋〔person〕と過ごします","grammar:91353:ex:explain":"「正月」 refers to the New Year period at the start of the year; Japan celebrates the solar New Year, not the lunar one. Adding 「お」 to make 「お正月」 is more common and more polite. 「〔person〕と過ごす」 = to spend time with ~.","grammar:91353:ex:words:0:zh":"New Year; the New Year holidays","grammar:91353:ex:words:0:note":"しょうがつ","grammar:91353:ex:words:0:pos":"noun","grammar:91353:ex:words:1:zh":"(topic)","grammar:91353:ex:words:1:pos":"particle","grammar:91353:ex:words:2:zh":"family","grammar:91353:ex:words:2:note":"かぞく","grammar:91353:ex:words:2:pos":"noun","grammar:91353:ex:words:3:zh":"with","grammar:91353:ex:words:3:pos":"particle","grammar:91353:ex:words:4:zh":"spend","grammar:91353:ex:words:4:note":"すごします; the masu-form of 過ごす","grammar:91353:ex:words:4:pos":"verb","grammar:91353:ex:points:0":"正月 = the New Year period (Japan celebrates the solar New Year on January 1); people often say 「お正月」","grammar:91353:ex:points:1":"過ごす: to spend (a period of time)","grammar:91353:ex2:trans":"I went to a shrine at New Year's.","grammar:91353:ex2:structure":"お正月に＋〔place〕へ行きました","grammar:91353:ex2:words:0:zh":"(beautifying prefix)","grammar:91353:ex2:words:0:pos":"prefix","grammar:91353:ex2:words:1:zh":"New Year","grammar:91353:ex2:words:1:note":"しょうがつ","grammar:91353:ex2:words:1:pos":"noun","grammar:91353:ex2:words:2:zh":"(point in time)","grammar:91353:ex2:words:2:pos":"particle","grammar:91353:ex2:words:3:zh":"shrine","grammar:91353:ex2:words:3:note":"じんじゃ","grammar:91353:ex2:words:3:pos":"noun","grammar:91353:ex2:words:4:zh":"to","grammar:91353:ex2:words:4:pos":"particle","grammar:91353:ex2:words:5:zh":"went","grammar:91353:ex2:words:5:note":"いきました; past masu-form of 行く","grammar:91353:ex2:words:5:pos":"verb","grammar:91353:ex2:points:1":"Adding 「お」 before a noun makes the tone more polite and softer"},"91354":{"example:91354:exzh":"Please follow the school rules.","example:91354:exzh2":"This dorm has strict rules.","grammar:91354:ex:trans":"Please follow the school rules.","grammar:91354:ex:structure":"規則を＋守る","grammar:91354:ex:explain":"「規則」 means the rules set by a group such as a school, a company, or a dormitory. Its most common combination is 「規則を守る」 (to follow the rules); here 「守る」 doesn't mean to protect but to obey.","grammar:91354:ex:words:0:zh":"school","grammar:91354:ex:words:0:note":"がっこう","grammar:91354:ex:words:0:pos":"noun","grammar:91354:ex:words:1:zh":"'s","grammar:91354:ex:words:1:pos":"particle","grammar:91354:ex:words:2:zh":"rule","grammar:91354:ex:words:2:note":"きそく","grammar:91354:ex:words:2:pos":"noun","grammar:91354:ex:words:3:zh":"(object marker)","grammar:91354:ex:words:3:pos":"particle","grammar:91354:ex:words:4:zh":"obey","grammar:91354:ex:words:4:note":"mamotte; te-form of 守る","grammar:91354:ex:words:4:pos":"verb","grammar:91354:ex:words:5:zh":"please ~","grammar:91354:ex:words:5:note":"ください; the imperative form of くださる","grammar:91354:ex:words:5:pos":"auxiliary verb","grammar:91354:ex:points:0":"規則を守る = to follow the rules; to violate them is 「規則を破る（やぶる）」","grammar:91354:ex:points:1":"〜てください: please do ~","grammar:91354:ex2:trans":"This dorm has strict rules.","grammar:91354:ex2:structure":"〔place〕には＋厳しい規則があります","grammar:91354:ex2:words:0:zh":"this","grammar:91354:ex2:words:0:pos":"pre-noun adjectival","grammar:91354:ex2:words:1:zh":"dormitory","grammar:91354:ex2:words:1:note":"りょう","grammar:91354:ex2:words:1:pos":"noun","grammar:91354:ex2:words:2:zh":"in (the place where something exists)","grammar:91354:ex2:words:2:pos":"particle","grammar:91354:ex2:words:3:zh":"(topic)","grammar:91354:ex2:words:3:pos":"particle","grammar:91354:ex2:words:4:zh":"strict","grammar:91354:ex2:words:4:note":"きびしい","grammar:91354:ex2:words:4:pos":"adjective","grammar:91354:ex2:words:5:zh":"stipulate","grammar:91354:ex2:words:5:note":"きそく","grammar:91354:ex2:words:5:pos":"noun","grammar:91354:ex2:words:6:zh":"(nominative)","grammar:91354:ex2:words:6:pos":"particle","grammar:91354:ex2:words:7:zh":"there is / are","grammar:91354:ex2:words:7:note":"あります; the masu-form (polite form) of ある","grammar:91354:ex2:words:7:pos":"verb","grammar:91354:ex2:points:0":"厳しい規則 = strict rules","grammar:91354:ex2:points:1":"寮 = a dormitory where students or employees live"},"91355":{"example:91355:exzh":"I studied hard for the exam.","example:91355:exzh2":"She always works hard.","grammar:91355:ex:trans":"I studied as hard as I could for the exam.","grammar:91355:ex:structure":"〜のために、＋一生懸命＋〔verb〕","grammar:91355:ex:explain":"「一生懸命」 means with all your might, trying very hard; note the double consonant and long vowel in the reading いっしょうけんめい. It can modify a verb directly, or you can say 「一生懸命に」. This sentence says that the person studied hard for an exam.","grammar:91355:ex:words:0:zh":"test","grammar:91355:ex:words:0:note":"しけん","grammar:91355:ex:words:0:pos":"noun","grammar:91355:ex:words:1:zh":"'s","grammar:91355:ex:words:1:pos":"particle","grammar:91355:ex:words:2:zh":"for the sake of","grammar:91355:ex:words:2:pos":"formal noun","grammar:91355:ex:words:3:zh":"with all one's might","grammar:91355:ex:words:3:note":"いっしょうけんめい","grammar:91355:ex:words:3:pos":"na-adjective","grammar:91355:ex:words:4:zh":"studied","grammar:91355:ex:words:4:note":"benkyō shimashita; masu-form past of 勉強する","grammar:91355:ex:words:4:pos":"verb","grammar:91355:ex:points:0":"一生懸命 = with all your might, as hard as you can; it can go directly before a verb: 一生懸命勉強する","grammar:91355:ex:points:1":"〜のために: for the sake of ~; Japanese 「勉強」 means studying, not reluctantly doing something","grammar:91355:ex2:trans":"She always works very hard.","grammar:91355:ex2:structure":"いつも＋一生懸命＋〜ています","grammar:91355:ex2:words:0:zh":"she","grammar:91355:ex2:words:0:note":"かのじょ","grammar:91355:ex2:words:0:pos":"pronoun","grammar:91355:ex2:words:1:zh":"(topic)","grammar:91355:ex2:words:1:pos":"particle","grammar:91355:ex2:words:2:zh":"always","grammar:91355:ex2:words:2:pos":"adverb","grammar:91355:ex2:words:3:zh":"very hard","grammar:91355:ex2:words:3:note":"いっしょうけんめい","grammar:91355:ex2:words:3:pos":"na-adjective","grammar:91355:ex2:words:4:zh":"work","grammar:91355:ex2:words:4:note":"はたらいて; the te-form of 働く","grammar:91355:ex2:words:4:pos":"verb","grammar:91355:ex2:words:5:zh":"(habitually) is ~ing","grammar:91355:ex2:words:5:note":"います; the masu-form of いる","grammar:91355:ex2:words:5:pos":"auxiliary verb","grammar:91355:ex2:points:0":"一生懸命働く: to work hard","grammar:91355:ex2:points:1":"〜ています: shows a habit or a continuing state"},"91356":{"example:91356:exzh":"I gave a present for my mother's birthday.","example:91356:exzh2":"These flowers are a gift from a friend.","grammar:91356:ex:trans":"I gave a present for my mother's birthday.","grammar:91356:ex:structure":"〔time〕に＋贈り物をする","grammar:91356:ex:explain":"「贈り物」 is made of 「贈る」 (to give) and 「物」 (thing), so it's a gift you give someone. Japanese often says 「贈り物をする」 for giving a gift; you don't have to use 「あげる」. In casual speech 「プレゼント」 is more common, while 「贈り物」 sounds more formal and polite.","grammar:91356:ex:words:0:zh":"mom","grammar:91356:ex:words:0:note":"haha; used when mentioning your own mother to outsiders","grammar:91356:ex:words:0:pos":"noun","grammar:91356:ex:words:1:zh":"'s","grammar:91356:ex:words:1:pos":"particle","grammar:91356:ex:words:2:zh":"birthday","grammar:91356:ex:words:2:note":"たんじょうび","grammar:91356:ex:words:2:pos":"noun","grammar:91356:ex:words:3:zh":"(point in time)","grammar:91356:ex:words:3:pos":"particle","grammar:91356:ex:words:4:zh":"present","grammar:91356:ex:words:4:note":"おくりもの","grammar:91356:ex:words:4:pos":"noun","grammar:91356:ex:words:5:zh":"(object marker)","grammar:91356:ex:words:5:pos":"particle","grammar:91356:ex:words:6:zh":"did (here meaning gave)","grammar:91356:ex:words:6:note":"しました; the past masu-form of する","grammar:91356:ex:words:6:pos":"verb","grammar:91356:ex:points:0":"贈り物 = gift; 「贈り物をする」 = to give a gift, a common expression","grammar:91356:ex:points:1":"贈り物 is a little more formal than 「プレゼント」 and is common for holidays, weddings, and similar occasions","grammar:91356:ex2:trans":"These flowers are a gift from a friend.","grammar:91356:ex2:structure":"〔thing〕は＋〔person〕からの贈り物です","grammar:91356:ex2:words:0:zh":"this","grammar:91356:ex2:words:0:pos":"pre-noun adjectival","grammar:91356:ex2:words:1:zh":"flowers","grammar:91356:ex2:words:1:note":"はな","grammar:91356:ex2:words:1:pos":"noun","grammar:91356:ex2:words:2:zh":"(topic)","grammar:91356:ex2:words:2:pos":"particle","grammar:91356:ex2:words:3:zh":"friend","grammar:91356:ex2:words:3:note":"ともだち","grammar:91356:ex2:words:3:pos":"noun","grammar:91356:ex2:words:4:zh":"from","grammar:91356:ex2:words:4:pos":"particle","grammar:91356:ex2:words:5:zh":"'s","grammar:91356:ex2:words:5:pos":"particle","grammar:91356:ex2:words:6:zh":"present","grammar:91356:ex2:words:6:note":"おくりもの","grammar:91356:ex2:words:6:pos":"noun","grammar:91356:ex2:words:7:zh":"is (polite form)","grammar:91356:ex2:words:7:pos":"copula","grammar:91356:ex2:points:0":"〜からの贈り物: a gift from ~","grammar:91356:ex2:points:1":"「から」＋「の」 can come before a noun: 友達からの手紙, 母からのメール"},"91357":{"example:91357:exzh":"A burglar broke into the house at night.","example:91357:exzh2":"A wallet was stolen by a thief.","grammar:91357:ex:trans":"Our house was broken into at night.","grammar:91357:ex:structure":"〔place〕に＋泥棒が入る","grammar:91357:ex:explain":"「泥棒」 is read どろぼう and means a thief. Saying 「家に泥棒が入った」 is the natural way to say the house was broken into. More formal news terms are 「空き巣（あきす）」 and 「窃盗（せっとう）」.","grammar:91357:ex:words:0:zh":"evening","grammar:91357:ex:words:0:note":"よる","grammar:91357:ex:words:0:pos":"noun","grammar:91357:ex:words:1:zh":"house","grammar:91357:ex:words:1:note":"いえ","grammar:91357:ex:words:1:pos":"noun","grammar:91357:ex:words:2:zh":"into (the place entered)","grammar:91357:ex:words:2:pos":"particle","grammar:91357:ex:words:3:zh":"thief","grammar:91357:ex:words:3:note":"どろぼう","grammar:91357:ex:words:3:pos":"noun","grammar:91357:ex:words:4:zh":"(nominative)","grammar:91357:ex:words:4:pos":"particle","grammar:91357:ex:words:5:zh":"entered","grammar:91357:ex:words:5:note":"hairimashita; masu-form past of 入る","grammar:91357:ex:words:5:pos":"verb","grammar:91357:ex:points:0":"泥棒 = thief; 「泥棒が入る」 = to be burgled, a set phrase","grammar:91357:ex:points:1":"〔place〕に入る: to enter ~","grammar:91357:ex2:trans":"My wallet was stolen by a thief.","grammar:91357:ex2:structure":"〔person〕に＋〔thing〕を盗まれる","grammar:91357:ex2:words:0:zh":"thief","grammar:91357:ex2:words:0:note":"どろぼう","grammar:91357:ex2:words:0:pos":"noun","grammar:91357:ex2:words:1:zh":"by (the person who does the action)","grammar:91357:ex2:words:1:pos":"particle","grammar:91357:ex2:words:2:zh":"wallet","grammar:91357:ex2:words:2:note":"さいふ","grammar:91357:ex2:words:2:pos":"noun","grammar:91357:ex2:words:3:zh":"(object marker)","grammar:91357:ex2:words:3:pos":"particle","grammar:91357:ex2:words:4:zh":"was stolen","grammar:91357:ex2:words:4:note":"nusumaremashita; passive past of 盗む","grammar:91357:ex2:words:4:pos":"verb","grammar:91357:ex2:points:0":"泥棒に盗まれる: to have something stolen by a thief","grammar:91357:ex2:points:1":"Passive sentence: the person doing the action takes 「に」; 盗む → 盗まれる"},"91358":{"example:91358:exzh":"The trains stopped because of the typhoon.","example:91358:exzh2":"I hear a typhoon is coming tomorrow.","grammar:91358:ex:trans":"The trains stopped because of the typhoon.","grammar:91358:ex:structure":"〔cause〕で＋〔thing〕が止まる","grammar:91358:ex:explain":"「台風」 means typhoon; like Taiwan, Japan often gets typhoons in summer and autumn. This sentence uses 「で」 for the cause, and 「電車が止まる」 means the trains stop running. 「止まる」 is an intransitive verb: something stops by itself.","grammar:91358:ex:words:0:zh":"typhoon","grammar:91358:ex:words:0:note":"たいふう","grammar:91358:ex:words:0:pos":"noun","grammar:91358:ex:words:1:zh":"because of (cause)","grammar:91358:ex:words:1:pos":"particle","grammar:91358:ex:words:2:zh":"train","grammar:91358:ex:words:2:note":"でんしゃ","grammar:91358:ex:words:2:pos":"noun","grammar:91358:ex:words:3:zh":"(nominative)","grammar:91358:ex:words:3:pos":"particle","grammar:91358:ex:words:4:zh":"stopped","grammar:91358:ex:words:4:note":"tomarimashita; masu-form past of 止まる","grammar:91358:ex:words:4:pos":"verb","grammar:91358:ex:points:0":"台風 = typhoon; Japanese writes only 「台」, not 「颱」","grammar:91358:ex:points:1":"台風で: because of the typhoon; 「で」 marks the cause","grammar:91358:ex2:trans":"I hear a typhoon is coming tomorrow.","grammar:91358:ex2:structure":"〔plain form〕＋そうです (hearsay)","grammar:91358:ex2:words:0:zh":"tomorrow","grammar:91358:ex2:words:0:note":"あした","grammar:91358:ex2:words:0:pos":"noun","grammar:91358:ex2:words:1:zh":"typhoon","grammar:91358:ex2:words:1:note":"たいふう","grammar:91358:ex2:words:1:pos":"noun","grammar:91358:ex2:words:2:zh":"(nominative)","grammar:91358:ex2:words:2:pos":"particle","grammar:91358:ex2:words:3:zh":"come","grammar:91358:ex2:words:3:note":"くる","grammar:91358:ex2:words:3:pos":"verb","grammar:91358:ex2:words:4:zh":"I hear (that)","grammar:91358:ex2:words:4:note":"sō; the hearsay 「そうだ」","grammar:91358:ex2:words:4:pos":"auxiliary verb","grammar:91358:ex2:words:5:zh":"is (polite form)","grammar:91358:ex2:words:5:pos":"copula","grammar:91358:ex2:points:0":"台風が来る: a typhoon is coming","grammar:91358:ex2:points:1":"plain form＋そうです: I hear that ~; the information comes from someone else or the news"},"91359":{"example:91359:exzh":"Please submit your report by Friday.","example:91359:exzh2":"I wrote a report last night.","grammar:91359:ex:trans":"Please hand in your report by Friday.","grammar:91359:ex:structure":"〔deadline〕までに＋レポートを出す","grammar:91359:ex:explain":"「レポート」 comes from the English word report and at university means a written paper you have to hand in. Here 「出す」 means to submit. 「までに」 marks a deadline, unlike 「まで」 (until), and is an important N4 grammar point.","grammar:91359:ex:words:0:zh":"Friday","grammar:91359:ex:words:0:note":"きんようび","grammar:91359:ex:words:0:pos":"noun","grammar:91359:ex:words:1:zh":"(deadline)","grammar:91359:ex:words:1:pos":"particle","grammar:91359:ex:words:2:zh":"(by ~)","grammar:91359:ex:words:2:pos":"particle","grammar:91359:ex:words:3:zh":"report","grammar:91359:ex:words:3:pos":"noun","grammar:91359:ex:words:4:zh":"(object marker)","grammar:91359:ex:words:4:pos":"particle","grammar:91359:ex:words:5:zh":"hand over","grammar:91359:ex:words:5:note":"だして; the te-form of 出す","grammar:91359:ex:words:5:pos":"verb","grammar:91359:ex:words:6:zh":"please ~","grammar:91359:ex:words:6:note":"ください; the imperative form of くださる","grammar:91359:ex:words:6:pos":"auxiliary verb","grammar:91359:ex:points:0":"レポート = a written report for school; 「レポートを出す」 = to hand in a report","grammar:91359:ex:points:1":"までに: by ~ (finish by then); 「まで」 means all the way until ~","grammar:91359:ex2:trans":"I wrote a report last night.","grammar:91359:ex2:structure":"〔time〕、＋レポートを書きました","grammar:91359:ex2:words:0:zh":"yesterday","grammar:91359:ex2:words:0:note":"きのう","grammar:91359:ex2:words:0:pos":"noun","grammar:91359:ex2:words:1:zh":"'s","grammar:91359:ex2:words:1:pos":"particle","grammar:91359:ex2:words:2:zh":"evening","grammar:91359:ex2:words:2:note":"よる","grammar:91359:ex2:words:2:pos":"noun","grammar:91359:ex2:words:3:zh":"report","grammar:91359:ex2:words:3:pos":"noun","grammar:91359:ex2:words:4:zh":"(object marker)","grammar:91359:ex2:words:4:pos":"particle","grammar:91359:ex2:words:5:zh":"wrote","grammar:91359:ex2:words:5:note":"かきました; the past masu-form of 書く","grammar:91359:ex2:words:5:pos":"verb","grammar:91359:ex2:points:0":"レポートを書く: to write a report","grammar:91359:ex2:points:1":"昨日の夜 = last night (「昨夜」 also works)"},"91360":{"example:91360:exzh":"I pressed the button. Then the door opened.","example:91360:exzh2":"I opened the window. Then a cool breeze came in.","grammar:91360:ex:trans":"I pressed the button, and the door opened.","grammar:91360:ex:structure":"〔action〕。すると、＋〔result〕","grammar:91360:ex:explain":"「すると」 connects two sentences: the first is an action, the second is what happened as a result, giving the sense that as soon as ~ happened, ~ followed. It's common in stories and in describing experiences. The second sentence is usually in the past tense, and it can't be 「〜ましょう」 or 「〜てください」.","grammar:91360:ex:words:0:zh":"button","grammar:91360:ex:words:0:pos":"noun","grammar:91360:ex:words:1:zh":"(object marker)","grammar:91360:ex:words:1:pos":"particle","grammar:91360:ex:words:2:zh":"pressed","grammar:91360:ex:words:2:note":"oshimashita; masu-form past of 押す","grammar:91360:ex:words:2:pos":"verb","grammar:91360:ex:words:3:zh":"as a result, and then","grammar:91360:ex:words:3:pos":"conjunction","grammar:91360:ex:words:4:zh":"door","grammar:91360:ex:words:4:pos":"noun","grammar:91360:ex:words:5:zh":"(nominative)","grammar:91360:ex:words:5:pos":"particle","grammar:91360:ex:words:6:zh":"bloomed","grammar:91360:ex:words:6:note":"akimashita; masu-form past of 開く（あく）","grammar:91360:ex:words:6:pos":"verb","grammar:91360:ex:points:0":"すると = after doing the first action, the second thing happened; it goes at the start of the sentence","grammar:91360:ex:points:1":"What follows is a result you actually saw; you can't put your own intention or a command after it","grammar:91360:ex2:trans":"I opened the window, and a cool breeze came in.","grammar:91360:ex2:structure":"〔action〕。すると、＋〔result〕","grammar:91360:ex2:words:0:zh":"window","grammar:91360:ex2:words:0:note":"まど","grammar:91360:ex2:words:0:pos":"noun","grammar:91360:ex2:words:1:zh":"(object marker)","grammar:91360:ex2:words:1:pos":"particle","grammar:91360:ex2:words:2:zh":"opened","grammar:91360:ex2:words:2:note":"akemashita; masu-form past of 開ける","grammar:91360:ex2:words:2:pos":"verb","grammar:91360:ex2:words:3:zh":"so; thereupon","grammar:91360:ex2:words:3:pos":"conjunction","grammar:91360:ex2:words:4:zh":"cool","grammar:91360:ex2:words:4:note":"すずしい","grammar:91360:ex2:words:4:pos":"adjective","grammar:91360:ex2:words:5:zh":"wind","grammar:91360:ex2:words:5:note":"かぜ","grammar:91360:ex2:words:5:pos":"noun","grammar:91360:ex2:words:6:zh":"(nominative)","grammar:91360:ex2:words:6:pos":"particle","grammar:91360:ex2:words:7:zh":"enter","grammar:91360:ex2:words:7:note":"はいって; te-form of 入る","grammar:91360:ex2:words:7:pos":"verb","grammar:91360:ex2:words:8:zh":"come (toward here)","grammar:91360:ex2:words:8:note":"kimashita; masu-form past of くる","grammar:91360:ex2:words:8:pos":"auxiliary verb","grammar:91360:ex2:points:0":"すると: the window opens, then the cool breeze comes in; the two are in a natural cause-and-effect order","grammar:91360:ex2:points:1":"〜てくる: to come toward the speaker"},"91361":{"example:91361:exzh":"My father is very strict.","example:91361:exzh2":"The cold is harsh this winter.","grammar:91361:ex:trans":"My father is very strict.","grammar:91361:ex:structure":"〔person〕は＋厳しいです","grammar:91361:ex:explain":"「厳しい」 can describe a person as strict, and also describe harsh weather or a tough situation (see the second sentence). 「うちの父」 means my dad, a natural way to refer to your own family member when talking to others.","grammar:91361:ex:words:0:zh":"our home","grammar:91361:ex:words:0:pos":"noun","grammar:91361:ex:words:1:zh":"'s","grammar:91361:ex:words:1:pos":"particle","grammar:91361:ex:words:2:zh":"dad","grammar:91361:ex:words:2:note":"ちち","grammar:91361:ex:words:2:pos":"noun","grammar:91361:ex:words:3:zh":"(topic)","grammar:91361:ex:words:3:pos":"particle","grammar:91361:ex:words:4:zh":"extremely","grammar:91361:ex:words:4:pos":"adverb","grammar:91361:ex:words:5:zh":"strict","grammar:91361:ex:words:5:note":"きびしい","grammar:91361:ex:words:5:pos":"adjective","grammar:91361:ex:words:6:zh":"is (polite form)","grammar:91361:ex:words:6:pos":"copula","grammar:91361:ex:points:0":"厳しい = demanding and strict with people: 厳しい先生, 厳しい親","grammar:91361:ex:points:1":"うちの〜: my family's ~; common in casual speech","grammar:91361:ex2:trans":"The cold is severe this winter.","grammar:91361:ex2:structure":"〔season〕は＋寒さが厳しいです","grammar:91361:ex2:words:0:zh":"this year","grammar:91361:ex2:words:0:note":"ことし","grammar:91361:ex2:words:0:pos":"noun","grammar:91361:ex2:words:1:zh":"'s","grammar:91361:ex2:words:1:pos":"particle","grammar:91361:ex2:words:2:zh":"winter","grammar:91361:ex2:words:2:note":"ふゆ","grammar:91361:ex2:words:2:pos":"noun","grammar:91361:ex2:words:3:zh":"(topic)","grammar:91361:ex2:words:3:pos":"particle","grammar:91361:ex2:words:4:zh":"the cold (its severity)","grammar:91361:ex2:words:4:note":"samusa; the noun form of 寒い","grammar:91361:ex2:words:4:pos":"noun","grammar:91361:ex2:words:5:zh":"(nominative)","grammar:91361:ex2:words:5:pos":"particle","grammar:91361:ex2:words:6:zh":"severe, harsh","grammar:91361:ex2:words:6:note":"きびしい","grammar:91361:ex2:words:6:pos":"adjective","grammar:91361:ex2:words:7:zh":"is (polite form)","grammar:91361:ex2:words:7:pos":"copula","grammar:91361:ex2:points:0":"寒さが厳しい: the cold is severe; 「厳しい」 is also used for harsh weather, hard living conditions, and so on","grammar:91361:ex2:points:1":"Drop い from an i-adjective and add 「さ」 to make a noun: 寒い → 寒さ, 暑い → 暑さ"},"91362":{"example:91362:exzh":"I take the escalator to the second floor.","example:91362:exzh2":"The escalator at the station has stopped.","grammar:91362:ex:trans":"I'll take the escalator to the second floor.","grammar:91362:ex:structure":"エスカレーターで＋〔floor〕へ行きます","grammar:91362:ex:explain":"「エスカレーター」 comes from the English word escalator and is the moving staircase; 「エレベーター」 is the elevator. This sentence uses 「で」 for the means of movement and 「へ」 for the direction.","grammar:91362:ex:words:0:zh":"escalator","grammar:91362:ex:words:0:pos":"noun","grammar:91362:ex:words:1:zh":"by (means)","grammar:91362:ex:words:1:pos":"particle","grammar:91362:ex:words:2:zh":"second floor","grammar:91362:ex:words:2:note":"にかい","grammar:91362:ex:words:2:pos":"noun","grammar:91362:ex:words:3:zh":"to","grammar:91362:ex:words:3:pos":"particle","grammar:91362:ex:words:4:zh":"go","grammar:91362:ex:words:4:note":"いきます; masu-form of 行く","grammar:91362:ex:words:4:pos":"verb","grammar:91362:ex:points:0":"エスカレーター = escalator; an elevator is 「エレベーター」; the two sound similar, so keep them apart","grammar:91362:ex:points:1":"Means of transport takes 「で」: エスカレーターで行く","grammar:91362:ex2:trans":"The escalator at the station has stopped.","grammar:91362:ex2:structure":"〔thing〕が＋止まっています","grammar:91362:ex2:words:0:zh":"station","grammar:91362:ex2:words:0:note":"えき","grammar:91362:ex2:words:0:pos":"noun","grammar:91362:ex2:words:1:zh":"'s","grammar:91362:ex2:words:1:pos":"particle","grammar:91362:ex2:words:2:zh":"escalator","grammar:91362:ex2:words:2:pos":"noun","grammar:91362:ex2:words:3:zh":"(nominative)","grammar:91362:ex2:words:3:pos":"particle","grammar:91362:ex2:words:4:zh":"stop","grammar:91362:ex2:words:4:note":"とまって; the te-form of 止まる","grammar:91362:ex2:words:4:pos":"verb","grammar:91362:ex2:words:5:zh":"(in the state of ~)","grammar:91362:ex2:words:5:note":"います; the masu-form of いる","grammar:91362:ex2:words:5:pos":"auxiliary verb","grammar:91362:ex2:points:0":"エスカレーターが止まっている: the escalator is stopped and not moving","grammar:91362:ex2:points:1":"〜ている: expresses the current state"},"91363":{"example:91363:exzh":"The house shook in the earthquake.","example:91363:exzh2":"The boat rocked a lot, and I felt sick.","grammar:91363:ex:trans":"The house shook during the earthquake.","grammar:91363:ex:structure":"〔cause〕で＋〔thing〕が揺れる","grammar:91363:ex:explain":"「揺れる」 means something shakes on its own, and it can be used for earthquakes, boats and tree branches. Japan has many earthquakes, so you often hear people say 「揺れましたね」, meaning it just shook, didn't it? The transitive verb that means to make something shake is 「揺らす（ゆらす）」.","grammar:91363:ex:words:0:zh":"earthquake","grammar:91363:ex:words:0:note":"じしん","grammar:91363:ex:words:0:pos":"noun","grammar:91363:ex:words:1:zh":"because of (cause)","grammar:91363:ex:words:1:pos":"particle","grammar:91363:ex:words:2:zh":"house","grammar:91363:ex:words:2:note":"いえ","grammar:91363:ex:words:2:pos":"noun","grammar:91363:ex:words:3:zh":"(nominative)","grammar:91363:ex:words:3:pos":"particle","grammar:91363:ex:words:4:zh":"rocked","grammar:91363:ex:words:4:note":"ゆれました; the past masu-form of 揺れる","grammar:91363:ex:words:4:pos":"verb","grammar:91363:ex:points:0":"揺れる = something shakes by itself; it is an intransitive verb, so it takes 「が」","grammar:91363:ex:points:1":"地震で: because of the earthquake; 「で」 marks the cause","grammar:91363:ex2:trans":"The boat rocked hard and I started to feel sick.","grammar:91363:ex2:structure":"〜が大きく揺れて、＋気分が悪くなりました","grammar:91363:ex2:words:0:zh":"boat","grammar:91363:ex2:words:0:note":"ふね","grammar:91363:ex2:words:0:pos":"noun","grammar:91363:ex2:words:1:zh":"(nominative)","grammar:91363:ex2:words:1:pos":"particle","grammar:91363:ex2:words:2:zh":"in a big motion","grammar:91363:ex2:words:2:note":"おおきく; the adverb form of 大きい","grammar:91363:ex2:words:2:pos":"adjective","grammar:91363:ex2:words:3:zh":"to sway","grammar:91363:ex2:words:3:note":"ゆれて; the te-form of 揺れる","grammar:91363:ex2:words:3:pos":"verb","grammar:91363:ex2:words:4:zh":"physical condition; mood","grammar:91363:ex2:words:4:note":"きぶん","grammar:91363:ex2:words:4:pos":"noun","grammar:91363:ex2:words:5:zh":"(nominative)","grammar:91363:ex2:words:5:pos":"particle","grammar:91363:ex2:words:6:zh":"bad / not good","grammar:91363:ex2:words:6:note":"わるく; the adverbial form of 悪い","grammar:91363:ex2:words:6:pos":"adjective","grammar:91363:ex2:words:7:zh":"become","grammar:91363:ex2:words:7:note":"なりました; past masu-form of なる","grammar:91363:ex2:words:7:pos":"verb","grammar:91363:ex2:points:0":"大きく揺れる: to shake a lot","grammar:91363:ex2:points:1":"The te-form can express a cause: 「揺れて」 = because it shook; 気分が悪い = to feel sick, to feel like throwing up"},"91364":{"example:91364:exzh":"Please come as early as you can.","example:91364:exzh2":"I try to walk as much as possible every day.","grammar:91364:ex:trans":"Please come as early as you can.","grammar:91364:ex:structure":"できるだけ＋〔adverb / verb〕","grammar:91364:ex:explain":"「できるだけ」 is made up of 「できる」 (can do) and 「だけ」 (limit), and means doing as much as you can. You can also say 「なるべく」. This sentence politely asks someone to arrive as early as possible.","grammar:91364:ex:words:0:zh":"as much as possible","grammar:91364:ex:words:0:pos":"adverb","grammar:91364:ex:words:1:zh":"early (as an adverb)","grammar:91364:ex:words:1:note":"はやく; the adverb form of 早い","grammar:91364:ex:words:1:pos":"adjective","grammar:91364:ex:words:2:zh":"come","grammar:91364:ex:words:2:note":"きて; the te-form of 来る","grammar:91364:ex:words:2:pos":"verb","grammar:91364:ex:words:3:zh":"please ~","grammar:91364:ex:words:3:note":"ください; the imperative form of くださる","grammar:91364:ex:words:3:pos":"auxiliary verb","grammar:91364:ex:points:0":"できるだけ = as much as you can within your ability; 「できるだけ早く」 is a very common combination","grammar:91364:ex:points:1":"Changing an i-adjective into an adverb: 早い→早く","grammar:91364:ex2:trans":"I try to walk as much as I can every day.","grammar:91364:ex2:structure":"できるだけ＋〔verb dictionary form〕ようにしています","grammar:91364:ex2:words:0:zh":"every day","grammar:91364:ex2:words:0:note":"まいにち","grammar:91364:ex2:words:0:pos":"noun","grammar:91364:ex2:words:1:zh":"as much as possible","grammar:91364:ex2:words:1:pos":"adverb","grammar:91364:ex2:words:2:zh":"walking","grammar:91364:ex2:words:2:note":"あるく","grammar:91364:ex2:words:2:pos":"verb","grammar:91364:ex2:words:3:zh":"(the appearance of trying to do so)","grammar:91364:ex2:words:3:pos":"formal noun","grammar:91364:ex2:words:4:zh":"(combines with よう to form 「ように」)","grammar:91364:ex2:words:4:pos":"particle","grammar:91364:ex2:words:5:zh":"do","grammar:91364:ex2:words:5:note":"して; the te-form of する","grammar:91364:ex2:words:5:pos":"verb","grammar:91364:ex2:words:6:zh":"(continuing) to do ~","grammar:91364:ex2:words:6:note":"います; the masu-form of いる","grammar:91364:ex2:words:6:pos":"auxiliary verb","grammar:91364:ex2:points:0":"できるだけ〜ようにする: to make an effort to do ~ as much as possible","grammar:91364:ex2:points:1":"〜ようにしている: a habit you keep in mind and try to maintain in daily life"},"91365":{"example:91365:exzh":"My younger sister is in junior high school.","example:91365:exzh2":"This junior high school has five hundred students.","grammar:91365:ex:trans":"My younger sister is in junior high school.","grammar:91365:ex:structure":"〔person〕は＋〔school〕に通っています","grammar:91365:ex:explain":"「中学校」 is the equivalent of junior high school in Taiwan, and its reading 「ちゅうがっこう」 has a small っ. In Japanese, attending a school is usually expressed with 「〜に通っています」, which means going to and from school every day. 「中学生」 means a junior high school student.","grammar:91365:ex:words:0:zh":"younger sister","grammar:91365:ex:words:0:note":"いもうと","grammar:91365:ex:words:0:pos":"noun","grammar:91365:ex:words:1:zh":"(topic)","grammar:91365:ex:words:1:pos":"particle","grammar:91365:ex:words:2:zh":"junior high school","grammar:91365:ex:words:2:note":"ちゅうがっこう","grammar:91365:ex:words:2:pos":"noun","grammar:91365:ex:words:3:zh":"to (the place you go to)","grammar:91365:ex:words:3:pos":"particle","grammar:91365:ex:words:4:zh":"to commute; to attend (school) regularly","grammar:91365:ex:words:4:note":"かよって; the te-form of 通う","grammar:91365:ex:words:4:pos":"verb","grammar:91365:ex:words:5:zh":"(continuing) to do ~","grammar:91365:ex:words:5:note":"います; the masu-form of いる","grammar:91365:ex:words:5:pos":"auxiliary verb","grammar:91365:ex:points:0":"中学校 = junior high school (three years in Japan too); the abbreviation is 「中学（ちゅうがく）」","grammar:91365:ex:points:1":"〔school〕に通う: to attend a certain school","grammar:91365:ex2:trans":"This junior high school has five hundred students.","grammar:91365:ex2:structure":"〔place〕には＋〔person〕が＋〔number〕います","grammar:91365:ex2:words:0:zh":"this","grammar:91365:ex2:words:0:pos":"pre-noun adjectival","grammar:91365:ex2:words:1:zh":"junior high school","grammar:91365:ex2:words:1:note":"ちゅうがっこう","grammar:91365:ex2:words:1:pos":"noun","grammar:91365:ex2:words:2:zh":"in (the place where something exists)","grammar:91365:ex2:words:2:pos":"particle","grammar:91365:ex2:words:3:zh":"(topic)","grammar:91365:ex2:words:3:pos":"particle","grammar:91365:ex2:words:4:zh":"(junior and senior high school) student","grammar:91365:ex2:words:4:note":"せいと","grammar:91365:ex2:words:4:pos":"noun","grammar:91365:ex2:words:5:zh":"(nominative)","grammar:91365:ex2:words:5:pos":"particle","grammar:91365:ex2:words:6:zh":"five hundred","grammar:91365:ex2:words:6:note":"ごひゃく","grammar:91365:ex2:words:6:pos":"numeral","grammar:91365:ex2:words:7:zh":"～人 (counter for people)","grammar:91365:ex2:words:7:note":"にん","grammar:91365:ex2:words:7:pos":"suffix","grammar:91365:ex2:words:8:zh":"there is / are","grammar:91365:ex2:words:8:note":"います; the masu-form of いる","grammar:91365:ex2:words:8:pos":"verb","grammar:91365:ex2:points:0":"中学校の生徒: junior high school students; junior and senior high school students are called 「生徒」, while university students are called 「学生」","grammar:91365:ex2:points:1":"The number comes before the verb: 五百人います"},"91366":{"example:91366:exzh":"I will contact you right away.","example:91366:exzh2":"Thank you for your help in advance.","grammar:91366:ex:trans":"I will contact you right away.","grammar:91366:ex:structure":"ご＋〔noun〕＋致します","grammar:91366:ex:explain":"「致す」 is the kenjōgo (humble) form of 「する」 (to do); it is used for your own actions to show politeness when speaking to clients or superiors. 「ご連絡致します」 is much more polite than 「連絡します」 and is common in workplace emails and phone calls. Today it is often written in hiragana as 「いたします」.","grammar:91366:ex:words:0:zh":"soon","grammar:91366:ex:words:0:pos":"adverb","grammar:91366:ex:words:1:zh":"(follows an adverb)","grammar:91366:ex:words:1:pos":"particle","grammar:91366:ex:words:2:zh":"(humble prefix)","grammar:91366:ex:words:2:pos":"prefix","grammar:91366:ex:words:3:zh":"contact","grammar:91366:ex:words:3:note":"れんらく","grammar:91366:ex:words:3:pos":"noun","grammar:91366:ex:words:4:zh":"to do (humble)","grammar:91366:ex:words:4:note":"いたします; the masu-form of 致す","grammar:91366:ex:words:4:pos":"verb","grammar:91366:ex:points:0":"致す = the kenjōgo (humble) form of 「する」; 「ご連絡致します」 = I will contact you","grammar:91366:ex:points:1":"「ご〜致します」 / 「お〜致します」: to lower yourself and show respect to the other person","grammar:91366:ex2:trans":"I look forward to working with you.","grammar:91366:ex2:structure":"よろしく＋お願い致します","grammar:91366:ex2:words:0:zh":"well","grammar:91366:ex2:words:0:pos":"adverb","grammar:91366:ex2:words:1:zh":"(beautifying prefix)","grammar:91366:ex2:words:1:pos":"prefix","grammar:91366:ex2:words:2:zh":"request","grammar:91366:ex2:words:2:note":"ねがい","grammar:91366:ex2:words:2:pos":"noun","grammar:91366:ex2:words:3:zh":"to do (humble)","grammar:91366:ex2:words:3:note":"いたします; the masu-form of 致す","grammar:91366:ex2:words:3:pos":"verb","grammar:91366:ex2:points:0":"よろしくお願い致します: more polite than 「よろしくお願いします」","grammar:91366:ex2:points:1":"Can be used both after introducing yourself and after asking someone for a favor"},"91367":{"example:91367:exzh":"I read novels before bed.","example:91367:exzh2":"This novel was made into a movie.","grammar:91367:ex:trans":"I read novels before going to bed.","grammar:91367:ex:structure":"〔verb dictionary form〕前に、＋〜","grammar:91367:ex:explain":"「小説」 means novel, just as in Chinese, and its reading is 「しょうせつ」. In Japanese, reading books or novels takes 「読む」, not 「見る」. The verb before 「寝る前に」 must be in dictionary form.","grammar:91367:ex:words:0:zh":"sleep","grammar:91367:ex:words:0:note":"ねる","grammar:91367:ex:words:0:pos":"verb","grammar:91367:ex:words:1:zh":"before","grammar:91367:ex:words:1:note":"まえ","grammar:91367:ex:words:1:pos":"noun","grammar:91367:ex:words:2:zh":"(point in time)","grammar:91367:ex:words:2:pos":"particle","grammar:91367:ex:words:3:zh":"novel","grammar:91367:ex:words:3:note":"しょうせつ","grammar:91367:ex:words:3:pos":"noun","grammar:91367:ex:words:4:zh":"(object marker)","grammar:91367:ex:words:4:pos":"particle","grammar:91367:ex:words:5:zh":"read","grammar:91367:ex:words:5:note":"よみます; masu-form of 読む","grammar:91367:ex:words:5:pos":"verb","grammar:91367:ex:points:0":"小説を読む: to read a novel; in Japanese, reading a book uses 「読む」 (to read)","grammar:91367:ex:points:1":"verb dictionary form＋前に: before doing ~","grammar:91367:ex2:trans":"This novel was made into a movie.","grammar:91367:ex2:structure":"〔noun〕は＋〔noun〕になりました","grammar:91367:ex2:words:0:zh":"this","grammar:91367:ex2:words:0:pos":"pre-noun adjectival","grammar:91367:ex2:words:1:zh":"novel","grammar:91367:ex2:words:1:note":"しょうせつ","grammar:91367:ex2:words:1:pos":"noun","grammar:91367:ex2:words:2:zh":"(topic)","grammar:91367:ex2:words:2:pos":"particle","grammar:91367:ex2:words:3:zh":"movie","grammar:91367:ex2:words:3:note":"えいが","grammar:91367:ex2:words:3:pos":"noun","grammar:91367:ex2:words:4:zh":"(the resulting color)","grammar:91367:ex2:words:4:pos":"particle","grammar:91367:ex2:words:5:zh":"became","grammar:91367:ex2:words:5:note":"なりました; past masu-form of なる","grammar:91367:ex2:words:5:pos":"verb","grammar:91367:ex2:points:0":"小説が映画になる: a novel is adapted into a movie","grammar:91367:ex2:points:1":"〜になる: to become ~"},"91368":{"example:91368:exzh":"This restaurant is cheap. Besides, the food is good.","example:91368:exzh2":"It's raining today. Besides, the wind is strong too.","grammar:91368:ex:trans":"This restaurant is cheap, and delicious too.","grammar:91368:ex:structure":"〔good point〕。それに、＋〔another good point〕","grammar:91368:ex:explain":"「それに」 is used to add a reason or a piece of information and is common in speech; it means something like 'and besides'. Here you say 「安い」 first, then add 「おいしい」 with 「それに」; both are positive evaluations. In writing, 「さらに」 and 「しかも」 are more common.","grammar:91368:ex:words:0:zh":"this","grammar:91368:ex:words:0:pos":"pre-noun adjectival","grammar:91368:ex:words:1:zh":"restaurant","grammar:91368:ex:words:1:pos":"noun","grammar:91368:ex:words:2:zh":"(topic)","grammar:91368:ex:words:2:pos":"particle","grammar:91368:ex:words:3:zh":"cheap","grammar:91368:ex:words:3:note":"やすい","grammar:91368:ex:words:3:pos":"adjective","grammar:91368:ex:words:4:zh":"is (polite form)","grammar:91368:ex:words:4:pos":"copula","grammar:91368:ex:words:5:zh":"and moreover","grammar:91368:ex:words:5:pos":"conjunction","grammar:91368:ex:words:6:zh":"tasty","grammar:91368:ex:words:6:pos":"adjective","grammar:91368:ex:words:7:zh":"is (polite form)","grammar:91368:ex:words:7:pos":"copula","grammar:91368:ex:points:0":"それに = and, moreover; adds one more thing of the same kind","grammar:91368:ex:points:1":"The two parts usually point in the same direction (both good points or both bad points)","grammar:91368:ex2:trans":"It is raining today, and the wind is strong too.","grammar:91368:ex2:structure":"〔thing〕。それに、＋〔another thing〕も〜","grammar:91368:ex2:words:0:zh":"today","grammar:91368:ex2:words:0:note":"きょう","grammar:91368:ex2:words:0:pos":"noun","grammar:91368:ex2:words:1:zh":"(topic)","grammar:91368:ex2:words:1:pos":"particle","grammar:91368:ex2:words:2:zh":"rain","grammar:91368:ex2:words:2:note":"あめ","grammar:91368:ex2:words:2:pos":"noun","grammar:91368:ex2:words:3:zh":"is (polite form)","grammar:91368:ex2:words:3:pos":"copula","grammar:91368:ex2:words:4:zh":"and moreover","grammar:91368:ex2:words:4:pos":"conjunction","grammar:91368:ex2:words:5:zh":"wind","grammar:91368:ex2:words:5:note":"かぜ","grammar:91368:ex2:words:5:pos":"noun","grammar:91368:ex2:words:6:zh":"also, too","grammar:91368:ex2:words:6:pos":"particle","grammar:91368:ex2:words:7:zh":"strong","grammar:91368:ex2:words:7:note":"つよい","grammar:91368:ex2:words:7:pos":"adjective","grammar:91368:ex2:words:8:zh":"is (polite form)","grammar:91368:ex2:words:8:pos":"copula","grammar:91368:ex2:points:0":"それに: it can also be used when both things are negative","grammar:91368:ex2:points:1":"風が強い = the wind is strong; Japanese uses 「強い」, not 「大きい」"},"91369":{"example:91369:exzh":"I like Western food.","example:91369:exzh2":"This town has a lot of Western-style buildings.","grammar:91369:ex:trans":"I like Western food.","grammar:91369:ex:structure":"西洋の＋〔noun〕","grammar:91369:ex:words:0:zh":"the West; Europe and the United States","grammar:91369:ex:words:0:note":"せいよう","grammar:91369:ex:words:0:pos":"noun","grammar:91369:ex:words:1:zh":"'s","grammar:91369:ex:words:1:pos":"particle","grammar:91369:ex:words:2:zh":"cooking, dish","grammar:91369:ex:words:2:note":"りょうり","grammar:91369:ex:words:2:pos":"noun","grammar:91369:ex:words:3:zh":"(nominative)","grammar:91369:ex:words:3:pos":"particle","grammar:91369:ex:words:4:zh":"to like","grammar:91369:ex:words:4:note":"すき","grammar:91369:ex:words:4:pos":"na-adjective","grammar:91369:ex:words:5:zh":"is (polite form)","grammar:91369:ex:words:5:pos":"copula","grammar:91369:ex:points:1":"〜が好きです: to like ~; the thing you like takes 「が」","grammar:91369:ex2:trans":"This town has many Western-style buildings.","grammar:91369:ex2:structure":"〔place〕には＋〔thing〕が多いです","grammar:91369:ex2:words:0:zh":"this","grammar:91369:ex2:words:0:pos":"pre-noun adjectival","grammar:91369:ex2:words:1:zh":"town","grammar:91369:ex2:words:1:note":"まち","grammar:91369:ex2:words:1:pos":"noun","grammar:91369:ex2:words:2:zh":"in (the place where something exists)","grammar:91369:ex2:words:2:pos":"particle","grammar:91369:ex2:words:3:zh":"(topic)","grammar:91369:ex2:words:3:pos":"particle","grammar:91369:ex2:words:4:zh":"the West","grammar:91369:ex2:words:4:note":"せいよう","grammar:91369:ex2:words:4:pos":"noun","grammar:91369:ex2:words:5:zh":"'s","grammar:91369:ex2:words:5:pos":"particle","grammar:91369:ex2:words:6:zh":"building","grammar:91369:ex2:words:6:note":"たてもの","grammar:91369:ex2:words:6:pos":"noun","grammar:91369:ex2:words:7:zh":"(nominative)","grammar:91369:ex2:words:7:pos":"particle","grammar:91369:ex2:words:8:zh":"many","grammar:91369:ex2:words:8:note":"おおい","grammar:91369:ex2:words:8:pos":"adjective","grammar:91369:ex2:words:9:zh":"is (polite form)","grammar:91369:ex2:words:9:pos":"copula","grammar:91369:ex2:points:0":"西洋の建物 = Western-style buildings","grammar:91369:ex2:points:1":"〜が多い: there are many ~; 「多い」 cannot go directly before a noun (you do not say 「多い建物」)"},"91370":{"example:91370:exzh":"Please do not touch the exhibits.","example:91370:exzh2":"I gently touched the cat's head.","grammar:91370:ex:trans":"Please do not touch the artworks.","grammar:91370:ex:structure":"〔thing〕に＋触らないでください","grammar:91370:ex:explain":"「触る」 means to touch something with your hand, and the thing you touch takes 「に」: 「作品に触る」. 「〜ないでください」 is a polite way to say 'please don't', and you often see it in museums and exhibitions.","grammar:91370:ex:words:0:zh":"artwork; exhibit","grammar:91370:ex:words:0:note":"さくひん","grammar:91370:ex:words:0:pos":"noun","grammar:91370:ex:words:1:zh":"(the thing being touched)","grammar:91370:ex:words:1:pos":"particle","grammar:91370:ex:words:2:zh":"don't touch","grammar:91370:ex:words:2:note":"さわらないで; the nai-form of 触る＋で","grammar:91370:ex:words:2:pos":"verb","grammar:91370:ex:words:3:zh":"please ~","grammar:91370:ex:words:3:note":"ください; the imperative form of くださる","grammar:91370:ex:words:3:pos":"auxiliary verb","grammar:91370:ex:points:0":"触る = to touch with your hand; the thing you touch takes 「に」, not 「を」","grammar:91370:ex:points:1":"〜ないでください: please don't ~; a common notice in museums and shops","grammar:91370:ex2:trans":"I gently touched the cat's head.","grammar:91370:ex2:structure":"〔thing〕に＋優しく触る","grammar:91370:ex2:words:0:zh":"cat","grammar:91370:ex2:words:0:note":"ねこ","grammar:91370:ex2:words:0:pos":"noun","grammar:91370:ex2:words:1:zh":"'s","grammar:91370:ex2:words:1:pos":"particle","grammar:91370:ex2:words:2:zh":"head","grammar:91370:ex2:words:2:note":"あたま","grammar:91370:ex2:words:2:pos":"noun","grammar:91370:ex2:words:3:zh":"(the thing being touched)","grammar:91370:ex2:words:3:pos":"particle","grammar:91370:ex2:words:4:zh":"gently","grammar:91370:ex2:words:4:note":"やさしく; the adverbial form of 優しい","grammar:91370:ex2:words:4:pos":"adjective","grammar:91370:ex2:words:5:zh":"touched","grammar:91370:ex2:words:5:note":"さわりました; the past masu-form of 触る","grammar:91370:ex2:words:5:pos":"verb","grammar:91370:ex2:points:0":"〜に触る: to touch ~","grammar:91370:ex2:points:1":"優しい→優しく: the adjective becomes an adverb that modifies a verb"},"91371":{"example:91371:exzh":"On Sunday I took my child to the zoo.","example:91371:exzh2":"This zoo has pandas.","grammar:91371:ex:trans":"On Sunday I went to the zoo with my child.","grammar:91371:ex:structure":"〔person〕と＋動物園へ行きました","grammar:91371:ex:explain":"「動物園」 is written the same as in Chinese, and its reading is 「どうぶつえん」. In this sentence 「と」 marks the person you go with, and 「へ」 marks the direction. The famous Ueno Zoo in Japan has pandas.","grammar:91371:ex:words:0:zh":"Sunday","grammar:91371:ex:words:0:note":"にちようび","grammar:91371:ex:words:0:pos":"noun","grammar:91371:ex:words:1:zh":"(point in time)","grammar:91371:ex:words:1:pos":"particle","grammar:91371:ex:words:2:zh":"child","grammar:91371:ex:words:2:note":"こども","grammar:91371:ex:words:2:pos":"noun","grammar:91371:ex:words:3:zh":"with","grammar:91371:ex:words:3:pos":"particle","grammar:91371:ex:words:4:zh":"zoo","grammar:91371:ex:words:4:note":"どうぶつえん","grammar:91371:ex:words:4:pos":"noun","grammar:91371:ex:words:5:zh":"to","grammar:91371:ex:words:5:pos":"particle","grammar:91371:ex:words:6:zh":"went","grammar:91371:ex:words:6:note":"いきました; past masu-form of 行く","grammar:91371:ex:words:6:pos":"verb","grammar:91371:ex:points:0":"動物園 = zoo; the reading is 「どうぶつえん」","grammar:91371:ex:points:1":"〔person〕と行く: to go together with ~","grammar:91371:ex2:trans":"This zoo has pandas.","grammar:91371:ex2:structure":"〔place〕には＋〔animal〕がいます","grammar:91371:ex2:words:0:zh":"this","grammar:91371:ex2:words:0:pos":"pre-noun adjectival","grammar:91371:ex2:words:1:zh":"zoo","grammar:91371:ex2:words:1:note":"どうぶつえん","grammar:91371:ex2:words:1:pos":"noun","grammar:91371:ex2:words:2:zh":"in (the place where something exists)","grammar:91371:ex2:words:2:pos":"particle","grammar:91371:ex2:words:3:zh":"(topic)","grammar:91371:ex2:words:3:pos":"particle","grammar:91371:ex2:words:4:zh":"panda","grammar:91371:ex2:words:4:pos":"noun","grammar:91371:ex2:words:5:zh":"(nominative)","grammar:91371:ex2:words:5:pos":"particle","grammar:91371:ex2:words:6:zh":"there is / are","grammar:91371:ex2:words:6:note":"います; the masu-form of いる","grammar:91371:ex2:words:6:pos":"verb","grammar:91371:ex2:points:0":"動物園にはパンダがいます","grammar:91371:ex2:points:1":"Animals also take 「います」"},"91372":{"example:91372:exzh":"I'll stop by the supermarket on the way home.","example:91372:exzh2":"If you come this way, please stop by my place.","grammar:91372:ex:trans":"I'll stop by the supermarket on my way home.","grammar:91372:ex:structure":"〔time〕に＋〔place〕に寄る","grammar:91372:ex:explain":"The key point of 「寄る」 is stopping by, breaking your trip midway: that place is not your destination, you just turn off to it on the way. 「帰りにスーパーに寄る」 means stopping at the supermarket on the way home from work. This sentence has two 「に」: the first marks time, the second marks the place you go to.","grammar:91372:ex:words:0:zh":"on the way home","grammar:91372:ex:words:0:note":"かえり; the noun form of 帰る","grammar:91372:ex:words:0:pos":"noun","grammar:91372:ex:words:1:zh":"(point in time)","grammar:91372:ex:words:1:pos":"particle","grammar:91372:ex:words:2:zh":"supermarket","grammar:91372:ex:words:2:pos":"noun","grammar:91372:ex:words:3:zh":"to (the place you go to)","grammar:91372:ex:words:3:pos":"particle","grammar:91372:ex:words:4:zh":"to stop by on the way","grammar:91372:ex:words:4:note":"よります; the masu-form of 寄る","grammar:91372:ex:words:4:pos":"verb","grammar:91372:ex:points:0":"寄る = to stop at another place on the way to somewhere; the place you stop at takes 「に」","grammar:91372:ex:points:1":"帰りに: on the way home","grammar:91372:ex2:trans":"If you're ever in the area, please stop by my place.","grammar:91372:ex2:structure":"〜たら、＋うちに寄ってください","grammar:91372:ex2:words:0:zh":"nearby","grammar:91372:ex2:words:0:note":"ちかく","grammar:91372:ex2:words:0:pos":"noun","grammar:91372:ex2:words:1:zh":"to (a place)","grammar:91372:ex2:words:1:pos":"particle","grammar:91372:ex2:words:2:zh":"if (you) come","grammar:91372:ex2:words:2:note":"きたら; the tara-form of 来る","grammar:91372:ex2:words:2:pos":"verb","grammar:91372:ex2:words:3:zh":"our home","grammar:91372:ex2:words:3:pos":"noun","grammar:91372:ex2:words:4:zh":"to (the place you go to)","grammar:91372:ex2:words:4:pos":"particle","grammar:91372:ex2:words:5:zh":"to drop by on the way","grammar:91372:ex2:words:5:note":"よって; the te-form of 寄る","grammar:91372:ex2:words:5:pos":"verb","grammar:91372:ex2:words:6:zh":"please ~","grammar:91372:ex2:words:6:note":"ください; the imperative form of くださる","grammar:91372:ex2:words:6:pos":"auxiliary verb","grammar:91372:ex2:points:0":"うちに寄る: to stop by my place for a bit","grammar:91372:ex2:points:1":"〜たら: if ~"},"91373":{"example:91373:exzh":"Please open your textbook to page ten.","example:91373:exzh2":"I'm having a birthday party next week.","grammar:91373:ex:trans":"Please open your textbook to page ten.","grammar:91373:ex:structure":"〔book〕を＋開く","grammar:91373:ex:explain":"When 「開く」 is read 「ひらく」, it means to open something that is closed, most commonly books and notebooks. It also means 'to hold (an event)' (see the second sentence). When read 「あく」, it means a door or shop is open.","grammar:91373:ex:words:0:zh":"textbook","grammar:91373:ex:words:0:note":"きょうかしょ","grammar:91373:ex:words:0:pos":"noun","grammar:91373:ex:words:1:zh":"'s","grammar:91373:ex:words:1:pos":"particle","grammar:91373:ex:words:2:zh":"ten","grammar:91373:ex:words:2:note":"じゅう","grammar:91373:ex:words:2:pos":"numeral","grammar:91373:ex:words:3:zh":"page","grammar:91373:ex:words:3:pos":"suffix","grammar:91373:ex:words:4:zh":"(object marker)","grammar:91373:ex:words:4:pos":"particle","grammar:91373:ex:words:5:zh":"to open (a book)","grammar:91373:ex:words:5:note":"hiraite; te-form of 開く（ひらく）","grammar:91373:ex:words:5:pos":"verb","grammar:91373:ex:words:6:zh":"please ~","grammar:91373:ex:words:6:note":"ください; the imperative form of くださる","grammar:91373:ex:words:6:pos":"auxiliary verb","grammar:91373:ex:points:0":"開く（ひらく）: to open a book, your hand, an umbrella, etc.; 本を開く = to open a book","grammar:91373:ex:points:1":"開く has two readings: 「あく」 (opens by itself) and 「ひらく」 (to open); this card is 「ひらく」","grammar:91373:ex2:trans":"We're having a birthday party next week.","grammar:91373:ex2:structure":"〔event〕を＋開く","grammar:91373:ex2:words:0:zh":"next week","grammar:91373:ex2:words:0:note":"らいしゅう","grammar:91373:ex2:words:0:pos":"noun","grammar:91373:ex2:words:1:zh":"birthday","grammar:91373:ex2:words:1:note":"たんじょうび","grammar:91373:ex2:words:1:pos":"noun","grammar:91373:ex2:words:2:zh":"party","grammar:91373:ex2:words:2:pos":"noun","grammar:91373:ex2:words:3:zh":"(object marker)","grammar:91373:ex2:words:3:pos":"particle","grammar:91373:ex2:words:4:zh":"hold (an event)","grammar:91373:ex2:words:4:note":"ひらきます; the masu-form of 開く","grammar:91373:ex2:words:4:pos":"verb","grammar:91373:ex2:points:0":"パーティーを開く: to hold a party; 「開く」 can also be used for meetings and exhibitions"},"91374":{"example:91374:exzh":"It's raining. So I'm not going out today.","example:91374:exzh2":"I have an exam tomorrow, so I'm going to bed early.","grammar:91374:ex:trans":"It's raining, so I'm not going out today.","grammar:91374:ex:structure":"〔cause〕。だから、＋〔result〕","grammar:91374:ex:explain":"「だから」 is a conjunction used between two sentences: the first is the cause and the second is the result. It is casual; when speaking to superiors, 「ですから」 is more polite.","grammar:91374:ex:words:0:zh":"rain","grammar:91374:ex:words:0:note":"あめ","grammar:91374:ex:words:0:pos":"noun","grammar:91374:ex:words:1:zh":"(nominative)","grammar:91374:ex:words:1:pos":"particle","grammar:91374:ex:words:2:zh":"to fall (rain)","grammar:91374:ex:words:2:note":"ふって; the te-form of 降る","grammar:91374:ex:words:2:pos":"verb","grammar:91374:ex:words:3:zh":"(in the middle of) ~ing","grammar:91374:ex:words:3:note":"います; the masu-form of いる","grammar:91374:ex:words:3:pos":"auxiliary verb","grammar:91374:ex:words:4:zh":"so / therefore","grammar:91374:ex:words:4:pos":"conjunction","grammar:91374:ex:words:5:zh":"today","grammar:91374:ex:words:5:note":"きょう","grammar:91374:ex:words:5:pos":"noun","grammar:91374:ex:words:6:zh":"(topic)","grammar:91374:ex:words:6:pos":"particle","grammar:91374:ex:words:7:zh":"not going out","grammar:91374:ex:words:7:note":"でかけません; the negative masu-form of 出かける","grammar:91374:ex:words:7:pos":"verb","grammar:91374:ex:points:0":"だから = so; it comes at the start of a sentence, with the cause before it and the result after","grammar:91374:ex:points:1":"For more politeness, you can say 「ですから」","grammar:91374:ex2:trans":"I have an exam tomorrow, so I'll go to bed early.","grammar:91374:ex2:structure":"〔noun〕だから、＋〔result〕","grammar:91374:ex2:words:0:zh":"tomorrow","grammar:91374:ex2:words:0:note":"あした","grammar:91374:ex2:words:0:pos":"noun","grammar:91374:ex2:words:1:zh":"(topic)","grammar:91374:ex2:words:1:pos":"particle","grammar:91374:ex2:words:2:zh":"test","grammar:91374:ex2:words:2:note":"しけん","grammar:91374:ex2:words:2:pos":"noun","grammar:91374:ex2:words:3:zh":"is","grammar:91374:ex2:words:3:pos":"copula","grammar:91374:ex2:words:4:zh":"because","grammar:91374:ex2:words:4:pos":"particle","grammar:91374:ex2:words:5:zh":"early (as an adverb)","grammar:91374:ex2:words:5:note":"はやく; the adverb form of 早い","grammar:91374:ex2:words:5:pos":"adjective","grammar:91374:ex2:words:6:zh":"sleep","grammar:91374:ex2:words:6:note":"ねます; the masu-form of 寝る","grammar:91374:ex2:words:6:pos":"verb","grammar:91374:ex2:points:0":"Here 「だから」 is actually 「だ」 (is) + 「から」 (because), attached after a noun","grammar:91374:ex2:points:1":"It means the same as sentence-initial 「だから」, 'so', just in a different position"},"91375":{"example:91375:exzh":"I wrapped the present in pretty paper.","example:91375:exzh2":"Could you wrap this for me?","grammar:91375:ex:trans":"I wrapped the present in pretty paper.","grammar:91375:ex:structure":"〔thing〕を＋〔material〕で包む","grammar:91375:ex:explain":"「包む」 means to wrap something up entirely in paper or cloth, and it is often used for presents and boxed lunches. The wrapping material takes 「で」. 「包み紙（つつみがみ）」 means wrapping paper.","grammar:91375:ex:words:0:zh":"present","grammar:91375:ex:words:0:pos":"noun","grammar:91375:ex:words:1:zh":"(object marker)","grammar:91375:ex:words:1:pos":"particle","grammar:91375:ex:words:2:zh":"beautiful","grammar:91375:ex:words:2:pos":"na-adjective","grammar:91375:ex:words:3:zh":"(links to the noun that follows)","grammar:91375:ex:words:3:pos":"particle","grammar:91375:ex:words:4:zh":"paper","grammar:91375:ex:words:4:note":"かみ","grammar:91375:ex:words:4:pos":"noun","grammar:91375:ex:words:5:zh":"with (a tool)","grammar:91375:ex:words:5:pos":"particle","grammar:91375:ex:words:6:zh":"wrapped it up","grammar:91375:ex:words:6:note":"つつみました; the past masu-form of 包む","grammar:91375:ex:words:6:pos":"verb","grammar:91375:ex:points:0":"包む = to wrap something in paper or cloth","grammar:91375:ex:points:1":"A na-adjective needs 「な」 before a noun: きれいな紙","grammar:91375:ex2:trans":"Could you wrap this for me?","grammar:91375:ex2:structure":"〔thing〕を包んで＋いただけますか","grammar:91375:ex2:words:0:zh":"this","grammar:91375:ex2:words:0:pos":"pronoun","grammar:91375:ex2:words:1:zh":"(object marker)","grammar:91375:ex2:words:1:pos":"particle","grammar:91375:ex2:words:2:zh":"bag","grammar:91375:ex2:words:2:note":"つつんで; the te-form of 包む","grammar:91375:ex2:words:2:pos":"verb","grammar:91375:ex2:words:3:zh":"could you please do (it for me)","grammar:91375:ex2:words:3:note":"いただけます; the potential form of いただく","grammar:91375:ex2:words:3:pos":"auxiliary verb","grammar:91375:ex2:words:4:zh":"(question)","grammar:91375:ex2:words:4:pos":"particle","grammar:91375:ex2:points:0":"包んでいただけますか: could you wrap this for me? Often said when buying a gift","grammar:91375:ex2:points:1":"〜ていただけますか: a very polite way to ask someone for a favor"},"91376":{"example:91376:exzh":"There's a meeting in the meeting room from three o'clock.","example:91376:exzh2":"I've already reserved the meeting room.","grammar:91376:ex:trans":"There's a meeting in the meeting room from three o'clock.","grammar:91376:ex:structure":"〔time〕から＋〔place〕で＋〔event〕があります","grammar:91376:ex:explain":"「会議室」 is 「会議」 (meeting) plus 「室」 (room). Note: for 'something is in a place' you use 「に」, but for 'an event is held in a place' you use 「で」, so it is 「会議室で会議があります」. This particle difference is often tested on the N4 exam.","grammar:91376:ex:words:0:zh":"three o'clock","grammar:91376:ex:words:0:note":"さんじ","grammar:91376:ex:words:0:pos":"noun","grammar:91376:ex:words:1:zh":"from","grammar:91376:ex:words:1:pos":"particle","grammar:91376:ex:words:2:zh":"meeting room","grammar:91376:ex:words:2:note":"かいぎしつ","grammar:91376:ex:words:2:pos":"noun","grammar:91376:ex:words:3:zh":"at / in (where the action happens)","grammar:91376:ex:words:3:pos":"particle","grammar:91376:ex:words:4:zh":"meeting","grammar:91376:ex:words:4:note":"かいぎ","grammar:91376:ex:words:4:pos":"noun","grammar:91376:ex:words:5:zh":"(nominative)","grammar:91376:ex:words:5:pos":"particle","grammar:91376:ex:words:6:zh":"there is / are","grammar:91376:ex:words:6:note":"あります; the masu-form (polite form) of ある","grammar:91376:ex:words:6:pos":"verb","grammar:91376:ex:points:1":"For events and meetings, use 「〔place〕で〜があります」; the place takes 「で」, not 「に」","grammar:91376:ex2:trans":"I've already booked the meeting room.","grammar:91376:ex2:structure":"〔place〕の予約を＋しておく","grammar:91376:ex2:words:0:zh":"meeting room","grammar:91376:ex2:words:0:note":"かいぎしつ","grammar:91376:ex2:words:0:pos":"noun","grammar:91376:ex2:words:1:zh":"'s","grammar:91376:ex2:words:1:pos":"particle","grammar:91376:ex2:words:2:zh":"reservation","grammar:91376:ex2:words:2:note":"よやく","grammar:91376:ex2:words:2:pos":"noun","grammar:91376:ex2:words:3:zh":"(object marker)","grammar:91376:ex2:words:3:pos":"particle","grammar:91376:ex2:words:4:zh":"do","grammar:91376:ex2:words:4:note":"して; the te-form of する","grammar:91376:ex2:words:4:pos":"verb","grammar:91376:ex2:words:5:zh":"(did it) in advance","grammar:91376:ex2:words:5:note":"おきました; the past masu-form of おく","grammar:91376:ex2:words:5:pos":"auxiliary verb","grammar:91376:ex2:points:0":"会議室の予約をする: to book a meeting room","grammar:91376:ex2:points:1":"〜ておく: to do something in advance for later"},"91377":{"example:91377:exzh":"My daughter is playing with dolls.","example:91377:exzh2":"I bought a cute doll in Kyoto.","grammar:91377:ex:trans":"My daughter is playing with dolls.","grammar:91377:ex:structure":"〔toy〕で＋遊んでいます","grammar:91377:ex:explain":"「人形」 is read 「にんぎょう」 and means a doll or figure made in the shape of a person; Japan has traditional dolls such as 「ひな人形」. In Japanese, 'playing with a doll' is 「人形で遊ぶ」: the toy is treated as a tool and takes 「で」.","grammar:91377:ex:words:0:zh":"daughter","grammar:91377:ex:words:0:note":"むすめ","grammar:91377:ex:words:0:pos":"noun","grammar:91377:ex:words:1:zh":"(topic)","grammar:91377:ex:words:1:pos":"particle","grammar:91377:ex:words:2:zh":"doll","grammar:91377:ex:words:2:note":"にんぎょう","grammar:91377:ex:words:2:pos":"noun","grammar:91377:ex:words:3:zh":"with (a tool)","grammar:91377:ex:words:3:pos":"particle","grammar:91377:ex:words:4:zh":"hang out","grammar:91377:ex:words:4:note":"あそんで; te-form of 遊ぶ","grammar:91377:ex:words:4:pos":"verb","grammar:91377:ex:words:5:zh":"(in the middle of) ~ing","grammar:91377:ex:words:5:note":"います; the masu-form of いる","grammar:91377:ex:words:5:pos":"auxiliary verb","grammar:91377:ex:points:0":"人形 = doll, figure; the reading is 「にんぎょう」, not 「じんけい」","grammar:91377:ex:points:1":"〜で遊ぶ: to play with ~; the thing you play with takes 「で」, not 「を」","grammar:91377:ex2:trans":"I bought a cute doll in Kyoto.","grammar:91377:ex2:structure":"〔place〕で＋〔thing〕を買いました","grammar:91377:ex2:words:0:zh":"Kyoto","grammar:91377:ex2:words:0:note":"きょうと","grammar:91377:ex2:words:0:pos":"noun","grammar:91377:ex2:words:1:zh":"at / in (where the action happens)","grammar:91377:ex2:words:1:pos":"particle","grammar:91377:ex2:words:2:zh":"cute","grammar:91377:ex2:words:2:pos":"adjective","grammar:91377:ex2:words:3:zh":"doll","grammar:91377:ex2:words:3:note":"にんぎょう","grammar:91377:ex2:words:3:pos":"noun","grammar:91377:ex2:words:4:zh":"(object marker)","grammar:91377:ex2:words:4:pos":"particle","grammar:91377:ex2:words:5:zh":"bought","grammar:91377:ex2:words:5:note":"かいました; past masu-form of 買う","grammar:91377:ex2:words:5:pos":"verb","grammar:91377:ex2:points:0":"かわいい人形: a cute doll","grammar:91377:ex2:points:1":"The place where you buy something takes 「で」"},"91378":{"example:91378:exzh":"I'm moving to Japan the month after next.","example:91378:exzh2":"The exam is on the tenth of the month after next.","grammar:91378:ex:trans":"I'm moving to Japan the month after next.","grammar:91378:ex:structure":"再来月、＋〔place〕へ引っ越します","grammar:91378:ex:explain":"「再来月」 is read 「さらいげつ」; note that 「再」 is not read 「さい」. The same applies to 「再来週」 (the week after next) and 「再来年」 (the year after next). Relative time words like 「再来月」 do not take 「に」.","grammar:91378:ex:words:0:zh":"the month after next","grammar:91378:ex:words:0:note":"さらいげつ","grammar:91378:ex:words:0:pos":"noun","grammar:91378:ex:words:1:zh":"Japan","grammar:91378:ex:words:1:note":"にほん","grammar:91378:ex:words:1:pos":"noun","grammar:91378:ex:words:2:zh":"to","grammar:91378:ex:words:2:pos":"particle","grammar:91378:ex:words:3:zh":"to move house","grammar:91378:ex:words:3:note":"ひっこします; the masu-form of 引っ越す","grammar:91378:ex:words:3:pos":"verb","grammar:91378:ex:points:0":"再来月 = the month after next; here 「再」 is read 「さ」","grammar:91378:ex2:trans":"The exam is on the tenth of the month after next.","grammar:91378:ex2:structure":"〔event〕は＋再来月の〔date〕です","grammar:91378:ex2:words:0:zh":"test","grammar:91378:ex2:words:0:note":"しけん","grammar:91378:ex2:words:0:pos":"noun","grammar:91378:ex2:words:1:zh":"(topic)","grammar:91378:ex2:words:1:pos":"particle","grammar:91378:ex2:words:2:zh":"the month after next","grammar:91378:ex2:words:2:note":"さらいげつ","grammar:91378:ex2:words:2:pos":"noun","grammar:91378:ex2:words:3:zh":"'s","grammar:91378:ex2:words:3:pos":"particle","grammar:91378:ex2:words:4:zh":"the tenth","grammar:91378:ex2:words:4:note":"とおか","grammar:91378:ex2:words:4:pos":"noun","grammar:91378:ex2:words:5:zh":"is (polite form)","grammar:91378:ex2:words:5:pos":"copula","grammar:91378:ex2:points:0":"再来月の十日: the tenth of the month after next","grammar:91378:ex2:points:1":"十日 is read 「とおか」, which is an irregular reading"},"91379":{"example:91379:exzh":"The stars are shining in the night sky.","example:91379:exzh2":"Something flashed in the distance.","grammar:91379:ex:trans":"The stars are shining in the night sky.","grammar:91379:ex:structure":"〔thing〕が＋光っています","grammar:91379:ex:explain":"「光る」 describes something that gives off or reflects light by itself; it is an intransitive verb, so it takes 「が」. The noun is 「光（ひかり）」. 「星が光る」 is a typical way to describe the night sky.","grammar:91379:ex:words:0:zh":"night sky","grammar:91379:ex:words:0:note":"よぞら","grammar:91379:ex:words:0:pos":"noun","grammar:91379:ex:words:1:zh":"in (a place)","grammar:91379:ex:words:1:pos":"particle","grammar:91379:ex:words:2:zh":"star","grammar:91379:ex:words:2:note":"ほし","grammar:91379:ex:words:2:pos":"noun","grammar:91379:ex:words:3:zh":"(nominative)","grammar:91379:ex:words:3:pos":"particle","grammar:91379:ex:words:4:zh":"to shine","grammar:91379:ex:words:4:note":"ひかって; the te-form of 光る","grammar:91379:ex:words:4:pos":"verb","grammar:91379:ex:words:5:zh":"(in the middle of) ~ing","grammar:91379:ex:words:5:note":"います; the masu-form of いる","grammar:91379:ex:words:5:pos":"auxiliary verb","grammar:91379:ex:points:0":"光る = to give off light by itself, to shine; it can be used for stars, eyes and jewels","grammar:91379:ex:points:1":"〜ている: expresses an action in progress or an ongoing state","grammar:91379:ex2:trans":"Something flashed in the distance.","grammar:91379:ex2:structure":"〔place〕で＋何かが光りました","grammar:91379:ex2:words:0:zh":"in the distance","grammar:91379:ex2:words:0:note":"とおく","grammar:91379:ex2:words:0:pos":"noun","grammar:91379:ex2:words:1:zh":"in (a place)","grammar:91379:ex2:words:1:pos":"particle","grammar:91379:ex2:words:2:zh":"something","grammar:91379:ex2:words:2:note":"なにか","grammar:91379:ex2:words:2:pos":"pronoun","grammar:91379:ex2:words:3:zh":"(nominative)","grammar:91379:ex2:words:3:pos":"particle","grammar:91379:ex2:words:4:zh":"flashed for a moment","grammar:91379:ex2:words:4:note":"ひかりました; the past masu-form of 光る","grammar:91379:ex2:words:4:pos":"verb","grammar:91379:ex2:points:0":"何かが光る: something lights up for a moment","grammar:91379:ex2:points:1":"何か = something (you are not sure what)"},"91380":{"example:91380:exzh":"I went to the airport to pick up a friend.","example:91380:exzh2":"This island has a small airport.","grammar:91380:ex:trans":"I went to the airport to pick up a friend.","grammar:91380:ex:structure":"〔place〕まで＋〔person〕を迎えに行く","grammar:91380:ex:explain":"「飛行場」 means a place where planes take off and land; it is the same as 「空港」, but today full-scale airports are usually called 「空港」, while 「飛行場」 often refers to a small airfield. 「迎えに行く」 means to go and pick someone up, and 「verb masu-stem＋に行く」 expresses the purpose of the movement.","grammar:91380:ex:words:0:zh":"airport","grammar:91380:ex:words:0:note":"ひこうじょう","grammar:91380:ex:words:0:pos":"noun","grammar:91380:ex:words:1:zh":"until","grammar:91380:ex:words:1:pos":"particle","grammar:91380:ex:words:2:zh":"friend","grammar:91380:ex:words:2:note":"ともだち","grammar:91380:ex:words:2:pos":"noun","grammar:91380:ex:words:3:zh":"(object marker)","grammar:91380:ex:words:3:pos":"particle","grammar:91380:ex:words:4:zh":"pick up","grammar:91380:ex:words:4:note":"むかえ；the masu-form stem of 「迎える」","grammar:91380:ex:words:4:pos":"verb","grammar:91380:ex:words:5:zh":"(the purpose of going to do ~)","grammar:91380:ex:words:5:pos":"particle","grammar:91380:ex:words:6:zh":"went","grammar:91380:ex:words:6:note":"いきました; past masu-form of 行く","grammar:91380:ex:words:6:pos":"verb","grammar:91380:ex:points:0":"飛行場 = airport; today people usually say 「空港（くうこう）」","grammar:91380:ex:points:1":"〔verb masu-stem〕に行く: to go in order to do ~; 迎えに行く = to go pick someone up","grammar:91380:ex2:trans":"This island has a small airfield.","grammar:91380:ex2:structure":"〔place〕には＋〔thing〕があります","grammar:91380:ex2:words:0:zh":"this","grammar:91380:ex2:words:0:pos":"pre-noun adjectival","grammar:91380:ex2:words:1:zh":"island","grammar:91380:ex2:words:1:note":"しま","grammar:91380:ex2:words:1:pos":"noun","grammar:91380:ex2:words:2:zh":"in (the place where something exists)","grammar:91380:ex2:words:2:pos":"particle","grammar:91380:ex2:words:3:zh":"(topic)","grammar:91380:ex2:words:3:pos":"particle","grammar:91380:ex2:words:4:zh":"small","grammar:91380:ex2:words:4:note":"ちいさい","grammar:91380:ex2:words:4:pos":"adjective","grammar:91380:ex2:words:5:zh":"airport","grammar:91380:ex2:words:5:note":"ひこうじょう","grammar:91380:ex2:words:5:pos":"noun","grammar:91380:ex2:words:6:zh":"(nominative)","grammar:91380:ex2:words:6:pos":"particle","grammar:91380:ex2:words:7:zh":"there is / are","grammar:91380:ex2:words:7:note":"あります; the masu-form (polite form) of ある","grammar:91380:ex2:words:7:pos":"verb","grammar:91380:ex2:points:0":"小さい飛行場: a small airfield (「飛行場」 is very natural here)","grammar:91380:ex2:points:1":"Buildings and facilities take 「あります」"},"91381":{"example:91381:exzh":"My younger brother takes judo lessons every week.","example:91381:exzh2":"Judo is a sport that was born in Japan.","grammar:91381:ex:trans":"My younger brother has judo lessons every week.","grammar:91381:ex:structure":"〔person〕は＋〔skill〕を習っています","grammar:91381:ex:explain":"「柔道」 is read 「じゅうどう」, with a long vowel in both characters. For learning skills or sports from a teacher, Japanese usually uses 「習う」, as in 「ピアノを習う」. 「〜ています」 expresses an ongoing habit.","grammar:91381:ex:words:0:zh":"younger brother","grammar:91381:ex:words:0:note":"おとうと","grammar:91381:ex:words:0:pos":"noun","grammar:91381:ex:words:1:zh":"(topic)","grammar:91381:ex:words:1:pos":"particle","grammar:91381:ex:words:2:zh":"every week","grammar:91381:ex:words:2:note":"まいしゅう","grammar:91381:ex:words:2:pos":"noun","grammar:91381:ex:words:3:zh":"judo","grammar:91381:ex:words:3:note":"じゅうどう","grammar:91381:ex:words:3:pos":"noun","grammar:91381:ex:words:4:zh":"(object marker)","grammar:91381:ex:words:4:pos":"particle","grammar:91381:ex:words:5:zh":"study / learn","grammar:91381:ex:words:5:note":"ならって; the te-form of 習う","grammar:91381:ex:words:5:pos":"verb","grammar:91381:ex:words:6:zh":"(habitually) is ~ing","grammar:91381:ex:words:6:note":"います; the masu-form of いる","grammar:91381:ex:words:6:pos":"auxiliary verb","grammar:91381:ex:points:1":"習う: to learn a skill from a teacher; 「勉強する」 leans toward studying knowledge from books","grammar:91381:ex2:trans":"Judo is a sport that was born in Japan.","grammar:91381:ex2:structure":"〔noun〕は＋〔place〕で生まれた〔noun〕です","grammar:91381:ex2:words:0:zh":"judo","grammar:91381:ex2:words:0:note":"じゅうどう","grammar:91381:ex2:words:0:pos":"noun","grammar:91381:ex2:words:1:zh":"(topic)","grammar:91381:ex2:words:1:pos":"particle","grammar:91381:ex2:words:2:zh":"Japan","grammar:91381:ex2:words:2:note":"にほん","grammar:91381:ex2:words:2:pos":"noun","grammar:91381:ex2:words:3:zh":"in (a place)","grammar:91381:ex2:words:3:pos":"particle","grammar:91381:ex2:words:4:zh":"birth","grammar:91381:ex2:words:4:note":"うまれた; the ta-form of 生まれる","grammar:91381:ex2:words:4:pos":"verb","grammar:91381:ex2:words:5:zh":"exercise","grammar:91381:ex2:words:5:pos":"noun","grammar:91381:ex2:words:6:zh":"is (polite form)","grammar:91381:ex2:words:6:pos":"copula","grammar:91381:ex2:points:0":"柔道は〜スポーツです: judo is a ~ sport","grammar:91381:ex2:points:1":"The ta-form can modify a noun: 日本で生まれたスポーツ"},"91382":{"example:91382:exzh":"What are you doing, teacher?","example:91382:exzh2":"What will you do over the weekend?","grammar:91382:ex:trans":"What is the teacher doing?","grammar:91382:ex:structure":"〔superior〕は＋何をなさっていますか","grammar:91382:ex:explain":"「なさる」 is the sonkeigo (respectful) form of 「する」, used to speak of someone else's actions more politely. Its masu-form is 「なさいます」 (not なさります), and its te-form is 「なさって」. This sentence asks what the teacher is doing, using respectful language to show respect for the teacher.","grammar:91382:ex:words:0:zh":"teacher","grammar:91382:ex:words:0:note":"せんせい","grammar:91382:ex:words:0:pos":"noun","grammar:91382:ex:words:1:zh":"(topic)","grammar:91382:ex:words:1:pos":"particle","grammar:91382:ex:words:2:zh":"what","grammar:91382:ex:words:2:note":"なに","grammar:91382:ex:words:2:pos":"question word","grammar:91382:ex:words:3:zh":"(object marker)","grammar:91382:ex:words:3:pos":"particle","grammar:91382:ex:words:4:zh":"to do (respectful)","grammar:91382:ex:words:4:note":"なさって; the te-form of なさる","grammar:91382:ex:words:4:pos":"verb","grammar:91382:ex:words:5:zh":"(in the middle of) ~ing","grammar:91382:ex:words:5:note":"います; the masu-form of いる","grammar:91382:ex:words:5:pos":"auxiliary verb","grammar:91382:ex:words:6:zh":"(question)","grammar:91382:ex:words:6:pos":"particle","grammar:91382:ex:points:0":"なさる = the sonkeigo (respectful) form of 「する」, used for the actions of superiors and customers","grammar:91382:ex:points:1":"You cannot use 「なさる」 for your own actions; use the humble 「いたす」","grammar:91382:ex2:trans":"What are you planning to do this weekend?","grammar:91382:ex2:structure":"〔time〕は＋どうなさいますか","grammar:91382:ex2:words:0:zh":"weekend","grammar:91382:ex2:words:0:note":"しゅうまつ","grammar:91382:ex2:words:0:pos":"noun","grammar:91382:ex2:words:1:zh":"(topic)","grammar:91382:ex2:words:1:pos":"particle","grammar:91382:ex2:words:2:zh":"how","grammar:91382:ex2:words:2:pos":"question word","grammar:91382:ex2:words:3:zh":"to do (respectful)","grammar:91382:ex2:words:3:note":"なさいます; the masu-form of なさる","grammar:91382:ex2:words:3:pos":"verb","grammar:91382:ex2:words:4:zh":"(question)","grammar:91382:ex2:words:4:pos":"particle","grammar:91382:ex2:points:0":"どうなさいますか = what would you like to do? Commonly used by shop staff and service workers","grammar:91382:ex2:points:1":"The masu-form of なさる is 「なさいます」; memorize this one"},"91383":{"example:91383:exzh":"On Sunday I saw paintings at the art museum.","example:91383:exzh2":"This art museum is closed on Mondays.","grammar:91383:ex:trans":"On Sunday I looked at paintings at the museum.","grammar:91383:ex:structure":"〔place〕で＋絵を見る","grammar:91383:ex:explain":"「美術館」 is pronounced 「びじゅつかん」 and displays works of art such as paintings and sculptures. This sentence uses 「で」 to mark the location of the action, and 「絵を見る」 means to look at paintings.","grammar:91383:ex:words:0:zh":"Sunday","grammar:91383:ex:words:0:note":"にちようび","grammar:91383:ex:words:0:pos":"noun","grammar:91383:ex:words:1:zh":"(point in time)","grammar:91383:ex:words:1:pos":"particle","grammar:91383:ex:words:2:zh":"Art museum","grammar:91383:ex:words:2:note":"びじゅつかん","grammar:91383:ex:words:2:pos":"noun","grammar:91383:ex:words:3:zh":"at / in (where the action happens)","grammar:91383:ex:words:3:pos":"particle","grammar:91383:ex:words:4:zh":"picture","grammar:91383:ex:words:4:note":"え","grammar:91383:ex:words:4:pos":"noun","grammar:91383:ex:words:5:zh":"(object marker)","grammar:91383:ex:words:5:pos":"particle","grammar:91383:ex:words:6:zh":"watched","grammar:91383:ex:words:6:note":"みました; past tense of the masu-form of 見る","grammar:91383:ex:words:6:pos":"verb","grammar:91383:ex:points:1":"Use 「見る」 for looking at paintings; use 「読む」 for reading books","grammar:91383:ex2:trans":"This art museum is closed on Mondays.","grammar:91383:ex2:structure":"〔place〕は＋〔day of the week〕が休みです","grammar:91383:ex2:words:0:zh":"this","grammar:91383:ex2:words:0:pos":"pre-noun adjectival","grammar:91383:ex2:words:1:zh":"Art museum","grammar:91383:ex2:words:1:note":"びじゅつかん","grammar:91383:ex2:words:1:pos":"noun","grammar:91383:ex2:words:2:zh":"(topic)","grammar:91383:ex2:words:2:pos":"particle","grammar:91383:ex2:words:3:zh":"Monday","grammar:91383:ex2:words:3:note":"げつようび","grammar:91383:ex2:words:3:pos":"noun","grammar:91383:ex2:words:4:zh":"(nominative)","grammar:91383:ex2:words:4:pos":"particle","grammar:91383:ex2:words:5:zh":"day the museum is closed","grammar:91383:ex2:words:5:note":"やすみ; the noun form of 休む","grammar:91383:ex2:words:5:pos":"noun","grammar:91383:ex2:words:6:zh":"is (polite form)","grammar:91383:ex2:words:6:pos":"copula","grammar:91383:ex2:points:0":"〜は月曜日が休みです: … is closed on Mondays; a common way to state the regular closing day of a shop or facility","grammar:91383:ex2:points:1":"The 「AはBが〜」 pattern: A is the topic, and B provides the specific explanation"},"91384":{"example:91384:exzh":"Japanese grammar is difficult.","example:91384:exzh2":"I learned new grammar in class.","grammar:91384:ex:trans":"Japanese grammar is difficult.","grammar:91384:ex:structure":"〔noun〕は＋難しいです","grammar:91384:ex:explain":"「文法」 is pronounced 「ぶんぽう」. 「法」 becomes 「ぽう」 because of the preceding 「ん」. 「難しい」 is an い-adjective; adding 「です」 directly makes it polite.","grammar:91384:ex:words:0:zh":"Japanese","grammar:91384:ex:words:0:note":"にほんご","grammar:91384:ex:words:0:pos":"noun","grammar:91384:ex:words:1:zh":"'s","grammar:91384:ex:words:1:pos":"particle","grammar:91384:ex:words:2:zh":"grammar","grammar:91384:ex:words:2:note":"ぶんぽう","grammar:91384:ex:words:2:pos":"noun","grammar:91384:ex:words:3:zh":"(topic)","grammar:91384:ex:words:3:pos":"particle","grammar:91384:ex:words:4:zh":"difficult","grammar:91384:ex:words:4:note":"むずかしい","grammar:91384:ex:words:4:pos":"adjective","grammar:91384:ex:words:5:zh":"is (polite form)","grammar:91384:ex:words:5:pos":"copula","grammar:91384:ex:points:0":"文法 = grammar; pronounced 「ぶんぽう」, with 「法」 pronounced 「ぽう」","grammar:91384:ex:points:1":"難しい = difficult; easy is 「易しい（やさしい）」 or 「簡単（かんたん）」","grammar:91384:ex2:trans":"We learned new grammar in class.","grammar:91384:ex2:structure":"〔place〕で＋〔content〕を習いました","grammar:91384:ex2:words:0:zh":"class","grammar:91384:ex2:words:0:note":"じゅぎょう","grammar:91384:ex2:words:0:pos":"noun","grammar:91384:ex2:words:1:zh":"at / in (where the action happens)","grammar:91384:ex2:words:1:pos":"particle","grammar:91384:ex2:words:2:zh":"new","grammar:91384:ex2:words:2:note":"あたらしい","grammar:91384:ex2:words:2:pos":"adjective","grammar:91384:ex2:words:3:zh":"grammar","grammar:91384:ex2:words:3:note":"ぶんぽう","grammar:91384:ex2:words:3:pos":"noun","grammar:91384:ex2:words:4:zh":"(object marker)","grammar:91384:ex2:words:4:pos":"particle","grammar:91384:ex2:words:5:zh":"learned","grammar:91384:ex2:words:5:note":"ならいました; past tense of the masu-form of 習う","grammar:91384:ex2:words:5:pos":"verb","grammar:91384:ex2:points:0":"文法を習う: learn grammar (from a teacher)","grammar:91384:ex2:points:1":"授業で: in class"},"91385":{"example:91385:exzh":"Once you know the results, please let me know.","example:91385:exzh2":"When I get to the station, I'll call and let you know.","grammar:91385:ex:trans":"Please let me know when you know the results.","grammar:91385:ex:structure":"〜たら、＋知らせてください","grammar:91385:ex:explain":"「知らせる」 means to make someone else 「知る（know）」, in other words, to notify or inform them. Compared with 「教える」, 「知らせる」 focuses on passing on news rather than teaching someone knowledge. This sentence uses 「〜たら」 to mean \"once you know the results.\"","grammar:91385:ex:words:0:zh":"result","grammar:91385:ex:words:0:note":"けっか","grammar:91385:ex:words:0:pos":"noun","grammar:91385:ex:words:1:zh":"(nominative)","grammar:91385:ex:words:1:pos":"particle","grammar:91385:ex:words:2:zh":"once you know","grammar:91385:ex:words:2:note":"わかったら; たら-form of わかる","grammar:91385:ex:words:2:pos":"verb","grammar:91385:ex:words:3:zh":"notify","grammar:91385:ex:words:3:note":"しらせて; te-form of 知らせる","grammar:91385:ex:words:3:pos":"verb","grammar:91385:ex:words:4:zh":"please ~","grammar:91385:ex:words:4:note":"ください; the imperative form of くださる","grammar:91385:ex:words:4:pos":"auxiliary verb","grammar:91385:ex:points:0":"知らせる = tell someone the news; notify; the noun is 「知らせ（notification, news）」","grammar:91385:ex:points:1":"〜たら: once …; if …","grammar:91385:ex2:trans":"I'll call to let you know when I arrive at the station.","grammar:91385:ex2:structure":"〜たら、＋電話で知らせます","grammar:91385:ex2:words:0:zh":"station","grammar:91385:ex2:words:0:note":"えき","grammar:91385:ex2:words:0:pos":"noun","grammar:91385:ex2:words:1:zh":"at (the destination)","grammar:91385:ex2:words:1:pos":"particle","grammar:91385:ex2:words:2:zh":"when it comes","grammar:91385:ex2:words:2:note":"ついたら; the たら form of 着く","grammar:91385:ex2:words:2:pos":"verb","grammar:91385:ex2:words:3:zh":"phone call","grammar:91385:ex2:words:3:note":"でんわ","grammar:91385:ex2:words:3:pos":"noun","grammar:91385:ex2:words:4:zh":"by (means)","grammar:91385:ex2:words:4:pos":"particle","grammar:91385:ex2:words:5:zh":"notify","grammar:91385:ex2:words:5:note":"しらせます; masu-form of 知らせる","grammar:91385:ex2:words:5:pos":"verb","grammar:91385:ex2:points:0":"電話で知らせる: notify by phone","grammar:91385:ex2:points:1":"〔place〕に着く: arrive at …"},"91386":{"example:91386:exzh":"My tooth hurts, so I'm going to the dentist.","example:91386:exzh2":"I have a dentist appointment tomorrow.","grammar:91386:ex:trans":"My tooth hurts, so I'm going to the dentist.","grammar:91386:ex:structure":"〜ので、＋歯医者に行きます","grammar:91386:ex:explain":"「歯医者」 combines 「歯（tooth）」 and 「医者（doctor）」 and is pronounced 「はいしゃ」. 「歯医者に行く」 means to go to the dentist. The word can refer to either the dentist or the dental clinic. 「〜ので」 explains the reason in a relatively gentle tone.","grammar:91386:ex:words:0:zh":"teeth","grammar:91386:ex:words:0:note":"は","grammar:91386:ex:words:0:pos":"noun","grammar:91386:ex:words:1:zh":"(nominative)","grammar:91386:ex:words:1:pos":"particle","grammar:91386:ex:words:2:zh":"painful","grammar:91386:ex:words:2:note":"いたい","grammar:91386:ex:words:2:pos":"adjective","grammar:91386:ex:words:3:zh":"because","grammar:91386:ex:words:3:pos":"particle","grammar:91386:ex:words:4:zh":"dentist","grammar:91386:ex:words:4:note":"はいしゃ","grammar:91386:ex:words:4:pos":"noun","grammar:91386:ex:words:5:zh":"to (the place you go to)","grammar:91386:ex:words:5:pos":"particle","grammar:91386:ex:words:6:zh":"go","grammar:91386:ex:words:6:note":"いきます; masu-form of 行く","grammar:91386:ex:words:6:pos":"verb","grammar:91386:ex:points:0":"歯医者 = dentist (can also refer to a dental clinic); 「歯医者に行く」 = go to the dentist","grammar:91386:ex:points:1":"〜が痛い: … hurts; 〜ので: because …","grammar:91386:ex2:trans":"I have a dentist appointment tomorrow.","grammar:91386:ex2:structure":"〔place〕の予約があります","grammar:91386:ex2:words:0:zh":"tomorrow","grammar:91386:ex2:words:0:note":"あした","grammar:91386:ex2:words:0:pos":"noun","grammar:91386:ex2:words:1:zh":"dentist","grammar:91386:ex2:words:1:note":"はいしゃ","grammar:91386:ex2:words:1:pos":"noun","grammar:91386:ex2:words:2:zh":"'s","grammar:91386:ex2:words:2:pos":"particle","grammar:91386:ex2:words:3:zh":"reservation","grammar:91386:ex2:words:3:note":"よやく","grammar:91386:ex2:words:3:pos":"noun","grammar:91386:ex2:words:4:zh":"(nominative)","grammar:91386:ex2:words:4:pos":"particle","grammar:91386:ex2:words:5:zh":"there is / are","grammar:91386:ex2:words:5:note":"あります; the masu-form (polite form) of ある","grammar:91386:ex2:words:5:pos":"verb","grammar:91386:ex2:points:0":"歯医者の予約: a dentist appointment","grammar:91386:ex2:points:1":"予約がある: have an appointment"},"91387":{"example:91387:exzh":"I've already gotten over my cold.","example:91387:exzh2":"Once my injury heals, I want to run again.","grammar:91387:ex:trans":"My cold has already cleared up.","grammar:91387:ex:structure":"〔illness〕は＋もう治りました","grammar:91387:ex:explain":"「治る」 means that an illness or injury heals, with the focus on physical recovery. The homophone 「直る」 means that something has been fixed; note the different kanji. 「もう」＋past tense means \"already … .\"","grammar:91387:ex:words:0:zh":"a cold","grammar:91387:ex:words:0:note":"かぜ","grammar:91387:ex:words:0:pos":"noun","grammar:91387:ex:words:1:zh":"(topic)","grammar:91387:ex:words:1:pos":"particle","grammar:91387:ex:words:2:zh":"already","grammar:91387:ex:words:2:pos":"adverb","grammar:91387:ex:words:3:zh":"recovered","grammar:91387:ex:words:3:note":"なおりました; past tense of the masu-form of 治る","grammar:91387:ex:words:3:pos":"verb","grammar:91387:ex:points:0":"治る = an illness or injury heals on its own; it is an intransitive verb used with 「が／は」","grammar:91387:ex:points:1":"When a doctor cures an illness, use the transitive verb 「治す（なおす）」","grammar:91387:ex2:trans":"I want to run again once my injury has healed.","grammar:91387:ex2:structure":"〜たら、＋〜たいです","grammar:91387:ex2:words:0:zh":"scar","grammar:91387:ex2:words:0:pos":"noun","grammar:91387:ex2:words:1:zh":"(nominative)","grammar:91387:ex2:words:1:pos":"particle","grammar:91387:ex2:words:2:zh":"once it has healed","grammar:91387:ex2:words:2:note":"なおったら; たら-form of 治る","grammar:91387:ex2:words:2:pos":"verb","grammar:91387:ex2:words:3:zh":"again","grammar:91387:ex2:words:3:pos":"adverb","grammar:91387:ex2:words:4:zh":"want to run","grammar:91387:ex2:words:4:note":"はしりたい; 走る＋たい","grammar:91387:ex2:words:4:pos":"verb","grammar:91387:ex2:words:5:zh":"is (polite form)","grammar:91387:ex2:words:5:pos":"copula","grammar:91387:ex2:points:0":"けがが治る: an injury heals","grammar:91387:ex2:points:1":"〜たら: after …; 〜たい: want to …"},"91388":{"example:91388:exzh":"I have a fever, so I'm taking today off.","example:91388:exzh2":"My child got a fever at night.","grammar:91388:ex:trans":"I have a fever, so I'm taking the day off today.","grammar:91388:ex:structure":"熱があるので、＋〜","grammar:91388:ex:explain":"「熱」 here refers to a high body temperature, meaning a fever. In Japanese, having a fever is expressed as 「熱がある（have heat）」 or 「熱が出る（heat comes out）」. This sentence uses 「ので」 to explain the reason for taking time off; it is a very natural way to do so.","grammar:91388:ex:words:0:zh":"fever, temperature","grammar:91388:ex:words:0:note":"ねつ","grammar:91388:ex:words:0:pos":"noun","grammar:91388:ex:words:1:zh":"(nominative)","grammar:91388:ex:words:1:pos":"particle","grammar:91388:ex:words:2:zh":"there is / are","grammar:91388:ex:words:2:note":"ある","grammar:91388:ex:words:2:pos":"verb","grammar:91388:ex:words:3:zh":"because","grammar:91388:ex:words:3:pos":"particle","grammar:91388:ex:words:4:zh":"today","grammar:91388:ex:words:4:note":"きょう","grammar:91388:ex:words:4:pos":"noun","grammar:91388:ex:words:5:zh":"(topic)","grammar:91388:ex:words:5:pos":"particle","grammar:91388:ex:words:6:zh":"taking time off","grammar:91388:ex:words:6:note":"やすみます: the masu-form of 休む.","grammar:91388:ex:words:6:pos":"verb","grammar:91388:ex:points:0":"熱がある = have a fever; Japanese literally says \"have heat,\" rather than \"a fever has developed\"","grammar:91388:ex:points:1":"〜ので: because …","grammar:91388:ex2:trans":"The child developed a fever at night.","grammar:91388:ex2:structure":"〔person〕が＋熱を出す","grammar:91388:ex2:words:0:zh":"child","grammar:91388:ex2:words:0:note":"こども","grammar:91388:ex2:words:0:pos":"noun","grammar:91388:ex2:words:1:zh":"(nominative)","grammar:91388:ex2:words:1:pos":"particle","grammar:91388:ex2:words:2:zh":"evening","grammar:91388:ex2:words:2:note":"よる","grammar:91388:ex2:words:2:pos":"noun","grammar:91388:ex2:words:3:zh":"(point in time)","grammar:91388:ex2:words:3:pos":"particle","grammar:91388:ex2:words:4:zh":"fever","grammar:91388:ex2:words:4:note":"ねつ","grammar:91388:ex2:words:4:pos":"noun","grammar:91388:ex2:words:5:zh":"(object marker)","grammar:91388:ex2:words:5:pos":"particle","grammar:91388:ex2:words:6:zh":"developed (a fever)","grammar:91388:ex2:words:6:note":"だしました; past tense of the masu-form of 出す","grammar:91388:ex2:words:6:pos":"verb","grammar:91388:ex2:points:0":"熱を出す: develop a fever; you can also say 「熱が出る」","grammar:91388:ex2:points:1":"夜に: at night"},"91389":{"example:91389:exzh":"The class bell rang.","example:91389:exzh2":"Please ring the bell at the front door.","grammar:91389:ex:trans":"The bell rang for class.","grammar:91389:ex:structure":"ベルが＋鳴る","grammar:91389:ex:explain":"「ベル」 comes from the English word \"bell\" and can refer to a school bell, a doorbell, a bicycle bell, and so on. Use the intransitive verb 「鳴る」 when something rings, and 「鳴らす」 when someone makes it ring. A school bell is also often called 「チャイム」 in Japanese.","grammar:91389:ex:words:0:zh":"attend a class","grammar:91389:ex:words:0:note":"じゅぎょう","grammar:91389:ex:words:0:pos":"noun","grammar:91389:ex:words:1:zh":"'s","grammar:91389:ex:words:1:pos":"particle","grammar:91389:ex:words:2:zh":"bell","grammar:91389:ex:words:2:pos":"noun","grammar:91389:ex:words:3:zh":"(nominative)","grammar:91389:ex:words:3:pos":"particle","grammar:91389:ex:words:4:zh":"rang","grammar:91389:ex:words:4:note":"なりました; the masu-form past of 鳴る","grammar:91389:ex:words:4:pos":"verb","grammar:91389:ex:points:0":"ベル = bell; the sound of a bell (from \"bell\"); 「ベルが鳴る」 is a fixed expression","grammar:91389:ex:points:1":"鳴る: (a bell or phone) rings; used with 「が」","grammar:91389:ex2:trans":"Please press the doorbell at the entrance.","grammar:91389:ex2:structure":"ベルを＋押す","grammar:91389:ex2:words:0:zh":"entrance; entryway","grammar:91389:ex2:words:0:note":"げんかん","grammar:91389:ex2:words:0:pos":"noun","grammar:91389:ex2:words:1:zh":"'s","grammar:91389:ex2:words:1:pos":"particle","grammar:91389:ex2:words:2:zh":"doorbell","grammar:91389:ex2:words:2:pos":"noun","grammar:91389:ex2:words:3:zh":"(object marker)","grammar:91389:ex2:words:3:pos":"particle","grammar:91389:ex2:words:4:zh":"press","grammar:91389:ex2:words:4:note":"おして; the te-form of 押す","grammar:91389:ex2:words:4:pos":"verb","grammar:91389:ex2:words:5:zh":"please ~","grammar:91389:ex2:words:5:note":"ください; the imperative form of くださる","grammar:91389:ex2:words:5:pos":"auxiliary verb","grammar:91389:ex2:points:0":"ベルを押す: press the doorbell","grammar:91389:ex2:points:1":"玄関 = the area just inside the entrance where you take off your shoes"},"91390":{"example:91390:exzh":"I look up words I don't understand in a dictionary.","example:91390:exzh2":"I borrowed an English-Japanese dictionary at the library.","grammar:91390:ex:trans":"I look up words I don't understand in a dictionary.","grammar:91390:ex:structure":"〔thing〕は＋辞典で調べます","grammar:91390:ex:words:0:zh":"that I don't understand","grammar:91390:ex:words:0:note":"わからない; ない-form of わかる","grammar:91390:ex:words:0:pos":"verb","grammar:91390:ex:words:1:zh":"word","grammar:91390:ex:words:1:note":"ことば","grammar:91390:ex:words:1:pos":"noun","grammar:91390:ex:words:2:zh":"(topic)","grammar:91390:ex:words:2:pos":"particle","grammar:91390:ex:words:3:zh":"dictionary","grammar:91390:ex:words:3:note":"じてん","grammar:91390:ex:words:3:pos":"noun","grammar:91390:ex:words:4:zh":"with (a tool)","grammar:91390:ex:words:4:pos":"particle","grammar:91390:ex:words:5:zh":"Look up","grammar:91390:ex:words:5:note":"しらべます; the masu-form of 調べる","grammar:91390:ex:words:5:pos":"verb","grammar:91390:ex:points:0":"辞典 = dictionary; it has almost the same meaning as 「辞書（じしょ）」, but 「辞書」 is more common in conversation","grammar:91390:ex:points:1":"〔tool〕で調べる: look up using …; Japanese uses 「調べる」 for looking something up in a dictionary","grammar:91390:ex2:trans":"I borrowed an English–Japanese dictionary from the library.","grammar:91390:ex2:structure":"〔place〕で＋〔thing〕を借りました","grammar:91390:ex2:words:0:zh":"library","grammar:91390:ex2:words:0:note":"としょかん","grammar:91390:ex2:words:0:pos":"noun","grammar:91390:ex2:words:1:zh":"at / in (where the action happens)","grammar:91390:ex2:words:1:pos":"particle","grammar:91390:ex2:words:2:zh":"English–Japanese","grammar:91390:ex2:words:2:note":"えいわ","grammar:91390:ex2:words:2:pos":"noun","grammar:91390:ex2:words:3:zh":"dictionary","grammar:91390:ex2:words:3:note":"じてん","grammar:91390:ex2:words:3:pos":"noun","grammar:91390:ex2:words:4:zh":"(object marker)","grammar:91390:ex2:words:4:pos":"particle","grammar:91390:ex2:words:5:zh":"borrowed","grammar:91390:ex2:words:5:note":"かりました; past tense of the masu-form of 借りる","grammar:91390:ex2:words:5:pos":"verb","grammar:91390:ex2:points:1":"借りる = borrow; lending to someone else is 「貸す（かす）」"},"91391":{"example:91391:exzh":"I made a plan for summer vacation.","example:91391:exzh2":"Please leave the umbrella standing against the wall.","grammar:91391:ex:trans":"I made plans for summer vacation.","grammar:91391:ex:structure":"計画を＋立てる","grammar:91391:ex:explain":"「立てる」 is a transitive verb whose original meaning is to make something stand upright. By extension, it also means to make plans or set goals. 「計画を立てる」 is an essential N4 expression: where Chinese uses a verb meaning \"set,\" Japanese uses 「立てる」. The intransitive verb is 「立つ」.","grammar:91391:ex:words:0:zh":"summer vacation","grammar:91391:ex:words:0:note":"なつやすみ","grammar:91391:ex:words:0:pos":"noun","grammar:91391:ex:words:1:zh":"'s","grammar:91391:ex:words:1:pos":"particle","grammar:91391:ex:words:2:zh":"plan","grammar:91391:ex:words:2:note":"けいかく","grammar:91391:ex:words:2:pos":"noun","grammar:91391:ex:words:3:zh":"(object marker)","grammar:91391:ex:words:3:pos":"particle","grammar:91391:ex:words:4:zh":"drew up","grammar:91391:ex:words:4:note":"たてました; past tense of the masu-form of 立てる","grammar:91391:ex:words:4:pos":"verb","grammar:91391:ex:points:0":"計画を立てる = make a plan; this is a fixed expression, as is 目標を立てる (set a goal)","grammar:91391:ex:points:1":"立てる basically means \"stand something upright,\" and by extension, \"establish or set\"","grammar:91391:ex2:trans":"Please leave the umbrella standing against the wall.","grammar:91391:ex2:structure":"〔thing〕を〔place〕に＋立てておく","grammar:91391:ex2:words:0:zh":"umbrella","grammar:91391:ex2:words:0:note":"かさ","grammar:91391:ex2:words:0:pos":"noun","grammar:91391:ex2:words:1:zh":"(object marker)","grammar:91391:ex2:words:1:pos":"particle","grammar:91391:ex2:words:2:zh":"wall","grammar:91391:ex2:words:2:note":"かべ","grammar:91391:ex2:words:2:pos":"noun","grammar:91391:ex2:words:3:zh":"(the place something leans against)","grammar:91391:ex2:words:3:pos":"particle","grammar:91391:ex2:words:4:zh":"place upright","grammar:91391:ex2:words:4:note":"たてて; te-form of 立てる","grammar:91391:ex2:words:4:pos":"verb","grammar:91391:ex2:words:5:zh":"(leave it there)","grammar:91391:ex2:words:5:note":"おいて; te-form of おく","grammar:91391:ex2:words:5:pos":"auxiliary verb","grammar:91391:ex2:words:6:zh":"please ~","grammar:91391:ex2:words:6:note":"ください; the imperative form of くださる","grammar:91391:ex2:words:6:pos":"auxiliary verb","grammar:91391:ex2:points:0":"立てる: to stand something upright","grammar:91391:ex2:points:1":"〜ておく: to leave something in a particular state"},"91392":{"example:91392:exzh":"A friend gave me a present for my birthday.","example:91392:exzh2":"My mother gave me a ride to the station.","grammar:91392:ex:trans":"My friend gave me a present on my birthday.","grammar:91392:ex:structure":"〔someone else〕が＋〔something〕をくれる","grammar:91392:ex:explain":"「くれる」 focuses on direction: something comes from someone else toward “me,” so “me” is usually left unstated. If I give something to a friend, use 「あげる」. This group of giving and receiving verbs (あげる・くれる・もらう) is a key N4 topic.","grammar:91392:ex:words:0:zh":"friend","grammar:91392:ex:words:0:note":"ともだち","grammar:91392:ex:words:0:pos":"noun","grammar:91392:ex:words:1:zh":"(nominative)","grammar:91392:ex:words:1:pos":"particle","grammar:91392:ex:words:2:zh":"birthday","grammar:91392:ex:words:2:note":"たんじょうび","grammar:91392:ex:words:2:pos":"noun","grammar:91392:ex:words:3:zh":"(point in time)","grammar:91392:ex:words:3:pos":"particle","grammar:91392:ex:words:4:zh":"present","grammar:91392:ex:words:4:pos":"noun","grammar:91392:ex:words:5:zh":"(object marker)","grammar:91392:ex:words:5:pos":"particle","grammar:91392:ex:words:6:zh":"gave (me)","grammar:91392:ex:words:6:note":"くれました; past tense of the masu-form of くれる","grammar:91392:ex:words:6:pos":"verb","grammar:91392:ex:points:0":"くれる = someone else gives something to “me (or someone on my side)”; the subject is the giver","grammar:91392:ex:points:1":"Use 「あげる」 when I give to someone else, and 「くれる」 when someone else gives to me","grammar:91392:ex2:trans":"My mother took me to the station.","grammar:91392:ex2:structure":"〔person〕が＋〔verb te-form〕くれる","grammar:91392:ex2:words:0:zh":"mom","grammar:91392:ex2:words:0:note":"はは","grammar:91392:ex2:words:0:pos":"noun","grammar:91392:ex2:words:1:zh":"(nominative)","grammar:91392:ex2:words:1:pos":"particle","grammar:91392:ex2:words:2:zh":"station","grammar:91392:ex2:words:2:note":"えき","grammar:91392:ex2:words:2:pos":"noun","grammar:91392:ex2:words:3:zh":"until","grammar:91392:ex2:words:3:pos":"particle","grammar:91392:ex2:words:4:zh":"take (someone somewhere)","grammar:91392:ex2:words:4:note":"おくって; te-form of 送る","grammar:91392:ex2:words:4:pos":"verb","grammar:91392:ex2:words:5:zh":"did (for me)","grammar:91392:ex2:words:5:note":"くれました; past tense of the masu-form of くれる","grammar:91392:ex2:words:5:pos":"auxiliary verb","grammar:91392:ex2:points:0":"〜てくれる: someone does something for me; conveys gratitude","grammar:91392:ex2:points:1":"送る: to take someone somewhere; can also mean to send something"},"91393":{"example:91393:exzh":"I pickled vegetables in salt.","example:91393:exzh2":"I'll leave the dirty shirt soaking in water.","grammar:91393:ex:trans":"I pickled vegetables in salt.","grammar:91393:ex:structure":"〔food〕を＋〔seasoning〕で漬ける","grammar:91393:ex:explain":"「漬ける」 mainly means to pickle food; the word 「漬物」 for the pickled vegetables common in Japan comes from this verb. It also means “to soak in liquid” (see the second sentence). Here, 「で」 marks the ingredient used for pickling.","grammar:91393:ex:words:0:zh":"vegetables","grammar:91393:ex:words:0:note":"やさい","grammar:91393:ex:words:0:pos":"noun","grammar:91393:ex:words:1:zh":"(object marker)","grammar:91393:ex:words:1:pos":"particle","grammar:91393:ex:words:2:zh":"salt","grammar:91393:ex:words:2:note":"しお","grammar:91393:ex:words:2:pos":"noun","grammar:91393:ex:words:3:zh":"with (ingredients)","grammar:91393:ex:words:3:pos":"particle","grammar:91393:ex:words:4:zh":"pickled","grammar:91393:ex:words:4:note":"つけました; past tense of the masu-form of 漬ける","grammar:91393:ex:words:4:pos":"verb","grammar:91393:ex:points:0":"漬ける = to pickle food in salt, vinegar, or soy sauce; the resulting pickles are called 「漬物（つけもの）」","grammar:91393:ex:points:1":"Use 「で」 for the ingredient used","grammar:91393:ex2:trans":"Soak the dirty shirt in water.","grammar:91393:ex2:structure":"〔something〕を水に＋漬けておく","grammar:91393:ex2:words:0:zh":"dirty","grammar:91393:ex2:words:0:note":"よごれた; ta-form of 汚れる","grammar:91393:ex2:words:0:pos":"verb","grammar:91393:ex2:words:1:zh":"shirt","grammar:91393:ex2:words:1:pos":"noun","grammar:91393:ex2:words:2:zh":"(object marker)","grammar:91393:ex2:words:2:pos":"particle","grammar:91393:ex2:words:3:zh":"water","grammar:91393:ex2:words:3:note":"みず","grammar:91393:ex2:words:3:pos":"noun","grammar:91393:ex2:words:4:zh":"(the place something is soaked in)","grammar:91393:ex2:words:4:pos":"particle","grammar:91393:ex2:words:5:zh":"to soak","grammar:91393:ex2:words:5:note":"つけて; te-form of 漬ける","grammar:91393:ex2:words:5:pos":"verb","grammar:91393:ex2:words:6:zh":"leave (in advance)","grammar:91393:ex2:words:6:note":"okimasu; masu-form of おく","grammar:91393:ex2:words:6:pos":"auxiliary verb","grammar:91393:ex2:points:0":"〜を水に漬ける: to soak in water; this meaning is also often written as 「浸ける」","grammar:91393:ex2:points:1":"汚れたシャツ: a dirty shirt; the ta-form modifies a noun"},"91394":{"example:91394:exzh":"Please write with a black or blue pen.","example:91394:exzh2":"Please contact me by phone or email.","grammar:91394:ex:trans":"Please write with a black or blue pen.","grammar:91394:ex:structure":"〔A〕または〔B〕","grammar:91394:ex:explain":"「または」 means “choose either A or B.” It is relatively formal and often appears in exam instructions and instructions for filling out forms. In everyday speech, it can be replaced with 「か」 or 「それか」. 「青」 means blue in Japanese, but is also used for a green traffic light.","grammar:91394:ex:words:0:zh":"black","grammar:91394:ex:words:0:note":"くろ","grammar:91394:ex:words:0:pos":"noun","grammar:91394:ex:words:1:zh":"or","grammar:91394:ex:words:1:pos":"conjunction","grammar:91394:ex:words:2:zh":"blue","grammar:91394:ex:words:2:note":"あお","grammar:91394:ex:words:2:pos":"noun","grammar:91394:ex:words:3:zh":"'s","grammar:91394:ex:words:3:pos":"particle","grammar:91394:ex:words:4:zh":"pen","grammar:91394:ex:words:4:pos":"noun","grammar:91394:ex:words:5:zh":"with (a tool)","grammar:91394:ex:words:5:pos":"particle","grammar:91394:ex:words:6:zh":"write","grammar:91394:ex:words:6:note":"かいて；the te-form of 書く","grammar:91394:ex:words:6:pos":"verb","grammar:91394:ex:words:7:zh":"please ~","grammar:91394:ex:words:7:note":"ください; the imperative form of くださる","grammar:91394:ex:words:7:pos":"auxiliary verb","grammar:91394:ex:points:0":"または = or; mainly used in formal writing, such as rules and instruction manuals","grammar:91394:ex:points:1":"「か」 is more common in speech: 黒か青のペン","grammar:91394:ex2:trans":"Please contact me by phone or email.","grammar:91394:ex2:structure":"〔A〕、または〔B〕で＋〜","grammar:91394:ex2:words:0:zh":"phone call","grammar:91394:ex2:words:0:note":"でんわ","grammar:91394:ex2:words:0:pos":"noun","grammar:91394:ex2:words:1:zh":"or","grammar:91394:ex2:words:1:pos":"conjunction","grammar:91394:ex2:words:2:zh":"email","grammar:91394:ex2:words:2:pos":"noun","grammar:91394:ex2:words:3:zh":"by (means)","grammar:91394:ex2:words:3:pos":"particle","grammar:91394:ex2:words:4:zh":"contact","grammar:91394:ex2:words:4:note":"れんらくして; te-form of 連絡する","grammar:91394:ex2:words:4:pos":"verb","grammar:91394:ex2:words:5:zh":"please ~","grammar:91394:ex2:words:5:note":"ください; the imperative form of くださる","grammar:91394:ex2:words:5:pos":"auxiliary verb","grammar:91394:ex2:points:0":"または: lists two methods to choose from","grammar:91394:ex2:points:1":"連絡する: to contact; 「で」 marks the method"},"91395":{"example:91395:exzh":"Please deliver this document to the teacher.","example:91395:exzh2":"I turned in the wallet I found at the police box.","grammar:91395:ex:trans":"Please deliver this document to the teacher.","grammar:91395:ex:structure":"〔something〕を＋〔person〕に届ける","grammar:91395:ex:explain":"「届ける」 means to deliver something to its destination, either personally or through someone else, with an emphasis on ensuring it arrives. In contrast, 「送る（send off）」 focuses on sending it out. 「に」 marks the recipient.","grammar:91395:ex:words:0:zh":"this","grammar:91395:ex:words:0:pos":"pre-noun adjectival","grammar:91395:ex:words:1:zh":"documents","grammar:91395:ex:words:1:note":"しょるい","grammar:91395:ex:words:1:pos":"noun","grammar:91395:ex:words:2:zh":"(object marker)","grammar:91395:ex:words:2:pos":"particle","grammar:91395:ex:words:3:zh":"teacher","grammar:91395:ex:words:3:note":"せんせい","grammar:91395:ex:words:3:pos":"noun","grammar:91395:ex:words:4:zh":"to give (to someone)","grammar:91395:ex:words:4:pos":"particle","grammar:91395:ex:words:5:zh":"deliver","grammar:91395:ex:words:5:note":"とどけて; te-form of 届ける","grammar:91395:ex:words:5:pos":"verb","grammar:91395:ex:words:6:zh":"please ~","grammar:91395:ex:words:6:note":"ください; the imperative form of くださる","grammar:91395:ex:words:6:pos":"auxiliary verb","grammar:91395:ex:points:0":"届ける = to deliver something into someone's hands; the focus is on its arrival","grammar:91395:ex:points:1":"Use 「届く」 when something arrives: 荷物が届いた (The package arrived)","grammar:91395:ex2:trans":"I took the wallet I found to the police box.","grammar:91395:ex2:structure":"〔something〕を交番に＋届ける","grammar:91395:ex2:words:0:zh":"found","grammar:91395:ex2:words:0:note":"ひろった; ta-form of 拾う","grammar:91395:ex2:words:0:pos":"verb","grammar:91395:ex2:words:1:zh":"wallet","grammar:91395:ex2:words:1:note":"さいふ","grammar:91395:ex2:words:1:pos":"noun","grammar:91395:ex2:words:2:zh":"(object marker)","grammar:91395:ex2:words:2:pos":"particle","grammar:91395:ex2:words:3:zh":"police box","grammar:91395:ex2:words:3:note":"こうばん","grammar:91395:ex2:words:3:pos":"noun","grammar:91395:ex2:words:4:zh":"to (the delivery destination)","grammar:91395:ex2:words:4:pos":"particle","grammar:91395:ex2:words:5:zh":"handed in","grammar:91395:ex2:words:5:note":"とどけました; past tense of the masu-form of 届ける","grammar:91395:ex2:words:5:pos":"verb","grammar:91395:ex2:points:0":"交番に届ける: to hand something in at a police box (when you find a lost item); can also be used for reporting an incident to the police","grammar:91395:ex2:points:1":"拾う: to pick up; the ta-form modifies a noun: 拾った財布"},"91396":{"example:91396:exzh":"The view from the top of the mountain is beautiful.","example:91396:exzh2":"I can see the ocean from the window.","grammar:91396:ex:trans":"The view from the mountain is beautiful.","grammar:91396:ex:structure":"〔place〕からの景色は＋きれいです","grammar:91396:ex:explain":"「景色」 is pronounced 「けしき」, not 「けいしょく」; memorize the reading as a whole. It refers to scenery before your eyes, such as mountains, the sea, or city views, and is often used with 「きれい」 and 「すばらしい」. 「山の上からの景色」 means “the view from the top of the mountain.”","grammar:91396:ex:words:0:zh":"mountain","grammar:91396:ex:words:0:note":"やま","grammar:91396:ex:words:0:pos":"noun","grammar:91396:ex:words:1:zh":"'s","grammar:91396:ex:words:1:pos":"particle","grammar:91396:ex:words:2:zh":"on top of","grammar:91396:ex:words:2:note":"うえ","grammar:91396:ex:words:2:pos":"noun","grammar:91396:ex:words:3:zh":"from","grammar:91396:ex:words:3:pos":"particle","grammar:91396:ex:words:4:zh":"'s","grammar:91396:ex:words:4:pos":"particle","grammar:91396:ex:words:5:zh":"scenery","grammar:91396:ex:words:5:note":"けしき","grammar:91396:ex:words:5:pos":"noun","grammar:91396:ex:words:6:zh":"(topic)","grammar:91396:ex:words:6:pos":"particle","grammar:91396:ex:words:7:zh":"beautiful","grammar:91396:ex:words:7:pos":"na-adjective","grammar:91396:ex:words:8:zh":"is (polite form)","grammar:91396:ex:words:8:pos":"copula","grammar:91396:ex:points:0":"景色 = natural scenery you can see; 「けしき」 is an irregular reading","grammar:91396:ex:points:1":"〜からの景色: the view from ~; 「から」＋「の」 connects to a noun","grammar:91396:ex2:trans":"You can see the sea from the window.","grammar:91396:ex2:structure":"〔place〕から＋〔something〕が見えます","grammar:91396:ex2:words:0:zh":"window","grammar:91396:ex2:words:0:note":"まど","grammar:91396:ex2:words:0:pos":"noun","grammar:91396:ex2:words:1:zh":"from","grammar:91396:ex2:words:1:pos":"particle","grammar:91396:ex2:words:2:zh":"sea","grammar:91396:ex2:words:2:note":"うみ","grammar:91396:ex2:words:2:pos":"noun","grammar:91396:ex2:words:3:zh":"'s","grammar:91396:ex2:words:3:pos":"particle","grammar:91396:ex2:words:4:zh":"scenery","grammar:91396:ex2:words:4:note":"けしき","grammar:91396:ex2:words:4:pos":"noun","grammar:91396:ex2:words:5:zh":"(nominative)","grammar:91396:ex2:words:5:pos":"particle","grammar:91396:ex2:words:6:zh":"to be visible","grammar:91396:ex2:words:6:note":"みえます; the masu-form of 見える","grammar:91396:ex2:words:6:pos":"verb","grammar:91396:ex2:points:0":"海の景色: a view of the sea","grammar:91396:ex2:points:1":"見える: to be visible without deliberately looking; 「が」 marks what is visible"},"91397":{"example:91397:exzh":"Groceries are sold on the first basement floor.","example:91397:exzh2":"On weekends I buy a week's worth of groceries.","grammar:91397:ex:trans":"Food is sold on the first basement floor.","grammar:91397:ex:structure":"〔product〕は＋〔place〕で売っています","grammar:91397:ex:explain":"「食料品」 refers to various foods bought for cooking or eating. It is more formal than 「食べ物」 and often appears on store signs. The basement floors of Japanese department stores usually contain the 「食料品売り場」, commonly called 「デパ地下」.","grammar:91397:ex:words:0:zh":"food","grammar:91397:ex:words:0:note":"しょくりょうひん","grammar:91397:ex:words:0:pos":"noun","grammar:91397:ex:words:1:zh":"(topic)","grammar:91397:ex:words:1:pos":"particle","grammar:91397:ex:words:2:zh":"basement","grammar:91397:ex:words:2:note":"ちか","grammar:91397:ex:words:2:pos":"noun","grammar:91397:ex:words:3:zh":"first floor","grammar:91397:ex:words:3:note":"いっかい","grammar:91397:ex:words:3:pos":"noun","grammar:91397:ex:words:4:zh":"at / in (where the action happens)","grammar:91397:ex:words:4:pos":"particle","grammar:91397:ex:words:5:zh":"sell","grammar:91397:ex:words:5:note":"うって; te-form of 売る","grammar:91397:ex:words:5:pos":"verb","grammar:91397:ex:words:6:zh":"(continuing) to do ~","grammar:91397:ex:words:6:note":"います; the masu-form of いる","grammar:91397:ex:words:6:pos":"auxiliary verb","grammar:91397:ex:points:0":"食料品 = groceries and ingredients (edible items such as meat, vegetables, and bread); common in supermarkets and department stores","grammar:91397:ex:points:1":"〜で売っています: is sold at ~; 「は」 presents the product as the topic","grammar:91397:ex2:trans":"On weekends, I buy a week's worth of groceries.","grammar:91397:ex2:structure":"〔period of time〕分の＋食料品を買います","grammar:91397:ex2:words:0:zh":"weekend","grammar:91397:ex2:words:0:note":"しゅうまつ","grammar:91397:ex2:words:0:pos":"noun","grammar:91397:ex2:words:1:zh":"(point in time)","grammar:91397:ex2:words:1:pos":"particle","grammar:91397:ex2:words:2:zh":"one week","grammar:91397:ex2:words:2:note":"いっしゅうかん","grammar:91397:ex2:words:2:pos":"noun","grammar:91397:ex2:words:3:zh":"~'s worth","grammar:91397:ex2:words:3:note":"ぶん","grammar:91397:ex2:words:3:pos":"suffix","grammar:91397:ex2:words:4:zh":"'s","grammar:91397:ex2:words:4:pos":"particle","grammar:91397:ex2:words:5:zh":"ingredients","grammar:91397:ex2:words:5:note":"しょくりょうひん","grammar:91397:ex2:words:5:pos":"noun","grammar:91397:ex2:words:6:zh":"(object marker)","grammar:91397:ex2:words:6:pos":"particle","grammar:91397:ex2:words:7:zh":"buy","grammar:91397:ex2:words:7:note":"かいます; the masu-form of 買う","grammar:91397:ex2:words:7:pos":"verb","grammar:91397:ex2:points:0":"一週間分の食料品: a week's worth of groceries"},"91398":{"example:91398:exzh":"What he says is always exaggerated.","example:91398:exzh2":"I went a little over budget.","grammar:91398:ex:trans":"He always exaggerates when he talks.","grammar:91398:ex:structure":"〔noun〕は＋オーバーです","grammar:91398:ex:explain":"「オーバー」 means “exaggerated” here, describing speech or reactions that go too far. It can also mean “exceed” (see the second sentence), or be an older word for an overcoat (オーバーコート). The native Japanese synonym is 「大げさ」.","grammar:91398:ex:words:0:zh":"he","grammar:91398:ex:words:0:note":"かれ","grammar:91398:ex:words:0:pos":"pronoun","grammar:91398:ex:words:1:zh":"'s","grammar:91398:ex:words:1:pos":"particle","grammar:91398:ex:words:2:zh":"talk; story","grammar:91398:ex:words:2:note":"はなし","grammar:91398:ex:words:2:pos":"noun","grammar:91398:ex:words:3:zh":"(topic)","grammar:91398:ex:words:3:pos":"particle","grammar:91398:ex:words:4:zh":"always","grammar:91398:ex:words:4:pos":"adverb","grammar:91398:ex:words:5:zh":"exaggerated","grammar:91398:ex:words:5:pos":"na-adjective","grammar:91398:ex:words:6:zh":"is (polite form)","grammar:91398:ex:words:6:pos":"copula","grammar:91398:ex:points:0":"オーバー = exaggerated (from “over”); 「オーバーな言い方」 = an exaggerated way of saying something","grammar:91398:ex:points:1":"You can also say 「大げさ（おおげさ）」, which has the same meaning","grammar:91398:ex2:trans":"I went slightly over budget.","grammar:91398:ex2:structure":"〔quantity〕を＋オーバーする","grammar:91398:ex2:words:0:zh":"budget","grammar:91398:ex2:words:0:note":"よさん","grammar:91398:ex2:words:0:pos":"noun","grammar:91398:ex2:words:1:zh":"(object marker)","grammar:91398:ex2:words:1:pos":"particle","grammar:91398:ex2:words:2:zh":"a little","grammar:91398:ex2:words:2:note":"すこし","grammar:91398:ex2:words:2:pos":"adverb","grammar:91398:ex2:words:3:zh":"exceeded","grammar:91398:ex2:words:3:note":"おーばーしました; past tense of the masu-form of オーバーする","grammar:91398:ex2:words:3:pos":"verb","grammar:91398:ex2:points:0":"オーバーする: to exceed (a budget, time limit, or weight limit)","grammar:91398:ex2:points:1":"A noun becomes a verb by adding する: オーバーする"},"91399":{"example:91399:exzh":"My older brother is a civil servant at city hall.","example:91399:exzh2":"I want to be a civil servant in the future.","grammar:91399:ex:trans":"My older brother is a civil servant at city hall.","grammar:91399:ex:structure":"〔person〕は＋〔government agency〕の公務員です","grammar:91399:ex:explain":"「公務員」 has the same meaning as in Chinese: someone who works for the national or a local government. 「市役所の公務員」 means a civil servant who works at city hall. Use 「〜は〜です」 to state someone's occupation.","grammar:91399:ex:words:0:zh":"older brother","grammar:91399:ex:words:0:note":"あに","grammar:91399:ex:words:0:pos":"noun","grammar:91399:ex:words:1:zh":"(topic)","grammar:91399:ex:words:1:pos":"particle","grammar:91399:ex:words:2:zh":"city hall","grammar:91399:ex:words:2:note":"しやくしょ","grammar:91399:ex:words:2:pos":"noun","grammar:91399:ex:words:3:zh":"'s","grammar:91399:ex:words:3:pos":"particle","grammar:91399:ex:words:4:zh":"civil servant","grammar:91399:ex:words:4:note":"こうむいん","grammar:91399:ex:words:4:pos":"noun","grammar:91399:ex:words:5:zh":"is (polite form)","grammar:91399:ex:words:5:pos":"copula","grammar:91399:ex:points:0":"公務員 = someone who works for a government agency; pronounced 「こうむいん」","grammar:91399:ex:points:1":"市役所 = city hall (a municipal government office)","grammar:91399:ex2:trans":"I want to become a civil servant in the future.","grammar:91399:ex2:structure":"将来は＋〔occupation〕になりたいです","grammar:91399:ex2:words:0:zh":"future","grammar:91399:ex2:words:0:note":"しょうらい","grammar:91399:ex2:words:0:pos":"noun","grammar:91399:ex2:words:1:zh":"(topic)","grammar:91399:ex2:words:1:pos":"particle","grammar:91399:ex2:words:2:zh":"civil servant","grammar:91399:ex2:words:2:note":"こうむいん","grammar:91399:ex2:words:2:pos":"noun","grammar:91399:ex2:words:3:zh":"(the resulting color)","grammar:91399:ex2:words:3:pos":"particle","grammar:91399:ex2:words:4:zh":"want to become","grammar:91399:ex2:words:4:note":"なりたい；なる＋たい","grammar:91399:ex2:words:4:pos":"verb","grammar:91399:ex2:words:5:zh":"is (polite form)","grammar:91399:ex2:words:5:pos":"copula","grammar:91399:ex2:points:0":"〔occupation〕になりたい: to want to become ~","grammar:91399:ex2:points:1":"〜になる: to become ~"}};